/* Layer 3 - REGULATED. Blocked unless the seller is verified for that category.
   (Verification is an operator action; unverified sellers simply can't list these.) */
const MKT_REGULATED = {
  'Financial & investment advice': ['investment advice','financial advice','stock picks','trading signals','forex signals','crypto signals','guaranteed returns','portfolio management'],
  'Medical & health claims': ['medical advice','cure cancer','miracle cure','diagnose','prescription','treatment plan','weight loss guaranteed'],
  'Legal advice': ['legal advice','legal representation','sue someone','lawsuit template guaranteed'],
  'Adult (18+)': ['adult content','nsfw','erotica','porn'],
};

/* Layer 4 - RISK SIGNALS. Not blocked, but the listing is held for review. */
const MKT_RISK_SIGNALS = [
  'hack','exploit','crack','bypass','scrape','scraper','bot farm','automation bot','mass dm','spam',
  'password','credential','proxy list','vpn crack','account generator','otp bypass','2fa bypass',
  'crypto','forex','trading bot','arbitrage','airdrop','presale','pump','nft flip',
  'guaranteed','get rich','passive income guaranteed','make money fast','mlm','downline','recruit',
  'unlimited','unlocked','premium free','free trial abuse',
];

/* Screen a listing. Returns a decision object. */
function _marketScreen(item, sellerVerifiedFor) {
  const fields = [item.title, item.desc, item.cat, item.text,
    Array.isArray(item.files) ? item.files.map(f => f && f.name).join(' ') : ''];
  const raw = fields.map(x => String(x || '')).join(' ');
  const n = _mktNormalize(raw);

  const hit = (term) => {
    const t = _mktNormalize(term);
    // word-ish boundary on the spaced form, plus a squeezed-form containment check
    const esc = t.spaced.trim().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    if (new RegExp('(^| )' + esc + '( |$)', 'i').test(n.spaced)) return true;
    if (t.squeezed.length >= 6 && n.squeezed.includes(t.squeezed)) return true;
    return false;
  };

  // Layer 2 - prohibited
  for (const [category, terms] of Object.entries(MKT_PROHIBITED)) {
    for (const term of terms) {
      if (hit(term)) {
        return { ok: false, action: 'blocked', category, term,
          reason: 'This listing appears to involve prohibited content (' + category + '). It cannot be published. Selling this violates the Marketplace Terms and may result in losing selling access.' };
      }
    }
  }
  // Layer 3 - regulated
  for (const [category, terms] of Object.entries(MKT_REGULATED)) {
    for (const term of terms) {
      if (hit(term)) {
        const verified = Array.isArray(sellerVerifiedFor) && sellerVerifiedFor.includes(category);
        if (!verified) {
          return { ok: false, action: 'needs_verification', category, term,
            reason: category + ' listings require a verified seller account. Apply for verification to list in this category.' };
        }
      }
    }
  }
  // Layer 4 - risk signals
  const signals = [];
  for (const term of MKT_RISK_SIGNALS) { if (hit(term)) signals.push(term); }
  if (signals.length) {
    return { ok: true, action: 'held_for_review', signals: signals.slice(0, 5),
      reason: 'Your listing is live but flagged for review. If it complies with the rules it stays up; if not, it will be removed.' };
  }
  return { ok: true, action: 'approved' };
}

/* http(s) only, and short. Anything else - javascript:, data:, vbscript: - is
   dropped rather than stored. */
function _safeHttpUrl(u) {
  const raw = String(u == null ? '' : u).trim().slice(0, 500);
  if (!raw) return undefined;
  try {
    const parsed = new URL(raw);
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return undefined;
    return parsed.toString().slice(0, 500);
  } catch (e) { return undefined; }
}

async function marketPublish(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'sign in to publish' }, 401);
  // Guard against listing spam - a handful a minute, a sane cap per day.
  const blocked = await guardAction(env, `mktpub:${user.email}`, 5, 50, 'listings');
  if (blocked) return blocked;
  const item = await request.json().catch(() => ({}));
  const title = String(item.title || '').slice(0, 100).trim();
  if (!title) return json({ error: 'title required' }, 400);

  // ── Trust & Safety: seller standing ──────────────────────────
  const standing = (await DB.get(env, 'seller', user.email)) || { strikes: 0, banned: false, verifiedFor: [] };
  if (standing.banned) {
    return json({ error: 'Your selling access has been suspended for repeated policy violations. Contact support to appeal.', code: 'seller_suspended' }, 403);
  }

  // ── Automated content review (server-side = cannot be bypassed) ──
  const screen = _marketScreen(item, standing.verifiedFor);
  if (!screen.ok) {
    if (screen.action === 'blocked') {
      /* Under the lock: moderation writes this record too, and a strike lost
         to a concurrent write is a seller who should be suspended and is not.
         Counted INSIDE, from the stored value rather than from the copy read
         at the top of this handler, so two violations landing together both
         count instead of the second overwriting the first with the same
         number. What the reply says comes back out of the lock, so the person
         is told the strike they actually have. */
      const after = await _withKind(env, 'seller', user.email, (fresh) => {
        if(!fresh) return null;
        fresh.strikes = (fresh.strikes || 0) + 1;
        fresh.lastViolation = { category: screen.category, at: Date.now() };
        if(fresh.strikes >= 3) fresh.banned = true;      // 3 strikes = suspended
        return { strikes: fresh.strikes, banned: !!fresh.banned };
      }, { strikes: 0, banned: false, verifiedFor: [] });
      standing.strikes = (after && after.strikes) || ((standing.strikes || 0) + 1);
      standing.banned = !!(after && after.banned);
      audit(env, 'market_blocked', { by: user.email, title, category: screen.category, term: screen.term, strikes: standing.strikes });
      return json({
        error: screen.reason, code: 'policy_violation', category: screen.category,
        strikes: standing.strikes, suspended: !!standing.banned,
      }, 422);
    }
    // needs verification
    audit(env, 'market_needs_verification', { by: user.email, title, category: screen.category });
    return json({ error: screen.reason, code: 'needs_verification', category: screen.category }, 422);
  }
  const kind = ['prompt', 'crew', 'agent', 'integration', 'workflow', 'guide', 'bundle'].includes(item.kind) ? item.kind : 'prompt';
  // price: 0 = free; otherwise whole dollars, $1..$999
  let price = Math.round(Number(item.price) || 0);
  if (price < 0) price = 0;
  if (price > 999) price = 999;
  const body = String(item.text || '').slice(0, 20000);
  // AMV-only content guard: reject listings that reference other AI brands.
  const blob = (title + ' ' + (item.desc || '') + ' ' + body).toLowerCase();
  const banned = ['claude', 'anthropic', 'openai', 'chatgpt', 'gpt-4', 'gpt-5', 'gemini', 'copilot', 'grok', 'llama', 'mistral', 'perplexity'];
  const hit = banned.find(b => blob.includes(b));
  if (hit) return json({ error: 'Listings must be AMV-only - remove references to other AI products (' + hit + ').' }, 400);
  // File attachments: store metadata + data. NOTE: KV caps values at 25MB - for
  // large media, production should upload to R2 and store only the URL here.
  // AMV-028: bound inline file payloads by DECODED byte size (not just string
  // length), per-file and in aggregate, so a listing can't smuggle a huge blob or
  // a decompression bomb into the record (which would amplify every read, write,
  // backup and response). Larger deliverables must be hosted and linked by URL.
  const MAX_FILE_B64 = 700 * 1024;             // ~512 KB decoded per file
  const MAX_FILES_B64_TOTAL = 3 * 1024 * 1024; // ~2.2 MB decoded across all files
  const rawFiles = Array.isArray(item.files) ? item.files.slice(0, 20) : [];
  let filesTotal = 0;
  for (const f of rawFiles) {
    const dlen = (f && typeof f.data === 'string') ? f.data.length : 0;
    if (dlen > MAX_FILE_B64) return json({ error: 'a file is too large to attach inline - host it and share a download link instead' }, 413);
    filesTotal += dlen;
  }
  if (filesTotal > MAX_FILES_B64_TOTAL) return json({ error: 'the attached files are too large in total - keep them under ~2MB or link them' }, 413);
  let files = rawFiles.map(f => ({
    name: String(f.name || 'file').slice(0, 160),
    type: String(f.type || 'application/octet-stream').slice(0, 100),
    size: Math.max(0, Number(f.size) || 0),
    data: typeof f.data === 'string' ? f.data : '',
    /* AMV-096: scheme-checked at the door. Nothing renders this as a link
       today, so it is not a live hole - but storing an attacker-chosen URL and
       trusting a future renderer not to make it an href is how stored XSS gets
       introduced by an unrelated change months later. Validate where it enters,
       not where it is used. */
    url: _safeHttpUrl(f.url),
  }));
  if (!body && !files.length && !(Array.isArray(item.crew) && item.crew.length)) {
    return json({ error: 'add a deliverable: text, a crew, or at least one file' }, 400);
  }
  const clean = {
    id: 'usr_' + crypto.randomUUID().replace(/-/g,''),
    kind, title,
    cat: String(item.cat || 'Community').slice(0, 40),
    desc: String(item.desc || '').slice(0, 280),
    text: body,
    crew: Array.isArray(item.crew) ? item.crew.slice(0, 8) : undefined,
    files,
    // icon is rendered unescaped on the client, so store an emoji/short-text
    // only - reject any markup outright (never a truncated tag fragment).
    icon: (function(ic){ ic = String(ic == null ? '\u2728' : ic); return ic.indexOf('<') >= 0 ? '\u2728' : (ic.slice(0, 8) || '\u2728'); })(),
    price,
    author: (user.name || user.email.split('@')[0]).slice(0, 40),
    authorEmail: user.email,
    installs: 0,
    sales: 0,
    views: 0,
    status: screen.action === 'held_for_review' ? 'under_review' : 'active',
    review: screen.action === 'held_for_review' ? { signals: screen.signals || [], at: Date.now() } : undefined,
    createdAt: Date.now(),
  };
  await env.AMV_KV.put(`market:${clean.id}`, JSON.stringify(clean));
  await _sellerIndexAdd(env, user.email, clean.id);
  await _marketCacheBust(env);
  if (screen.action === 'held_for_review') {
    audit(env, 'market_held_for_review', { id: clean.id, by: user.email, signals: screen.signals });
  }
  audit(env, 'market_publish', { id: clean.id, by: user.email, price, files: files.length, status: clean.status });
  return json({ ok: true, item: _publicListing(clean), review: screen.action === 'held_for_review' ? screen.reason : undefined });
}

/* Strip the deliverable (text/crew/file DATA) from a paid listing so it can't
   be read for free from the public catalog. File NAMES stay as a teaser.
   Free items keep their content inline. */
function _publicListing(it) {
  if (!it.price || it.price <= 0) return it;
  const { text, crew, files, ...rest } = it;
  const teaser = Array.isArray(files) ? files.map(f => ({ name: f.name, type: f.type, size: f.size })) : [];
  return { ...rest, files: teaser, locked: true };
}

async function marketInstall(request, env) {
  /* AMV-096: installs drive ranking, so an install has to cost something. It
     used to be unauthenticated and limited only per IP, which means a rented
     address pool could rank anything to the top of the marketplace. Now it
     takes an account, and counts ONCE per account per listing - a number that
     can be manufactured is not a ranking signal, it is an advertisement. */
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'sign in to install' }, 401);
  const iip = request.headers.get('CF-Connecting-IP') || request.headers.get('X-Forwarded-For') || 'noip';
  const irl = await limitAction(env, `mktinstall:${iip}`, 30, 300);
  if (!irl.ok) return json({ ok: true, throttled: true });
  const { id } = await request.json().catch(() => ({}));
  if (!id || !/^[a-z0-9_]+$/i.test(id)) return json({ error: 'bad id' }, 400);
  // Second and later installs by the same account are honoured, but not counted.
  const first = await _claimOnce(env, 'mktinst', `${user.email}:${id}`, CLAIM_ONCE_TTL_S);
  if (!first) return json({ ok: true, counted: false });
  const raw = await env.AMV_KV.get(`market:${id}`);
  if (raw) {
    try {
      JSON.parse(raw);                       // still a listing, not a stray key
      await _withKV(env, 'market', id, (rec) => {
        if (rec) rec.installs = (rec.installs || 0) + 1;
      });
    } catch {}
  }
  return json({ ok: true, counted: true });
}

/* =====================================================================
   MARKETPLACE ECONOMY - paid listings, 80/20 split, seller balance.
   ---------------------------------------------------------------------
   Money flow: buyer pays the full price through the SAME Stripe checkout
   used for plans (mode=payment, one-time). On checkout.session.completed
   the webhook calls _creditSale(): the buyer is granted the item, the
   seller's balance is credited 80%, the platform keeps 20%. Sellers see
   their balance and can request a withdrawal (extraction) of it.
   Records:
     purchases:<buyer>      -> [ {id, title, kind, price, ts} ]   (what they own)
     entitleitem:<buyer>:<id> -> '1'                              (fast ownership check)
     wallet:<seller>        -> { balance, lifetime, currency }    (earnings ledger)
     wallet_tx:<seller>     -> [ {type, amount, item, ts, ...} ]  (ledger history)
     withdraw:<id>          -> { seller, amount, status, ts }     (extraction requests)
   ===================================================================== */
const MARKET_PLATFORM_FEE = 0.20;   // you keep 20%, seller gets 80%
const MARKET_MIN_WITHDRAW = 10;     // minimum balance (USD) to extract

async function _getListing(env, id) {
  if (!id || !/^[a-z0-9_]+$/i.test(id)) return null;
  const raw = await env.AMV_KV.get(`market:${id}`);
  if (!raw) return null;
  try { return JSON.parse(raw); } catch { return null; }
}

/* ONE SELLER'S LISTINGS, WITHOUT READING EVERYBODY'S.

   marketMyListings walked every `market:` key in the product and did a full
   read of each one, keeping the handful whose authorEmail matched. With four
   listings that is four reads. With four hundred thousand it is four hundred
   thousand reads, on a page one seller opened to see their own three items -
   and it had no cap at all, so it did not stop, it just got slower and more
   expensive every time anybody else published anything.

   An index is the whole fix: the author of a listing never changes, so the
   membership is decided once at publish and once at removal.

   BUILT ON FIRST USE rather than migrated. `built` is what separates "this
   seller has no listings" from "nobody has ever asked", so an empty index is
   not rebuilt on every page load - which is the bug this exists to fix,
   rewritten as a cache miss. */
const MKT_SCAN_MAX = 20000;      // keys, not results: a bound has to bound the work
/* AND A BOUND ON THE INDEX ITSELF.

   These indexes were added to stop three pages reading the whole store, and
   they went in without a cap - which trades an unbounded READ for an unbounded
   WRITE, and the write is the worse one. Both records are written on every
   publish and every message, and KV has a hard ceiling on a value: past it
   every write fails, so the person stops being able to publish or send
   anything at all. The read they replaced was only slow.

   Most recent last, capped. An inbox that holds your most recent few thousand
   conversations is how every inbox works, and this bounds the INDEX, not the
   data - every listing and every message is still exactly where it was. */
const MKT_INDEX_MAX = 4000;

async function _sellerListingIds(env, email) {
  const em = String(email || '').toLowerCase();
  if (!em) return { ids: [], built: 0, scanned: 0, truncated: false };
  try {
    const raw = await env.AMV_KV.get(`mktmine:${em}`);
    if (raw) {
      const r = JSON.parse(raw);
      if (r && r.built) return { ids: Array.isArray(r.ids) ? r.ids : [], built: r.built, scanned: 0, truncated: false };
    }
  } catch (e) { /* unreadable index: rebuild it below rather than fail the page */ }

  /* The old behaviour, ONCE, to seed the index for listings that predate it. */
  const ids = [];
  let cursor, scanned = 0, truncated = false;
  do {
    const page = await env.AMV_KV.list({ prefix: 'market:', cursor, limit: 1000 });
    for (const k of (page.keys || [])) {
      scanned++;
      const raw = await env.AMV_KV.get(k.name);
      if (!raw) continue;
      try { const it = JSON.parse(raw); if (it && it.authorEmail === em) ids.push(it.id || k.name.slice(7)); } catch (e) {}
    }
    cursor = page.list_complete ? undefined : page.cursor;
    if (cursor && scanned >= MKT_SCAN_MAX) { truncated = true; break; }
  } while (cursor);

  /* A backfill that stopped short must NOT be written as if it were complete -
     the seller would lose the listings past the cap permanently, which is
     worse than the slow page it replaces. */
  if (!truncated) {
    try { await env.AMV_KV.put(`mktmine:${em}`, JSON.stringify({ ids: ids.slice(-MKT_INDEX_MAX), built: Date.now() })); } catch (e) {}
  } else {
    audit(env, 'seller_index_partial', { email: em, scanned });
  }
  return { ids, built: 0, scanned, truncated };
}

/* Keep it true. Called where a listing is created and where it is removed -
   the only two moments its author changes. */
async function _sellerIndexAdd(env, email, id) {
  const em = String(email || '').toLowerCase();
  if (!em || !id) return;
  try {
    await _withKV(env, 'mktmine', em, (r) => {
      r.ids = Array.isArray(r.ids) ? r.ids : [];
      if (!r.ids.includes(id)) r.ids.push(id);
      if (r.ids.length > MKT_INDEX_MAX) r.ids = r.ids.slice(-MKT_INDEX_MAX);
      /* Marked built either way: an index that gains a listing is an index,
         and leaving `built` unset would send the next read back to the scan. */
      r.built = r.built || Date.now();
      return r;
    }, { ids: [], built: 0 });
  } catch (e) { audit(env, 'seller_index_add_failed', { email: em, id, error: String((e && e.message) || e) }); }
}
async function _sellerIndexRemove(env, email, id) {
  const em = String(email || '').toLowerCase();
  if (!em || !id) return;
  try {
    await _withKV(env, 'mktmine', em, (r) => {
      r.ids = (Array.isArray(r.ids) ? r.ids : []).filter(x => x !== id);
      r.built = r.built || Date.now();
      return r;
    }, { ids: [], built: 0 });
  } catch (e) { audit(env, 'seller_index_remove_failed', { email: em, id, error: String((e && e.message) || e) }); }
}
/* AMV-187: MONEY FROM A SALE CLEARS BEFORE IT CAN LEAVE.

   A card dispute arrives weeks after the charge. `_reverseSale` already handles
   that correctly on the books - it takes the item back, debits the seller, and
   lets the balance go NEGATIVE so nobody profits by being quick. It only works
   if the money is still here.

   Withdrawal paid out the whole balance the moment it passed the minimum, with
   no requirement that the funds had aged at all. So: list at $999, buy it from
   a second account with a stolen card, take the $799 the same minute, abandon
   the account. Six weeks later the dispute lands, the balance goes to -$799,
   and that is a number in a record nobody will ever return to. AMV is out the
   payout, the dispute fee, and a mark against its merchant account.

   So each credit is HELD until the window has substantially passed. Held money
   is still theirs - it is on the balance, it is shown, it is counted - it just
   cannot leave yet. A reversal takes the held money first, because that is the
   money most likely to still exist.

   Additive on purpose: a wallet written before this has no `holds` array, and
   an absent hold means cleared. Freezing every existing seller's balance on the
   day this ships would cost real sellers to stop a fraud that has not happened. */
const PAYOUT_HOLD_DAYS = 14;
const PAYOUT_HOLD_MS = PAYOUT_HOLD_DAYS * 86400000;

/* AN UNREADABLE WALLET IS NOT AN EMPTY WALLET.

   This used to be `try { return JSON.parse(raw) } catch {}` falling through to
   a fresh zero wallet, and that made a corrupt record indistinguishable from a
   seller who has never sold anything. Two consequences, and the second is the
   one that cannot be undone.

   The screen showed $0.00 available, $0.00 lifetime and "No earnings yet -
   sell something to start" to somebody who is owed money. The code six lines
   from the caller says "Never a fabricated zero" about the network-failure
   path; this path fabricated exactly that zero.

   And `_withWallet` - the lock every money path goes through - reads with this
   function, mutates, and writes back with `_saveWallet`. So the next sale
   credit landing on a corrupt record did not fail: it overwrote the real
   balance, the lifetime total and the holds array with a fresh wallet plus the
   new sale. The seller's money was gone, permanently, and nothing anywhere
   said so.

   `_withKV` - which every other locked record uses - has always refused this:
   "Nothing is known about this record, so nothing may be written over it." The
   money one was the one that did not. Absent is still a new seller and still
   returns a fresh wallet; only present-and-unparseable throws. */
async function _wallet(env, email) {
  const raw = await env.AMV_KV.get(`wallet:${email}`);
  if (raw != null) {
    try { return JSON.parse(raw); }
    catch (e) {
      try { audit(env, 'record_corrupt', { key: `wallet:${email}`, bytes: String(raw).length }); } catch (_) {}
      throw new UnreadableRecordError(`wallet:${email}`, 'invalid JSON');
    }
  }
  return { balance: 0, lifetime: 0, currency: 'usd', holds: [] };
}
async function _saveWallet(env, email, w) { await env.AMV_KV.put(`wallet:${email}`, JSON.stringify(w)); }

/* AMV-190: EVERY WALLET MUTATION GOES THROUGH HERE.

   Withdrawal already serialized itself, because two withdrawals racing was
   obviously money. Crediting a sale and reversing one did read-modify-write on
   the SAME record with no lock at all, which is the same race wearing a
   different hat:

     two sales completing together - both read balance B, both write B+share,
     and one seller credit is silently gone. The seller notices; AMV cannot
     explain it, because nothing failed.

     a sale landing during a withdrawal - the payout zeroes what left, the sale
     writes the balance it read before that, and money already paid out is back
     on the books to be withdrawn a second time.

   Neither shows up until there is enough traffic for two things to happen at
   once, which is to say: until it is working.

   Short lock, real release, and a few retries - a webhook that cannot get the
   lock must NOT give up, because giving up means somebody paid and nobody was
   credited. If it truly cannot, it throws, and the caller's retry or the
   reconciliation sweep picks it up rather than the money quietly vanishing. */
const WALLET_LOCK_TRIES = 6;

/* AMV-196: READ, CHANGE, WRITE - WITHOUT LOSING THE OTHER WRITER.

   The wallet was the first record found doing this unguarded, and it is not the
   only one that matters. Two of the others cost more than money:

     `acct` - authLogin rewrites the password hash when it upgrades the
     iteration count, and authResetConfirm writes the NEW hash. A login with the
     OLD password in flight when a reset lands writes back the record it read
     BEFORE the reset, restoring the old hash and salt. The reset reports
     success, the new password does not work, and the old one still does -
     which is precisely the situation somebody resets their password to escape.

     `ent` - thirteen callers of setEntitlement plus three direct writers. A
     Stripe grant racing a referral bonus loses one of them, and the one that
     loses can be the plan somebody just paid for.

   `mutate` receives the CURRENT record, read inside the lock. Return a value to
   pass it back out. Failing to take the lock throws rather than writing
   anyway - a lost entitlement or a reverted password must not happen quietly. */
async function _withRecord(env, kind, id, load, save, mutate) {
  /* The key is used AS GIVEN. It used to be lowercased here, which is right for
     an email and silently wrong for a record id: a team id that is not already
     lowercase becomes a key that does not exist, `load` returns nothing, the
     mutate does nothing, and the caller is told the change was applied. The
     callers that key by email lowercase it themselves, where it is obviously an
     email. */
  const key = String(id || '');
  if (!key) return null;
  for (let i = 0; i < WALLET_LOCK_TRIES; i++) {
    if (await _claimOnce(env, 'rmut:' + kind, key, 15)) {
      try {
        const rec = await load(env, key);
        const out = await mutate(rec);
        await save(env, key, rec);
        return out;
      } finally { await _releaseClaim(env, 'rmut:' + kind, key); }
    }
    await new Promise(r => setTimeout(r, 40 * (i + 1)));
  }
  /* Tagged, because callers turn THIS into "try again" for the person. An
     ordinary bug inside the mutate must not wear the same badge: a caller that
     catches everything would answer "the record was busy" for ever while the
     real fault never surfaced. */
  audit(env, 'record_lock_timeout', { kind, id: key });
  try { await alertOnce(env, 'record_lock:' + kind,
    'A ' + kind + ' record could not be locked to apply a change, so the change was NOT made. '
    + 'If this is `ent` somebody may be on the wrong plan; if it is `acct` a password change may not have taken.', 30); } catch (e) {}
  const busy = new Error(kind + ' is busy');
  busy.code = 'record_busy';
  throw busy;
}
/* True only for "the lock could not be taken". Anything else thrown out of a
   mutate is a fault, and telling somebody to try again would hide it. */
const _isBusy = (e) => !!(e && e.code === 'record_busy');

async function _withWallet(env, email, mutate) {
  const em = String(email || '').toLowerCase();
  if (!em) return null;
  let lastErr = null;
  for (let i = 0; i < WALLET_LOCK_TRIES; i++) {
    if (await _claimOnce(env, 'wmut', em, 15)) {
      try {
        const w = await _wallet(env, em);
        const out = await mutate(w);
        await _saveWallet(env, em, w);
        return out;
      } catch (e) { lastErr = e; throw e; }
      finally { await _releaseClaim(env, 'wmut', em); }
    }
    await new Promise(r => setTimeout(r, 40 * (i + 1)));
  }
  /* Loud. A credit that cannot be applied is somebody's money, and the one
     thing that must not happen is for it to disappear quietly. */
  audit(env, 'wallet_lock_timeout', { email: em });
  try { await alertOnce(env, 'wallet_lock', 'A wallet could not be locked to apply a change - a sale credit or reversal may not have been recorded. Check the reconciliation sweep.', 30); } catch (e) {}
  throw lastErr || new Error('wallet is busy');
}

/* The two records where a lost write is worse than money. */
const _loadAcct = async (env, em) => (await DB.get(env, 'acct', em)) || null;
const _saveAcct = async (env, em, a) => { if (a) await DB.put(env, 'acct', em, a); };
async function _withAcct(env, email, mutate) {
  return _withRecord(env, 'acct', String(email || '').toLowerCase(), _loadAcct, _saveAcct, mutate);
}

/* AMV-197: THE RECORDS A GROUP OF PEOPLE ALL WRITE TO.

   `acct` and `ent` belong to one person, so a lost write there needs two of
   their own devices. A team record and a family record are written by everybody
   in them, from different places, at the same time - joining, leaving, being
   removed, changing a role, sharing something. Read-append-write on those does
   not need a coincidence; it needs two people using the product.

   What a lost write costs here is not an edit. It is a seat somebody paid for
   and did not get, a member who was removed and can still see everything, or a
   role change that silently did not happen. None of it errors, and the screen
   shows whichever version won.

   The mutate callback receives the record as it is INSIDE the lock, so a
   permission or capacity check written there is checked against what is true
   now rather than what was true when the request started. Returning
   `{ error, status, code }` refuses without writing; returning anything else
   commits. */
const _loadTeam = async (env, id) => (await DB.get(env, 'team', id)) || null;
const _saveTeam = async (env, id, t) => { if (t) await DB.put(env, 'team', id, t); };
async function _withTeam(env, id, mutate) {
  return _withRecord(env, 'team', id, _loadTeam, _saveTeam, mutate);
}
const _loadFam = async (env, id) => (await DB.get(env, 'fam', id)) || null;
const _saveFam = async (env, id, f) => { if (f) await DB.put(env, 'fam', id, f); };
/* AMV-203: the same lock for any record that is read, changed and written back.

   Nine of the ten defects found in the sweep after AMV-202 were this one shape
   on nine different record kinds, so the helper is generic rather than one per
   kind. `empty` is what a missing record starts as, and it is COPIED per call -
   a shared default object would be mutated by the first caller and handed to
   every one after it. */
async function _withKind(env, kind, id, mutate, empty) {
  return _withRecord(env, kind, String(id || ''),
    async (e, k) => (await DB.get(e, kind, k)) || (empty === undefined ? null : JSON.parse(JSON.stringify(empty))),
    async (e, k, rec) => { if (rec) await DB.put(e, kind, k, rec); },
    mutate);
}
/* And for the records that live under a raw KV key rather than a DB kind. */
/* AMV-012: "NOT THERE" AND "COULD NOT BE READ" ARE DIFFERENT ANSWERS.

   This caught every exception from the read - a transient storage error, a
   timeout, corrupt JSON - and returned the caller's `empty` value, which the
   mutate then filled in and the save wrote back over the key. A storage blip
   during a wallet or entitlement mutation therefore replaced a live record
   with a fresh empty one, silently, and the operation reported success.

   The lock made this worse rather than better: the write happens inside the
   lock, so it looks correct and nothing races it. It was the read that lied.

   Availability and absence are now separate outcomes. A genuine miss still
   yields `empty`, because a record that has never existed is a real state.
   Anything else throws, and the caller fails rather than overwriting data it
   could not see. Corrupt JSON throws too, and says which key, because a record
   that cannot be parsed is a record to look at rather than one to replace. */
class UnreadableRecordError extends Error {
  constructor(key, cause) {
    super('record could not be read: ' + key + (cause ? ' (' + cause + ')' : ''));
    this.name = 'UnreadableRecordError';
    this.key = key;
    this.kind = 'unreadable';
  }
}

async function _withKV(env, name, key, mutate, empty) {
  const fresh = () => (empty === undefined ? null : JSON.parse(JSON.stringify(empty)));
  return _withRecord(env, name, String(key || ''),
    async (e, k) => {
      const id = `${name}:${k}`;
      let raw;
      try {
        raw = await e.AMV_KV.get(id);
      } catch (err) {
        /* The store was unreachable. Nothing is known about this record, so
           nothing may be written over it. */
        throw new UnreadableRecordError(id, String((err && err.message) || err));
      }
      if (raw == null) return fresh();          // genuinely absent
      try {
        return JSON.parse(raw);
      } catch (err) {
        try { audit(env, 'record_corrupt', { key: id, bytes: String(raw).length }); } catch (_) {}
        throw new UnreadableRecordError(id, 'invalid JSON');
      }
    },
    async (e, k, rec) => { if (rec) await e.AMV_KV.put(`${name}:${k}`, JSON.stringify(rec)); },
    mutate);
}

/* AMV-202: A LOCK ONLY HOLDS IF EVERY WRITER TAKES IT.

   setEntitlement has run under the ent record lock since AMV-196, which stops
   two grants losing each other. It does nothing about the eleven other places
   that wrote this record directly and took no lock at all - and a locked writer
   is no safer than the unlocked one racing it.

   The sharp one is a past-due mark landing beside a payment: the customer pays,
   the grant is applied under the lock, and the unlocked past-due write puts
   back the record it read first. A paying customer is marked past due and loses
   what they just bought, and nothing anywhere fails.

   Keyed by address, so lowercasing belongs here where the value is obviously an
   address. Whatever `load` returned is written back, so a mutate that decides
   there is nothing to do rewrites the record it just read inside the lock -
   which is a no-op, not a lost write. */
const _loadEnt = async (env, em) => (await DB.get(env, 'ent', em)) || null;
const _saveEnt = async (env, em, e) => { if (e) await DB.put(env, 'ent', em, e); };
async function _withEnt(env, email, mutate) {
  return _withRecord(env, 'ent', String(email || '').toLowerCase(), _loadEnt, _saveEnt, mutate);
}
async function _withFam(env, id, mutate) {
  // Keyed by the parent's address, so lowercasing is right here and stated here.
  return _withRecord(env, 'fam', String(id || '').toLowerCase(), _loadFam, _saveFam, mutate);
}
/* One shape for "the lock said no" so every caller answers the same way, and
   nobody is told a change happened that did not. */
function _busyJson(what) {
  return json({ error: 'Your ' + what + ' was being changed by somebody else just then, so this was not applied. Please try again.',
                code: 'record_busy' }, 503);
}

/* What this seller could actually withdraw right now: the balance, less
   everything still inside its clearing window. Never below zero on the
   available side - a negative balance from a reversal is a debt to work off,
   not a number to withdraw against. */
async function _availableBalance(env, email, now = Date.now()) {
  const w = await _wallet(env, email);
  return _availableOf(w, now);
}
function _availableOf(w, now = Date.now()) {
  /* Only holds that have NOT matured hold anything back. Subtracting every hold
     regardless of age was the first version and it never cleared at all - money
     would have been frozen for ever, which is a worse failure than the one this
     exists to prevent. */
  const held = (w.holds || [])
    .filter(h => (+h.until || 0) > now)
    .reduce((n, h) => n + (+h.amount || 0), 0);
  return +Math.max(0, (+w.balance || 0) - held).toFixed(2);
}
/* Holds whose window has passed have done their job; once the money they were
   holding has actually left, they are noise that makes the record harder to
   read and the arithmetic easier to get wrong. */
function _pruneMaturedHolds(w, now = Date.now()) {
  w.holds = (w.holds || []).filter(h => (+h.until || 0) > now);
  return w;
}
/* When the next tranche frees up, so a refusal can say WHEN rather than no. */
function _nextClearingAt(w) {
  const now = Date.now();
  const times = (w.holds || []).map(h => +h.until || 0)
    .filter(t => t > now).sort((a, b) => a - b);
  return times.length ? times[0] : 0;
}
/* Same rule as `_wallet` above, for the same reason: a money history that
   cannot be read is not a money history with nothing in it. This one is also
   read-modify-written by `_pushWalletTx`, so swallowing the parse here would
   let the next sale replace a seller's whole record of what they were paid
   with a single line. */
async function _walletTx(env, email) {
  const raw = await env.AMV_KV.get(`wallet_tx:${email}`);
  if (raw != null) {
    try {
      const v = JSON.parse(raw);
      return Array.isArray(v) ? v : [];
    } catch (e) {
      try { audit(env, 'record_corrupt', { key: `wallet_tx:${email}`, bytes: String(raw).length }); } catch (_) {}
      throw new UnreadableRecordError(`wallet_tx:${email}`, 'invalid JSON');
    }
  }
  return [];
}
/* Append a line to somebody's money history, at most once per event.

   A sale that fails partway is retried, and the retry re-runs the steps that
   already succeeded - so an append has to be able to tell whether it is the
   same event coming round again. `ref` (the charge) and `item` together are
   that identity, and a caller supplying both gets exactly-once for free.

   Returns whether it actually wrote, so a caller can tell "recorded now" from
   "was already recorded" - which is what the steps after it key on. A caller
   with no ref gets the old behaviour: always append. */
/* UNDER THE LOCK, BECAUSE FIVE MONEY PATHS WRITE THIS AND NONE OF THEM WAITED.

   This was a read, an unshift and a put - a read-modify-write with nothing
   serialising it - and it is called from every path that moves a seller's
   money: the sale credit, the reversal, the withdrawal, and both payout
   settlements. A sale landing beside a withdrawal simply lost one of the two
   lines, and this record is what a seller reads to understand what happened to
   their money and what an operator reads in a dispute.

   The single-writer shape is what hid it. Every other record here has several
   handlers writing it, which is visible; this has ONE function with five
   callers, which reads as safe and is not. And it is why the lock sweep is
   silent: `wallet_tx` had no locked writer anywhere, so the rule it enforces -
   locked somewhere, therefore locked everywhere - never engaged. Going through
   the shared helper is what puts it inside that rule, so the next writer is
   held to it.

   It also stopped being merely a log. The dedupe below is what tells a retried
   sale that its history line already exists, so a lost line does not just
   leave a gap now - it lets the next attempt write a second one.

   `_withKV` writes `wallet_tx:<key>`, which is the same key this always used,
   and the key is passed through exactly as callers give it - lowercasing here
   and not in `_walletTx` would split reads from writes. */
async function _pushWalletTx(env, email, tx) {
  return await _withKV(env, 'wallet_tx', email, (list) => {
    if (tx && tx.ref && tx.item &&
        list.some((t) => t && t.ref === tx.ref && t.item === tx.item && t.type === tx.type)) {
      return false;
    }
    /* In place: the helper writes back the object it loaded, so building a new
       array here would be a no-op that looked like a write. */
    list.unshift(tx);
    if (list.length > 500) list.length = 500;
    return true;
  }, []);
}
async function _ownsItem(env, email, id) {
  return !!(await env.AMV_KV.get(`entitleitem:${email}:${id}`));
}

/* Start a purchase: creates a one-time Stripe Checkout for a paid listing.
   We pass the item id + buyer in metadata so the webhook can grant + split. */
async function marketBuy(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'sign in to buy' }, 401);
  /* Money out of a card. A minor cannot form a binding contract, which is
     exactly why their purchases come back as chargebacks. */
  const ageBad = await _moneyAgeGate(env, user.email);
  if (ageBad) return json(ageBad, ageBad.code === 'age_required' ? 428 : 403);
  /* A purchase creates a Stripe session too, so it carries the same bound as
     the plan checkout for the same reason. */
  const bg = await guardAction(env, `mktbuy:${user.email}`, 10, 100, 'purchases');
  if (bg) return bg;
  const { id } = await request.json().catch(() => ({}));
  const it = await _getListing(env, id);
  if (!it) return json({ error: 'item not found' }, 404);
  if (/^usr_/.test(id) && it.status === 'sold') return json({ error: 'Sorry - this just sold. Message the seller to ask for another.' }, 409);

  if (!it.price || it.price <= 0) return json({ error: 'this item is free - just install it' }, 400);
  if (it.authorEmail === user.email) return json({ error: 'you cannot buy your own listing' }, 400);
  if (await _ownsItem(env, user.email, id)) return json({ error: 'you already own this', owned: true }, 400);
  /* A parent switching off marketplace purchases has to mean it at the point
     money would move, not in a settings screen nobody consults (AMV-102). */
  if (user.family && user.family.limits && !user.family.limits.marketplace) {
    return json({ error: 'Buying from the marketplace is turned off for your account. Whoever manages your family can turn it on.',
                  code: 'family_blocked' }, 403);
  }
  /* Same fact, same words as the subscription routes. Somebody pressing Buy
     on a marketplace listing is owed a sentence, not a config note. */
  if (!env.STRIPE_SECRET_KEY)
    return json({ error: 'Payments are not connected on this deployment yet, so this cannot be bought. Nothing has been charged.',
                  code: 'needs_service' }, 503);

  /* AMV-009: THE CHECKOUT THEY ALREADY HAVE, IF THERE IS ONE.

     Every call here used to create a fresh payment session. Two clicks on a
     slow connection, a double submit, or a back button and a retry produced two
     live sessions for the same item, and both of them take a card.

     The credit is exactly-once per buyer and item, so the SECOND payment grants
     nothing - which is worse than granting twice. The buyer is charged for a
     thing they already own and nothing anywhere notices, because from the
     inside the duplicate credit was correctly refused. The safety mechanism is
     what makes the loss silent.

     Returned before a second session is created, which is the only point at
     which a duplicate charge can still be prevented. Reached only after the
     already-owns check above, so somebody who has finished paying is told they
     own it rather than handed a stale checkout. */
  try {
    const open = JSON.parse(await env.AMV_KV.get(`mktsess:${user.email}:${id}`) || 'null');
    if (open && open.url && open.id) {
      audit(env, 'market_checkout_reused', { buyer: user.email, item: id, session: open.id });
      return json({ ok: true, url: open.url, id: open.id, reused: true });
    }
  } catch (e) { /* a missing or unreadable note just means a new session */ }

  /* AMV-009: A ONE-OF-A-KIND LISTING IS RESERVED, NOT MERELY CHECKED.

     The 'sold' test near the top of this function is a read followed by a
     decision. Two buyers arriving together both read a status that has not
     changed yet, both are sent to checkout, and both pay. One gets the item;
     the other has paid for something that no longer exists, and finds out by
     not receiving it - which is the worst way for somebody to learn they were
     charged.

     Claimed through the Durable Object rather than written to storage after a
     read, because a read-then-write reservation is the same race with an extra
     step. It expires by itself, so an abandoned checkout does not take an item
     off the market for a day.

     Taken HERE, after the buyer's own open session has been handed back above,
     so returning to your own checkout can never be blocked by your own hold. */
  if (/^usr_/.test(id)) {
    if (!(await _claimOnce(env, 'mktresv', id, MARKET_RESERVE_S))) {
      return json({ error: 'Somebody else is buying this right now. Try again in a few minutes, or message the seller.',
                    code: 'item_reserved' }, 409);
    }
  }

  // AMV-025 / AMV-SP-09: the server-configured origin is authoritative for
  // payment redirects, and there is no fallback to the request Origin.
  const origin = _paymentReturnOrigin(env);
  if (!origin) return _paymentOriginMissing();
  const form = new URLSearchParams();
  form.set('mode', 'payment');
  /* The same for a marketplace purchase, where the single-use methods matter
     most: PIX, OXXO, BLIK and iDEAL are all one-off payments and all of them
     are how their countries actually buy something once. */
  form.set('automatic_payment_methods[enabled]', 'true');
  form.set('line_items[0][price_data][currency]', 'usd');
  form.set('line_items[0][price_data][product_data][name]', ('AMV: ' + it.title).slice(0, 120));
  form.set('line_items[0][price_data][unit_amount]', String(it.price * 100));
  form.set('line_items[0][quantity]', '1');
  form.set('customer_email', user.email);
  form.set('client_reference_id', user.email);
  form.set('success_url', `${origin}?bought=${encodeURIComponent(id)}`);
  form.set('cancel_url', `${origin}?canceled=1`);
  form.set('metadata[kind]', 'market_purchase');
  form.set('metadata[itemId]', id);
  form.set('metadata[buyer]', user.email);
  form.set('metadata[seller]', it.authorEmail || '');

  const r = await fetchDeadline('https://api.stripe.com/v1/checkout/sessions', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${env.STRIPE_SECRET_KEY}`, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: form.toString(),
  });
  const d = await r.json();
  if (!r.ok) {
    /* No checkout exists, so nothing is being paid for and the item goes back
       on the market now rather than when the hold expires. */
    if (/^usr_/.test(id)) { try { await _releaseClaim(env, 'mktresv', id); } catch (e) {} }
    return json({ error: d.error?.message || 'stripe error' }, 502);
  }
  /* Remembered until the webhook completes it. If that delivery never
     lands, the sweep asks Stripe directly rather than leaving somebody
     who paid with nothing. */
  await _pendStart(env, d.id, { provider:'stripe', kind:'market', email:user.email,
                                itemId:id, seller:(it.authorEmail||'').toLowerCase() });
  /* AMV-009: ONE OPEN CHECKOUT PER BUYER PER ITEM.

     Every call to this route created a fresh Stripe session. Two clicks on a
     slow connection, a double-submit, or a back button and a retry produced two
     live sessions for the same item - and both of them take a card.

     The credit is exactly-once per (buyer, item), so the SECOND payment grants
     nothing. That is worse than granting twice: the buyer is charged for a
     thing they already own and nothing anywhere notices, because from AMV's
     side the duplicate credit was correctly refused.

     So the session is remembered and handed back. A buyer who returns to the
     checkout gets the one they already have rather than a second card charge.
     It expires with Stripe's own session window, so an abandoned checkout does
     not lock somebody out of buying. */
  await env.AMV_KV.put(`mktsess:${user.email}:${id}`, JSON.stringify({ id: d.id, url: d.url, at: Date.now() }),
                       { expirationTtl: MARKET_SESSION_TTL_S });

  return json({ ok: true, url: d.url, id: d.id });
}

/* Called from the Stripe webhook when a market_purchase session completes.
   Grants the item to the buyer and credits the seller their 80% share. */
async function _creditSale(env, { itemId, buyer, seller, amountCents, ref }) {
  if (!itemId || !buyer) return;
  // Exactly-once: atomically claim this (buyer,item) sale. A buyer can never own
  // the same item twice (marketBuy blocks re-purchase), so this is a stable key.
  // The claim is atomic on D1, closing the double-credit race that a plain
  // "already owns it?" read cannot (two concurrent callers both read "no").
  /* Claimed through the helper so a credit that fails halfway gives the claim
     back and the provider's retry - or the reconcile sweep - can finish it.
     Taking the claim and then failing used to be recoverable only because the
     claim expired in thirty seconds; now that it is permanent, the release has
     to be deliberate. */
  const _sale = await _onceOrRetry(env, 'sale', `${buyer}:${itemId}`, CLAIM_ONCE_TTL_S,
    async () => { await _creditSaleWork(env, { itemId, buyer, seller, amountCents, ref }); });
  return _sale.value;
}

/* The credit itself. Separated only so the claim above wraps ALL of it - there
   is no partial success here worth keeping: either the buyer owns it and the
   seller was paid, or the whole thing is retried. */
async function _creditSaleWork(env, { itemId, buyer, seller, amountCents, ref }) {
  const it = await _getListing(env, itemId);
  const price = amountCents != null ? amountCents / 100 : (it ? it.price : 0);
  const sellerEmail = seller || (it && it.authorEmail) || '';
  // grant ownership to the buyer
  await env.AMV_KV.put(`entitleitem:${buyer}:${itemId}`, '1');
  /* AMV-207: a buyer's history, appended under the lock. Access to the item is
     granted by entitleitem above and is not at risk here - what a lost write
     costs is the record of what they bought, which is the thing they look at to
     find it again. A refund landing beside a purchase used to lose one of the
     two. */
  /* AMV-043: THE SELLER, WRITTEN DOWN AT THE MOMENT OF THE SALE.

     Reviewing a seller used to be proved by walking the buyer's purchases and
     reading each LISTING to see who wrote it. So the proof depended on the
     listing still existing - and the person who decides whether it exists is
     the seller being reviewed. Delete the item and every buyer of it silently
     loses the ability to say anything about you, which is the one thing a
     reputation system must not let a seller do.

     It is not only deletion: a listing that moderation removes, or one that a
     restore did not bring back, takes the same reviews with it.

     Who somebody bought from is a fact about the transaction. It is recorded
     with the transaction now, so it survives whatever happens to the listing
     afterwards. */
  const bought = { id: itemId, title: it ? it.title : itemId, kind: it ? it.kind : 'prompt',
                   price, ts: Date.now(), seller: sellerEmail || (it ? String(it.authorEmail || '').toLowerCase() : '') };
  /* EVERY STEP HERE HAS TO SURVIVE BEING RUN TWICE.

     The claim around this is released when the work throws, so the retry can
     finish a sale that failed halfway - which means the steps that already
     succeeded run again. Granting the item and writing the snapshot are puts
     and do not care. This is an append, and it did care: a credit that failed
     at the wallet left the purchase recorded, and the retry recorded it again,
     so the buyer's history showed one item bought twice.

     A buyer can only own a listing once - marketBuy refuses a re-purchase - so
     the entry's own presence is the evidence. */
  let alreadyBought = false;
  await _withKV(env, 'purchases', buyer, (list) => {
    if (list.some((x) => x && x.id === itemId)) { alreadyBought = true; return; }
    /* Changed IN PLACE: the helper writes back the object it loaded, so a
       mutate that builds a new array would be a no-op that looked like a write. */
    list.unshift(bought);
    if (list.length > 500) list.length = 500;
  }, []);
  // AMV-037: snapshot the deliverable at purchase time. The buyer paid for THIS
  // content - a later seller edit or delete must never revoke their access.
  if (it) { try { await DB.put(env, 'mktsnap', `${buyer}:${itemId}`, { ...it, _boughtAt: Date.now() }); } catch (e) {} }
  // credit the seller 80%
  let credited = false;
  if (sellerEmail) {
    const sellerShare = +(price * (1 - MARKET_PLATFORM_FEE)).toFixed(2);
    /* THE MONEY STEP, ASKED WHETHER IT ALREADY HAPPENED - INSIDE THE LOCK.

       The retry has to be able to finish an unfinished sale without paying for
       a finished one, and the only place that question can be answered without
       racing is inside the wallet's own lock, against the wallet's own record.
       The hold written below carries this charge's `ref` and the item, so its
       presence IS the evidence that this sale was credited. Nothing else has
       to be trusted - not a marker written elsewhere, not the order the steps
       ran in.

       Holds are pruned once matured, at fourteen days. Every retry that can
       reach here happens within a provider's redelivery window, which is days,
       so the evidence is always still there when it is needed. */
    credited = await _withWallet(env, sellerEmail, (w) => {
    if ((w.holds || []).some((h) => h && h.item === itemId && (h.ref || '') === (ref || ''))) return false;
    w.balance = +(w.balance + sellerShare).toFixed(2);
    w.lifetime = +(w.lifetime + sellerShare).toFixed(2);
    /* Held until the dispute window has substantially passed. `at` is the sale
       time so a test - or a backfill - can age it, and `ref` ties the hold to
       the charge so a reversal can release exactly this one rather than
       guessing at an amount. */
    const at = Date.now();
    /* A ROLLING RESERVE, BECAUSE THE HOLD IS SHORTER THAN THE RISK.

       The 14-day hold answers "did this sale stick". It does not answer the
       real question, which is that a card dispute can arrive up to 120 days
       after the charge. Holding EVERYTHING for 120 days would be safe and
       would also make AMV useless to an honest seller, who would wait four
       months to be paid for work already delivered.

       So the money is split the way payment platforms split it: most of it
       clears on the short hold, and a small percentage of every sale is held
       across the full dispute window. That reserve is what a late chargeback
       is taken from, so a reversal at day 60 lands on money AMV still has
       rather than on money it has already sent. It is the seller's money and
       it is shown as theirs the whole time - it clears late, it is not lost. */
    const reserved = +(sellerShare * PAYOUT_RESERVE_PCT).toFixed(2);
    const clearing = +(sellerShare - reserved).toFixed(2);
    w.holds = (w.holds || []).concat({ amount: clearing, at, until: at + PAYOUT_HOLD_MS,
                                       ref: ref || '', item: itemId });
    if (reserved > 0) {
      w.holds = w.holds.concat({ amount: reserved, at, until: at + PAYOUT_RESERVE_MS,
                                 ref: ref || '', item: itemId, reserve: true });
    }
    /* Matured holds are dropped on every credit, not only on withdrawal. They
       were pruned in one place - the payout - so a seller who never withdrew
       accumulated one entry per sale for ever, in a record that is read and
       rewritten on every single sale. */
    _pruneMaturedHolds(w);
    return true;
    });
    /* NOT gated on `credited`. That was the first attempt and it was wrong in
       the way that matters: a sale which failed HERE, after the money moved,
       comes back with the credit already done - so keying these off the credit
       would skip for ever the exact steps that failed. Each one carries its own
       evidence instead, so it can tell a repeat from a resumption.

       `ref` and the item are what make this line identifiable as this sale. */
    await _pushWalletTx(env, sellerEmail, { type: 'sale', amount: sellerShare, gross: price,
      item: itemId, title: it ? it.title : itemId, buyer, ref: ref || '', ts: Date.now() });
    // record the platform's cut (your revenue) so it shows in admin finance. The
    // full charge is already in Stripe; this logs the marketplace fee distinctly.
    /* Given a stable id rather than a generated one, so a resumed sale records
       the fee it could not record the first time WITHOUT recording it twice.
       Gating this on whether the credit or the history line was new was the
       first attempt and it was wrong the same way both times: the retry exists
       to finish the steps that failed, so keying a step off an earlier step
       skips exactly the work that is missing. */
    const platformCut = +(price * MARKET_PLATFORM_FEE).toFixed(2);
    if (platformCut > 0) await _recordTxn(env, { id: 'mktfee_' + (ref || itemId) + '_' + itemId,
      provider: 'marketplace', email: buyer, amount: platformCut,
      currency: 'USD', kind: 'marketplace fee', status: 'succeeded', ref: itemId });
  }
  /* bump sale count; user listings are one-of-a-kind -> mark SOLD (leaves catalog)

     Skipped when this pass credited nothing, or a retry would count one sale
     twice on the listing every reader sees. A free listing has no seller and no
     credit to key on, so it uses the buyer's own history instead - the same
     evidence, one record over.

     The one thing this does not cover is a failure landing strictly between the
     wallet write and this line, which leaves the counter one short. That is the
     direction to be wrong in: a sale count that reads low is a display being
     modest, and the money is right. */
  /* NOT guarded, deliberately, and the reason is worth stating because a guard
     here looks obviously right. Nothing after this line can throw - the saleref
     write below swallows its own errors - so a pass that reaches this bump also
     finishes, takes the claim for good, and is never retried. The counter
     therefore cannot run twice. A guard would only be able to do one thing:
     skip the bump on a pass that is resuming, which is the pass that still owes
     the count. Guarding it loses sales from the listing; not guarding it cannot
     add any. */
  if (it) {
    /* AMV-204: the sale is recorded on the listing under the lock. This is the
       write a visitor's page view used to put back, which is how an item that
       had sold went back on sale. */
    await _withKV(env, 'market', itemId, (rec) => {
      if (!rec) return null;
      rec.sales = (rec.sales || 0) + 1; rec.installs = (rec.installs || 0) + 1;
      if (/^usr_/.test(itemId)) rec.status = 'sold';
    });
  }
  /* AMV-091: a reverse index from the payment to what it bought. Without it a
     refund or chargeback arrives as a charge id we cannot connect to anything,
     which is exactly why nothing was ever undone. */
  if (ref) {
    try {
      await env.AMV_KV.put(`saleref:${ref}`, JSON.stringify({
        itemId, buyer, seller: sellerEmail, price,
        sellerShare: sellerEmail ? +(price * (1 - MARKET_PLATFORM_FEE)).toFixed(2) : 0,
        /* Carried so a reversal can release exactly this sale's hold. */
        ref, at: Date.now(),
      }), { expirationTtl: 400 * 86400 });
    } catch (e) {}
  }
  audit(env, 'market_sale', { item: itemId, buyer, seller: sellerEmail, price });
}

/* Undo a marketplace sale that was refunded or charged back.

   Before this, none of it happened. The buyer kept the item, the seller kept
   the credit and could withdraw it, and the platform ate the whole charge -
   which makes "buy the expensive listing, charge it back" a way to take money
   out of AMV. The fraud register already had a signal for exactly this pattern;
   what it did not have was anything on the server that acted on it. */
/* Returns null for "this charge is not a marketplace sale", which is the
   signal the webhook uses to fall through to the subscription path.

   A corrupt `saleref:` record produced that same null, and the consequence was
   two wrongs at once. The marketplace sale was never reversed - the buyer kept
   the item, the seller kept the credit and could withdraw it, and the platform
   ate the whole charge, which is exactly the "buy the expensive listing, then
   charge it back" hole this function was written to close. And the fallthrough
   then treated a $9 listing chargeback as a SUBSCRIPTION dispute: it revoked
   the customer's whole plan to free and recorded an abuse strike against them.

   "I could not read it" is not "it is not one of mine", so it throws. The
   webhook catches that and refuses the event rather than deciding on it, and
   the provider retries - which is the right answer for a record that may be
   readable again in a moment, and the only answer that does not punish the
   wrong customer meanwhile. */
async function _reverseSale(env, ref, reason) {
  if (!ref) return null;
  let rec = null;
  const rawRef = await env.AMV_KV.get(`saleref:${ref}`);
  if (rawRef != null) {
    try { rec = JSON.parse(rawRef); }
    catch (e) {
      try { audit(env, 'record_corrupt', { key: `saleref:${ref}`, bytes: String(rawRef).length }); } catch (_) {}
      throw new UnreadableRecordError(`saleref:${ref}`, 'invalid JSON');
    }
  }
  if (!rec || !rec.itemId || !rec.buyer) return null;
  /* AMV-010: THE CLAIM WAS TAKEN BEFORE THE WORK AND KEPT WHEN IT FAILED.

     A refund followed by a dispute on the same charge must not claw the money
     back twice, so this is claimed once. The claim is PERMANENT - it has to be,
     or a redelivery weeks later would reverse the same sale again - and it was
     taken up front, before any of the four steps below.

     Every one of those steps can fail. If the wallet is locked by another
     writer, or the store blinks, the reversal stops halfway with the claim
     still held. The provider retries, the retry is discarded as a duplicate of
     work that never happened, and the outcome is the buyer keeping an item they
     charged back or the seller keeping money that was taken off the card. There
     is no error anywhere: from the outside a held claim and a completed
     reversal are the same thing.

     _creditSale had this fixed already, with a comment saying exactly why. The
     reversal - the half where the money goes the other way - was left on the
     bare claim. So it uses the same helper, which gives the claim back when the
     work throws and lets the retry finish it. */
  const _rev = await _onceOrRetry(env, 'salerev', ref, CLAIM_ONCE_TTL_S,
    async () => { await _reverseSaleWork(env, rec, reason); return rec; });
  return _rev.claimed ? _rev.value : null;
}

async function _reverseSaleWork(env, rec, reason) {
  // 1. The buyer does not keep what they did not pay for.
  /* NOT swallowed. A buyer who charges back and keeps the item is the attack
     this whole function exists to stop, so a failure to revoke has to reach the
     caller - which now releases the claim so the retry can finish it. Caught
     and discarded, it turned "AMV could not take it back" into "AMV took it
     back", permanently and silently.

     The snapshot delete stays tolerant: it is a copy of the deliverable, and
     the access records above are what actually decide whether the buyer keeps
     the item. */
  await env.AMV_KV.delete(`entitleitem:${rec.buyer}:${rec.itemId}`);
  try { await DB.del(env, 'mktsnap', `${rec.buyer}:${rec.itemId}`); } catch (e) {}
  await _withKV(env, 'purchases', rec.buyer, (list) => {
    const keep = list.filter(p => p && p.id !== rec.itemId);
    list.length = 0;
    for (const p of keep) list.push(p);
  }, []);

  /* 2. The seller does not keep the money. The balance is allowed to go
     NEGATIVE: a seller who already withdrew must not be able to outrun the
     reversal by being fast, and withdrawals are gated on a positive balance, so
     the debt is paid down by their next sales. */
  if (rec.seller && rec.sellerShare > 0) {
    await _withWallet(env, rec.seller, (w) => {
    w.balance = +((+w.balance || 0) - rec.sellerShare).toFixed(2);
    w.lifetime = +Math.max(0, (+w.lifetime || 0) - rec.sellerShare).toFixed(2);
    /* Release this sale's hold. Leaving it would keep freezing money for a sale
       that no longer exists - the seller would be short twice, once for the
       reversal and once for a hold against nothing. Matched on the charge
       reference, falling back to the item, so it releases THIS sale rather than
       whichever hold happens to be the same size. */
    /* EVERY hold for this sale, not the first one found.

       A sale now leaves TWO holds: the part that clears on the short window
       and the reserve slice that clears across the dispute window. They share
       a reference, so releasing one by index left the other frozen against a
       sale that no longer exists - the seller short by the reserve, invisibly,
       for four months. That is the exact failure the note above describes, and
       adding the reserve reintroduced it.

       Matched on the charge reference, falling back to the item, so it
       releases THIS sale's holds rather than whichever happen to be the same
       size. */
    const holds = (w.holds || []);
    const byRef = rec.ref ? holds.filter(h => h.ref && h.ref === rec.ref) : [];
    const drop = byRef.length ? byRef : holds.filter(h => h.item === rec.itemId);
    w.holds = holds.filter(h => !drop.includes(h));
    _pruneMaturedHolds(w);
    });
    await _pushWalletTx(env, rec.seller, { type: 'sale_reversed', amount: -rec.sellerShare,
      item: rec.itemId, buyer: rec.buyer, reason, ts: Date.now() });
  }

  // 3. A one-of-a-kind listing goes back on sale rather than staying "sold".
  try {
    const it = await _getListing(env, rec.itemId);
    if (it) {
      await _withKV(env, 'market', rec.itemId, (cur) => {
        if (!cur) return null;
        cur.sales = Math.max(0, (cur.sales || 1) - 1);
        if (/^usr_/.test(rec.itemId) && cur.status === 'sold') cur.status = 'active';
      });
    }
  } catch (e) {}

  // 4. The buyer is recorded, because doing this repeatedly is the attack.
  await _abuseRecord(env, rec.buyer, reason === 'dispute' ? 'dispute' : 'refund',
                     { marketItem: rec.itemId, amount: rec.price });
  audit(env, 'market_sale_reversed', { item: rec.itemId, buyer: rec.buyer, seller: rec.seller,
                                       price: rec.price, reason });
  await notify(env, `Marketplace ${reason}: $${(+rec.price || 0).toFixed(2)} on ${rec.itemId}. Buyer access revoked, seller credit clawed back.`);
}
/* Same rule as `_wallet`: absent means they have bought nothing, unreadable
   means AMV does not know. Swallowed, the two were the same answer, and the
   library screen says "No purchases yet" to a buyer who has paid - which the
   client already calls the worst way for this to be wrong, in a comment
   guarding the case where the REQUEST fails. This is the case where it
   succeeds and returns a lie. */
async function _purchasesList(env, email) {
  const raw = await env.AMV_KV.get(`purchases:${email}`);
  if (raw != null) {
    try {
      const v = JSON.parse(raw);
      return Array.isArray(v) ? v : [];
    } catch (e) {
      try { audit(env, 'record_corrupt', { key: `purchases:${email}`, bytes: String(raw).length }); } catch (_) {}
      throw new UnreadableRecordError(`purchases:${email}`, 'invalid JSON');
    }
  }
  return [];
}

/* Buyer's library: items they've purchased, WITH the unlocked deliverable. */
async function marketPurchases(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  /* An unreadable record here is the difference between "you have bought
     nothing" and "AMV cannot tell you what you own", and only one of those is
     something to say to somebody who has paid. */
  let list;
  try { list = await _purchasesList(env, user.email); }
  catch (e) {
    if (!(e instanceof UnreadableRecordError)) throw e;
    try { await alertOnce(env, 'purchases_corrupt', 'A buyer purchase record is unreadable, so their library cannot be listed. Check the audit log for record_corrupt.', 60); } catch (_) {}
    return json({ error: 'AMV could not read your library right now, so it will not tell you it is empty. Nothing has been lost - everything you have bought is still yours. This has been reported.',
                  code: 'purchases_unreadable' }, 503);
  }
  const items = [];
  for (const p of list) {
    // AMV-037: serve the immutable snapshot taken at purchase - the buyer keeps
    // full access to what they paid for even if the seller later edited or
    // deleted the listing. Fall back to the live listing for legacy purchases.
    const snap = await DB.get(env, 'mktsnap', `${user.email}:${p.id}`);
    if (snap) { items.push({ ...snap, _purchasedAt: p.ts }); continue; }
    const it = await _getListing(env, p.id);
    if (it) items.push({ ...it, _purchasedAt: p.ts });
    else items.push({ ...p, _removed: true });
  }
  return json({ ok: true, items });
}

/* Seller's own listings + sale counts. */
async function marketMyListings(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  /* Their own ids, then their own records. What this used to do was read every
     listing in the product and throw away the ones belonging to somebody else. */
  const idx = await _sellerListingIds(env, user.email);
  const out = [];
  for (const id of idx.ids) {
    const it = await _getListing(env, id);
    /* An id in the index whose record is gone is not an error worth showing
       somebody - it is a removal that raced this read, or an old entry. It is
       dropped here and tidied on the next write. */
    if (it) out.push(it);
  }
  out.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
  return json({ ok: true, items: out,
    /* Only ever true on the one-time backfill for a catalogue larger than the
       scan bound, and said out loud rather than quietly showing fewer items
       than somebody has. */
    truncated: idx.truncated || undefined,
    note: idx.truncated
      ? 'Some of your listings could not be indexed in one pass. They are safe - reload in a moment and the rest will appear.'
      : undefined });
}
async function marketUnlist(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  const { id } = await request.json().catch(() => ({}));
  const it = await _getListing(env, id);
  if (!it) return json({ error: 'not found' }, 404);
  if (it.authorEmail !== user.email) return json({ error: 'not your listing' }, 403);
  await env.AMV_KV.delete(`market:${id}`);
  await _sellerIndexRemove(env, user.email, id);
  await _marketCacheBust(env);
  audit(env, 'market_unlist', { id, by: user.email });
  return json({ ok: true });
}

/* Seller wallet: balance, lifetime earnings, recent transactions. */
async function marketEarnings(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  /* The wallet is the numbers. If it cannot be read there is nothing honest to
     put on this screen, so the failure goes to the client whole rather than as
     a zero - and the client already says "could not load your earnings,
     nothing has changed" rather than inventing a balance. */
  let w;
  try { w = await _wallet(env, user.email); }
  catch (e) {
    if (!(e instanceof UnreadableRecordError)) throw e;
    try { await alertOnce(env, 'wallet_corrupt', 'A seller wallet record is unreadable, so their balance cannot be shown. Check the audit log for record_corrupt.', 60); } catch (_) {}
    return json({ error: 'AMV could not read your balance right now, so it will not guess at it. Nothing has changed - your money is where it was. This has been reported.',
                  code: 'wallet_unreadable' }, 503);
  }
  /* The history is separate, and losing it does not make the numbers wrong. So
     it degrades on its own: the balances still show, and the list says it
     could not be read instead of "No earnings yet" - which to somebody with a
     lifetime total on the same screen is both false and self-contradictory. */
  let tx = [], txUnavailable = false;
  try { tx = await _walletTx(env, user.email); }
  catch (e) {
    if (!(e instanceof UnreadableRecordError)) throw e;
    txUnavailable = true;
  }
  /* Three numbers, not one. "Balance" alone meant a seller saw money they could
     not take and had no way to learn why - which reads as AMV keeping it. What
     has cleared, what is still clearing, and how long that takes. */
  const available = _availableOf(w);
  const pending = +Math.max(0, (+w.balance || 0) - available).toFixed(2);
  /* The list is capped at 50 and the heading says "Transaction history", which
     claims completeness the response cannot support. The count and the flag go
     with it so the screen can say which 50 these are - the same rule every
     bounded scan here already follows. */
  const TX_SHOWN = 50;
  return json({ ok: true, balance: w.balance, available, pending,
                holdDays: PAYOUT_HOLD_DAYS, availableAt: _nextClearingAt(w) || null,
                lifetime: w.lifetime, currency: w.currency || 'usd', minWithdraw: MARKET_MIN_WITHDRAW,
                sellerPct: Math.round((1 - MARKET_PLATFORM_FEE) * 100),
                tx: tx.slice(0, TX_SHOWN), txTotal: tx.length,
                txTruncated: tx.length > TX_SHOWN, txUnavailable });
}

/* Extraction: seller requests a withdrawal of their balance. Records a
   pending payout and zeroes the balance (operator fulfills it via the
   destination on file). Idempotent-ish via a unique request id. */
/* MONEY THAT LEFT A BALANCE FOR A PAYOUT THAT WAS NEVER WRITTEN.

   The withdrawal debits first and writes the payout record second, because the
   other order is a way to be paid twice. That leaves one narrow state: debited,
   with a marker naming the payout, and no record - which happens if the request
   is cut off between the two. The rollback in the withdrawal handles an
   exception; nothing can handle the Worker simply ending, so this does.

   Checked at the top of the next withdrawal, under the same lock, which is the
   only moment it matters and costs one read only when a marker exists - which
   is to say almost never. A marker whose record DOES exist is left alone: that
   payout is real and the money is genuinely gone. */
async function _reconcileStrandedPayouts(env, email) {
  const w = await _wallet(env, email);
  const pending = Array.isArray(w.pendingOut) ? w.pendingOut : [];
  if (!pending.length) return 0;
  const stranded = [];
  for (const p of pending) {
    if (!p || !p.id) continue;
    let rec = null;
    try { rec = await env.AMV_KV.get(`withdraw:${p.id}`); }
    catch (e) { return 0; }   // cannot tell: leave it rather than refund twice
    if (!rec) stranded.push(p);
  }
  if (!stranded.length) {
    /* Every marker has a record behind it, so they are all settled business. */
    await _withWallet(env, email, (ww) => { ww.pendingOut = []; });
    return 0;
  }
  const total = +stranded.reduce((n, p) => n + (+p.amount || 0), 0).toFixed(2);
  await _withWallet(env, email, (ww) => {
    ww.balance = +((+ww.balance || 0) + total).toFixed(2);
    const ids = new Set(stranded.map((p) => p.id));
    ww.pendingOut = (Array.isArray(ww.pendingOut) ? ww.pendingOut : []).filter((p) => p && !ids.has(p.id));
  });
  audit(env, 'withdraw_stranded_returned', { seller: email, amount: total, ids: stranded.map((p) => p.id) });
  return total;
}

async function marketWithdraw(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  const ageBadW = await _moneyAgeGate(env, user.email);
  if (ageBadW) return json(ageBadW, ageBadW.code === 'age_required' ? 428 : 403);
  /* The one place the hold stops money LEAVING rather than being spent, and
     the one where it is irreversible: a payout is a transfer AMV cannot claw
     back, so an account blocked for charging back must not be able to take
     cash out while an operator is still looking at it. Nothing is lost by
     waiting - the balance stays theirs, and clearing the block releases it. */
  {
    const heldW = await _accountHold(env, user, 'withdraw');
    if (heldW) return heldW;
  }
  const { destination } = await request.json().catch(() => ({}));
  /* Taking money OUT is the one a parent most needs to be able to stop. */
  if (user.family && user.family.limits && !user.family.limits.payouts) {
    return json({ error: 'Withdrawing money is turned off for your account. Whoever manages your family can turn it on.',
                  code: 'family_blocked' }, 403);
  }
  /* Where the money is meant to GO. Only the browser checked this, so a request
     without it zeroed the seller's balance and wrote a pending payout the
     operator had no way to fulfil - the money left the balance and arrived
     nowhere, which is the same failure AMV-089 was written to end. Checked
     BEFORE anything is debited, and AFTER the family block: somebody who may
     not withdraw at all is told that, rather than being asked to fill in a
     destination for a withdrawal that was never going to be allowed. */
  const dest = String(destination == null ? '' : destination).trim().slice(0, 200);
  if (dest.length < 3) {
    return json({ error: 'Tell AMV where to send the money - a PayPal email or a bank reference. Nothing has been withdrawn.',
                  code: 'destination_required' }, 400);
  }
  // Serialize withdrawals per seller so two concurrent requests can't both read
  // the same balance and each create a payout for it (double withdrawal). The
  // lock is atomic on D1; on KV it is a best-effort short-TTL guard. Balance is
  // re-read INSIDE the lock.
  if (!(await _claimOnce(env, 'wdlock', user.email, 30))) {
    return json({ error: 'A withdrawal is already being processed. Please try again in a moment.' }, 409);
  }
  try {
    /* Anything a previous attempt debited for a payout that was never written
       goes back before this one decides what is available. Under the same lock,
       so it cannot race the withdrawal it is correcting. */
    try { await _reconcileStrandedPayouts(env, user.email); }
    catch (e) { audit(env, 'withdraw_reconcile_failed', { seller: user.email, error: String((e && e.message) || e).slice(0, 160) }); }
    /* A wallet that cannot be read used to come back as a fresh zero, so this
       path answered "Minimum withdrawal is $10. You have $0.00 available." to
       a seller with money - a specific, confident, false number, at the one
       moment they are trying to get paid. It refuses, and says which. */
    let w;
    try { w = await _wallet(env, user.email); }
    catch (e) {
      if (!(e instanceof UnreadableRecordError)) throw e;
      try { await alertOnce(env, 'wallet_corrupt', 'A seller wallet record is unreadable, so a withdrawal was refused. Check the audit log for record_corrupt.', 60); } catch (_) {}
      return json({ error: 'AMV could not read your balance, so it will not process a withdrawal against a number it does not have. Nothing has been debited and your money is untouched. This has been reported.',
                    code: 'wallet_unreadable' }, 503);
    }
    /* Only what has cleared. The balance may be larger - held money is still
       theirs and still shown - but it cannot leave until the dispute window has
       substantially passed, or a seller could outrun a chargeback and leave AMV
       holding it. */
    const available = _availableOf(w);
    if (available < MARKET_MIN_WITHDRAW) {
      const nextAt = _nextClearingAt(w);
      const held = +((+w.balance || 0) - available).toFixed(2);
      /* Said as a matter of time rather than a refusal, because for an honest
         seller that is exactly what it is. */
      const when = nextAt
        ? ' $' + held.toFixed(2) + ' is still clearing and becomes available on '
          + new Date(nextAt).toISOString().slice(0, 10) + '.'
        : '';
      return json({ error: `Minimum withdrawal is $${MARKET_MIN_WITHDRAW}. You have $${available.toFixed(2)} available.` + when,
                    code: 'not_cleared', available, held, holdDays: PAYOUT_HOLD_DAYS,
                    availableAt: nextAt || null }, 400);
    }
    const amount = available;
    const wid = 'wd_' + crypto.randomUUID().slice(0, 12);

    /* DECIDED HERE, so the queue is the exceptions rather than the business.
       A payout with nothing against it clears itself; anything with a reason
       goes to a person, carrying the reasons so they are deciding rather than
       guessing. 'blocked' still creates the record - the seller is told, the
       money stays theirs, and an operator can override - because a scoring
       system that can silently delete somebody's earnings is worse than the
       fraud it prevents. */
    const risk = await _payoutRisk(env, user.email, amount, w);
    const status = risk.tier === 'auto' ? 'approved' : 'pending';

    /* THE MONEY LEAVES THE BALANCE BEFORE ANYTHING PROMISES IT.

       This wrote the payout record first and debited afterwards, and the gap
       between the two was a way to be paid twice. Nothing subtracts a payout
       already in flight when working out what is available - `_availableOf` is
       balance minus unmatured holds, and `_payoutsInFlight` is only ever read
       as a risk signal - so a debit that did not happen left the full amount
       still withdrawable with an approved payout already standing against it.
       The seller asks again, a second record is written, and an operator
       working the queue sends the money twice.

       It does not take an exception. A Worker can be cut off mid-request, and
       the window was two storage writes wide.

       So the debit comes first, in the lock, together with a marker naming the
       payout it is for. Between here and the record being written the money is
       neither spendable nor promised, which is the only state that cannot be
       double-spent. `_reconcileStrandedPayouts` above puts it back if the
       record never appeared. */
    /* Take out only what left. This used to zero the whole balance, which was
       right when everything was withdrawable and is silent theft now: money
       still inside its clearing window would vanish along with the payout, and
       the seller would never see it again. The holds are untouched - they are
       still that seller's money, still on the books, still on their own clock. */
    /* Under the SAME lock every other wallet change takes, re-reading inside
       it. The wdlock above stops two withdrawals racing each other; this stops
       a sale or a reversal landing in the middle of this one and writing back a
       balance it read before the payout. */
    await _withWallet(env, user.email, (ww) => {
      /* A destination that just changed is one of the signals above, so the
         change has to be recorded when it happens rather than inferred later. */
      if (ww.lastDest && ww.lastDest !== dest) ww.destChangedAt = Date.now();
      ww.lastDest = dest;
      ww.balance = +((+ww.balance || 0) - amount).toFixed(2);
      /* Debited, and owed. The marker is what tells a later attempt that this
         money left for a payout, so it can be given back if the payout record
         turns out never to have been written. */
      ww.pendingOut = (Array.isArray(ww.pendingOut) ? ww.pendingOut : [])
        .concat({ id: wid, amount, at: Date.now() }).slice(-20);
      /* The cleared tranches have now genuinely left; anything still inside its
         window stays, on its own clock. */
      _pruneMaturedHolds(ww);
    });
    try {
      await env.AMV_KV.put(`withdraw:${wid}`, JSON.stringify({
        id: wid, seller: user.email, amount, destination: dest,
        status, ts: Date.now(),
        risk: { tier: risk.tier, score: risk.score, reasons: risk.reasons },
        kycVerified: !!(risk.kyc && risk.kyc.verified),
        approvedBy: risk.tier === 'auto' ? 'auto' : '',
        approvedAt: risk.tier === 'auto' ? Date.now() : 0,
      }));
      /* It is unsettled from this moment. One of the two places that is true. */
      await _openPayoutAdd(env, user.email, wid);
    } catch (e) {
      /* The record is what makes the payout real, so without it the debit was
         for nothing and the money goes straight back. Told out loud: a balance
         that moved down and up again with no payout to show for it is exactly
         the kind of thing a seller writes in about. */
      await _withWallet(env, user.email, (ww) => {
        ww.balance = +((+ww.balance || 0) + amount).toFixed(2);
        ww.pendingOut = (Array.isArray(ww.pendingOut) ? ww.pendingOut : []).filter((p) => p && p.id !== wid);
      });
      audit(env, 'withdraw_rolled_back', { seller: user.email, amount, id: wid,
                                           error: String((e && e.message) || e).slice(0, 160) });
      throw e;
    }
    /* The record exists and is now the authority on what is owed, so the marker
       has done its job. */
    await _withWallet(env, user.email, (ww) => {
      ww.pendingOut = (Array.isArray(ww.pendingOut) ? ww.pendingOut : []).filter((p) => p && p.id !== wid);
    });
    await _pushWalletTx(env, user.email, { type: 'withdrawal', amount: -amount, status, id: wid, ts: Date.now() });
    /* Counted for the velocity signal and the identity threshold, both of which
       are about the pattern across payouts rather than this one. */
    await _withWallet(env, user.email, (ww) => {
      ww.payouts = (Array.isArray(ww.payouts) ? ww.payouts : []).concat({ at: Date.now(), amount }).slice(-20);
      ww.paidOut = +(((+ww.paidOut) || 0) + amount).toFixed(2);
    });
    audit(env, 'market_withdraw', { seller: user.email, amount, id: wid, tier: risk.tier, score: risk.score });

    /* An operator is told about the ones that need them, and NOT about the
       ordinary ones - a notification for every payout is how the ones that
       matter stop being read. */
    if (risk.tier !== 'auto') {
      await notify(env, `Payout needs review: $${amount.toFixed(2)} to ${user.email}`
        + ` (${risk.tier}, score ${risk.score}) - ` + risk.reasons.join('; '));
    }
    return json({ ok: true, amount, id: wid, status,
      /* The seller is told which of the two happened and why, because "pending"
         with no explanation is how somebody decides the platform is stealing
         from them. */
      message: risk.tier === 'auto'
        ? 'Approved. It will be sent on the next payout run.'
        : 'This payout is being reviewed before it is sent. ' + (risk.reasons[0] || '') + '.',
      reviewing: risk.tier !== 'auto' });
  } finally {
    await _releaseClaim(env, 'wdlock', user.email);
  }
}

/* =====================================================================
   AMV-089  PAYOUTS - the money had nowhere to go

   A seller could request a withdrawal. Their balance was zeroed, a debit was
   written to their transaction log, and a record was stored under
   `withdraw:<id>` - which nothing in the entire product ever read. No endpoint
   listed it, no screen showed it, and there was no way to mark one paid.

   So the seller's money left their balance and arrived nowhere, the operator
   had no idea they owed anybody anything, and the only trace was a KV key with
   no reader. That is destroyed user funds and an undisclosed liability at the
   same time, which makes it the worst defect in the product.

   Below: the operator can see what is owed, mark it paid, or reject it - and a
   rejection puts the money BACK, because a payout that cannot be fulfilled must
   return the balance rather than swallow it a second time.
   ===================================================================== */

/* ══════════════════════════════════════════════════════════════
   DECIDING PAYOUTS AT A SCALE WHERE NOBODY CAN READ THEM ALL.

   Every payout used to wait for the owner to mark it paid. That is right at
   ten sellers and impossible at ten thousand, and the alternative people reach
   for - approve everything - is how a marketplace gets drained. Neither is the
   answer, and the answer is not a bigger inbox.

   What payment platforms actually do, and what this does: decide each payout
   on evidence, release the ones that are provably ordinary, and send only the
   ones that are not to a person. The queue then stays the size of the problem
   rather than the size of the business.

   Three things carry the weight:

     the reserve   a percentage of every sale is held across the full dispute
                   window, so a late chargeback is taken from money AMV still
                   holds. See the hold split at the credit site.

     the score     account age, dispute and refund history, how concentrated
                   the sales are, how fast payouts are being requested, and
                   whether the destination just changed. Each is a reason a
                   person would give, so the answer can be explained.

     the tier      auto, review, or blocked. Nothing is ever auto-PAID by
                   accident: auto means AMV has cleared it, and money still
                   moves through whatever rail the operator has configured.

   Deliberately conservative where it is cheap to be: a payout wrongly sent to
   review costs somebody a day, a payout wrongly released costs the money. */
const PAYOUT_AUTO_MAX_USD       = 100;    // at or under this, and clean, releases itself
const PAYOUT_KYC_THRESHOLD_USD  = 600;    // cumulative payouts before identity is required
/* The SAME number, for a different reason, which is why it is written twice.

   $600 is where US information reporting starts - the point past which what
   AMV paid somebody in a CALENDAR YEAR has to be reported, and past which the
   taxpayer details had to be collected BEFORE the money went out rather than
   chased afterwards. The identity threshold above is about who somebody is and
   is fairly measured over their lifetime; this one is about a tax year and
   resets every January. Sharing one constant would mean the day the identity
   line moves for a fraud reason, the reporting line moves with it silently. */
const TAX_REPORT_THRESHOLD_USD  = 600;
const taxYearOf = (ts) => new Date(ts || Date.now()).getUTCFullYear();
const PAYOUT_RESERVE_PCT        = 0.10;   // of every sale, held across the dispute window
const PAYOUT_RESERVE_DAYS       = 120;    // how long a card dispute can take to arrive
const PAYOUT_RESERVE_MS         = PAYOUT_RESERVE_DAYS * 86400000;
const PAYOUT_MIN_AGE_DAYS       = 30;     // a brand new account is not a track record
const PAYOUT_VELOCITY_WINDOW_MS = 7 * 86400000;
const PAYOUT_VELOCITY_MAX       = 3;      // payouts in that window before it looks like cashing out

/* Identity. There is no provider wired, and this does not pretend there is:
   past the threshold a payout goes to REVIEW so a person verifies, rather than
   being auto-released or marked verified by something that checked nothing.
   When a provider key exists this reads its answer instead, and the threshold
   is also where the US 1099 reporting line sits, so it is a number worth
   keeping whatever the provider turns out to be. */
/* WHAT AMV PAID ONE PERSON IN ONE CALENDAR YEAR.

   This did not exist anywhere it could be read. `wallet.paidOut` is a lifetime
   running total with no year boundary; `wallet.payouts` keeps the last TWENTY,
   because it exists for the velocity signal; `wallet_tx` keeps 500. The
   `withdraw:` ledger does survive and carries seller, amount and time, but the
   only way to total a year from it is the admin scan - which lists KV in KEY
   order, caps at 5000 records and says so. At any size that matters, the one
   figure a 1099 requires could not be answered.

   So it is maintained where the money actually leaves, keyed by year first:
   `payoutyear:2026:seller@x.com`. The year-first key means the whole
   reporting population for a year is one prefix list rather than a scan of
   every withdrawal ever made.

   Deliberately NOT in PER_USER_KINDS. A tax record outlives an erasure
   request - that is what the legal-obligation carve-out in both GDPR and CCPA
   is for - and it is kept minimal for exactly that reason: what was paid, how
   many times, and when. Nothing about what was sold or to whom. */
async function _recordPaidForTax(env, email, amount, when) {
  const em = String(email || '').toLowerCase();
  const amt = +amount || 0;
  if (!em || !(amt > 0)) return null;
  const year = taxYearOf(when);
  try {
    return await _withKV(env, `payoutyear:${year}`, em, (r) => {
      r.email = em;
      r.year = year;
      r.paid = +(((+r.paid) || 0) + amt).toFixed(2);
      r.count = (+r.count || 0) + 1;
      r.firstAt = r.firstAt || (when || Date.now());
      r.lastAt = when || Date.now();
      r.reportable = r.paid >= TAX_REPORT_THRESHOLD_USD;
      return r;
    }, {});
  } catch (e) {
    /* The money HAS moved by the time this runs, so failing here must not
       unwind it - but a reporting figure that silently did not get written is
       how a filing comes out short, so it is both audited and alerted. */
    audit(env, 'tax_year_write_failed', { email: em, amount: amt, year, error: String((e && e.message) || e) });
    try { await alertOnce(env, 'tax_year_write',
      'A payout was sent but its calendar-year total could not be updated. The withdraw: record is still the source of truth - reconcile before filing.', 60); } catch (_) {}
    return null;
  }
}

/* What has been paid to somebody this year, for the threshold checks. */
async function _paidThisYear(env, email, when) {
  try {
    /* Read the way _withKV writes - straight from the namespace. DB.get would
       take the same string as a D1 `kind` column, and these rows are not
       written through DB, so the two would disagree on a D1 deployment. */
    const raw = await env.AMV_KV.get(`payoutyear:${taxYearOf(when)}:${String(email || '').toLowerCase()}`);
    if (!raw) return 0;
    const r = JSON.parse(raw);
    return +(r && r.paid) || 0;
  } catch (e) { return 0; }
}

async function _kycState(env, email) {
  try {
    const raw = await env.AMV_KV.get(`kyc:${String(email || '').toLowerCase()}`);
    if (!raw) return { verified: false, provider: '', checkedAt: 0 };
    const k = JSON.parse(raw);
    return { verified: !!k.verified, provider: k.provider || '', checkedAt: +k.checkedAt || 0 };
  } catch (e) { return { verified: false, provider: '', checkedAt: 0 }; }
}

/* Why this payout is or is not ordinary, in sentences somebody could read out.
   Returns { tier, score, reasons, kyc } and never throws - a scoring error must
   not become a released payout, so anything unexpected lands in review. */
async function _payoutRisk(env, email, amount, wallet) {
  const reasons = [];
  let score = 0;
  const em = String(email || '').toLowerCase();

  try {
    const acct = await DB.get(env, 'acct', em);
    const ageDays = acct && acct.createdAt ? (Date.now() - acct.createdAt) / 86400000 : 0;
    if (ageDays < PAYOUT_MIN_AGE_DAYS) {
      score += 40;
      reasons.push('the account is ' + Math.floor(ageDays) + ' days old, under the ' + PAYOUT_MIN_AGE_DAYS + '-day mark');
    }

    /* Disputes and refunds already recorded against this seller. This is the
       single strongest signal there is: somebody whose sales come back is
       somebody whose next payout is likely to be taken back too. */
    /* AMV-031: strict, because an unreadable abuse record reads as a seller
       with no disputes - the single strongest signal there is, answered wrong
       in the direction that releases the money. The whole function is wrapped
       in a handler that sends an unreadable state to a person. */
    const abuse = await DB.getStrict(env, 'abuse', em);
    const disputes = (abuse && +abuse.disputes) || 0;
    const refunds = (abuse && +abuse.refunds) || 0;
    if (disputes > 0) { score += 50 * Math.min(disputes, 3); reasons.push(disputes + ' payment dispute' + (disputes === 1 ? '' : 's') + ' on record'); }
    if (refunds > 2)  { score += 20; reasons.push(refunds + ' refunds on record'); }

    /* And an unreadable seller record reads as one who was never banned. */
    const standing = await DB.getStrict(env, 'seller', em);
    if (standing && standing.banned) { score += 200; reasons.push('selling access is suspended'); }
    else if (standing && +standing.strikes > 0) { score += 25 * +standing.strikes; reasons.push(+standing.strikes + ' policy strike(s)'); }

    /* Concentration. Fifty sales to fifty people is a business; fifty sales to
       two people is one person moving money through AMV, which is what
       wash-trading looks like from the inside. */
    /* AMV-040: THIS READ A FIELD NOTHING HAS EVER WRITTEN.

       Sales are recorded by _pushWalletTx into the separate `wallet_tx`
       record - the wallet itself has no `.tx`. So this list was always empty,
       `tx.length >= 3` was never true, and the concentration signal has never
       fired once. The most specific wash-trading check AMV has was dead code
       that read like working code, and a fraud check that cannot fire is worse
       than none: it is a reason not to look.

       Only settled sales count. A pending or reversed one is not evidence of
       anything, and counting it would let somebody manufacture the appearance
       of a broad customer base with purchases they later cancel. */
    /* Deliberately NOT caught here. The whole function is wrapped in a handler
       that escalates an unreadable state to human review, which is a better
       answer than this one scoring a partial penalty and letting the payout
       proceed. Swallowing the error locally would turn "AMV could not check"
       back into "AMV checked and found little", which is the exact confusion
       that made the original defect invisible. */
    const raw = await DB.get(env, 'wallet_tx', email);
    const tx = Array.isArray(raw) ? raw : [];
    const sales = tx.filter((t) => t && t.type === 'sale' && (t.buyer || t.from));
    const buyers = new Set(sales.map((t) => t.buyer || t.from).filter(Boolean));
    if (sales.length >= 3 && buyers.size <= 2) {
      score += 45;
      reasons.push('sales come from only ' + buyers.size + ' buyer' + (buyers.size === 1 ? '' : 's'));
    }

    /* Velocity. Cashing out fast is what somebody does when they expect the
       money to be taken back. */
    const recent = (wallet && Array.isArray(wallet.payouts) ? wallet.payouts : [])
      .filter(p => p && (Date.now() - (+p.at || 0)) < PAYOUT_VELOCITY_WINDOW_MS).length;
    if (recent >= PAYOUT_VELOCITY_MAX) { score += 30; reasons.push(recent + ' payouts in the last 7 days'); }

    /* A destination changed just before a withdrawal is the shape of a taken
       -over account being emptied. */
    const destAt = +(wallet && wallet.destChangedAt) || 0;
    if (destAt && (Date.now() - destAt) < 3 * 86400000) {
      score += 35; reasons.push('the payout destination changed in the last 3 days');
    }

    if (amount > PAYOUT_AUTO_MAX_USD) {
      score += 20;
      reasons.push('$' + amount.toFixed(2) + ' is over the $' + PAYOUT_AUTO_MAX_USD + ' automatic limit');
    }
  } catch (e) {
    /* A signal that could not be read is not a clean signal. */
    audit(env, 'payout_risk_error', { email: em, error: String((e && e.message) || e) });
    return { tier: 'review', score: 999, kyc: { verified: false }, 
             reasons: ['AMV could not finish checking this payout, so a person should look at it'] };
  }

  /* Identity, past the point where it is legally and practically required. */
  const kyc = await _kycState(env, em);
  const lifetimePaid = +(wallet && wallet.paidOut) || 0;
  if (!kyc.verified && (lifetimePaid + amount) > PAYOUT_KYC_THRESHOLD_USD) {
    score += 60;
    reasons.push('total payouts would pass $' + PAYOUT_KYC_THRESHOLD_USD + ' and identity has not been verified');
  }

  /* The reporting line, which is a different question from the identity one
     and was being answered with the lifetime figure. Somebody who was paid
     $400 in each of three years has passed the lifetime mark and has never
     been reportable; somebody paid $700 in their first year is reportable and
     has not passed anything measured over a lifetime. Asked of the calendar
     year, because that is what a filing covers. */
  const paidThisYear = await _paidThisYear(env, em);
  const yearAfter = +(paidThisYear + amount).toFixed(2);
  if (yearAfter >= TAX_REPORT_THRESHOLD_USD) {
    score += 30;
    reasons.push('this would bring ' + taxYearOf() + ' payouts to $' + yearAfter.toFixed(2)
      + ', at or past the $' + TAX_REPORT_THRESHOLD_USD + ' reporting line - taxpayer details are required before it is sent');
  }

  const tier = score >= 100 ? 'blocked' : (score > 0 ? 'review' : 'auto');
  return { tier, score, reasons, kyc, paidThisYear, yearAfter, taxYear: taxYearOf(),
           reportable: yearAfter >= TAX_REPORT_THRESHOLD_USD };
}

const ADMIN_PAYOUT_SCAN_MAX = 5000;
/* 'approved' is the step that did not exist. Before, a payout was either
   waiting for a person or already sent, so there was nowhere to record "AMV has
   decided this is fine and the money has not physically moved yet" - and money
   moving is a different act from money being cleared to move, done by whatever
   rail the operator has configured. Keeping them apart is what lets the
   decision be automatic without the disbursement being automatic. */
const PAYOUT_STATES = new Set(['pending', 'approved', 'paid', 'rejected']);

/* GET /admin/payouts - what is owed, and to whom. */
async function adminPayouts(request, env) {
  { const g = await _adminGate(request, env, 'read', 60, 2000); if (g) return g; }
  /* THE CAP IS REAL, SO IT HAS TO BE ADMITTED.

     This scanned until it held 5000 records, then sorted by time and showed
     the first 500. Both numbers were wrong past the cap and neither said so.
     KV lists in KEY order, not in time order, so the 5000 kept were an
     arbitrary slice of the withdrawals rather than the newest ones - which
     means the "recent 500" were the recent 500 OF AN ARBITRARY SLICE, and
     `owed`, the money taken out of sellers' balances that has not reached
     them, was summed over that same slice. It is the platform's liability,
     it under-reported in silence, and the direction of the error is the
     dangerous one: it makes the business look like it owes less than it does.

     A bounded scan that stops short has to say so - the rule from AMV-031.
     So the cap is still there, because an unbounded admin scan is its own
     outage, and the answer now carries whether it was hit and how much was
     read. A number that might be short is reported as one. */
  const out = [];
  let cursor;
  let truncated = false;
  do {
    const page = await env.AMV_KV.list({ prefix: 'withdraw:', cursor, limit: 1000 });
    for (const k of (page.keys || [])) {
      const raw = await env.AMV_KV.get(k.name);
      if (!raw) continue;
      try { out.push(JSON.parse(raw)); } catch (e) {}
    }
    cursor = page.list_complete ? undefined : page.cursor;
    if (cursor && out.length >= ADMIN_PAYOUT_SCAN_MAX) { truncated = true; break; }
  } while (cursor);

  /* THE REPORTING YEAR, read from its own prefix rather than summed out of the
     scan above. This is the whole reason those records exist: the scan is
     capped, lists in key order and admits it may be short, so a filing built
     from it would be a floor. `payoutyear:2026:` is keyed year-first, so one
     year's reportable population is one prefix list, in whatever size it is.

     Still bounded - an unbounded admin scan is its own outage - but the bound
     is per year and the population past $600 is a small fraction of sellers,
     so it is a bound that is not expected to bite. It says so either way. */
  const year = Math.min(Math.max(parseInt(new URL(request.url).searchParams.get('taxYear'), 10) || taxYearOf(), 2020), 2200);
  const taxRows = [];
  let taxCursor, taxTruncated = false;
  do {
    const page = await env.AMV_KV.list({ prefix: `payoutyear:${year}:`, cursor: taxCursor, limit: 1000 });
    for (const k of (page.keys || [])) {
      const raw = await env.AMV_KV.get(k.name);
      if (!raw) continue;
      try { taxRows.push(JSON.parse(raw)); } catch (e) {}
    }
    taxCursor = page.list_complete ? undefined : page.cursor;
    if (taxCursor && taxRows.length >= ADMIN_PAYOUT_SCAN_MAX) { taxTruncated = true; break; }
  } while (taxCursor);
  const reportable = taxRows.filter(r => (+r.paid || 0) >= TAX_REPORT_THRESHOLD_USD)
                            .sort((a, b) => (+b.paid || 0) - (+a.paid || 0));

  out.sort((a, b) => (b.ts || 0) - (a.ts || 0));
  /* THE QUEUE IS NOW THE EXCEPTIONS. Payouts AMV cleared by itself are
     'approved' and are not what somebody has to read; 'pending' means a
     signal fired and a person is being asked. Separating them is the whole
     point - a queue that contains every payout is a queue nobody finishes,
     and then the risky ones are read with the same attention as the rest. */
  const pending = out.filter(w => (w.status || 'pending') === 'pending');
  const approved = out.filter(w => w.status === 'approved');
  return json({
    ok: true,
    payouts: out.slice(0, 500),
    /* The number that matters: money taken out of sellers' balances that has
       not yet reached them. It is a liability until it is paid. */
    /* Everything not yet sent is owed, whichever side of the decision it is
       on - an approved payout is still money AMV has taken from a seller's
       balance and not delivered. Reporting only the reviewed ones would make
       the liability look smaller the better the risk engine got. */
    owed: +[...pending, ...approved].reduce((n, w) => n + (+w.amount || 0), 0).toFixed(2),
    pendingCount: pending.length,
    approvedCount: approved.length,
    approvedTotal: +approved.reduce((n, w) => n + (+w.amount || 0), 0).toFixed(2),
    needsReview: pending.slice(0, 200).map(w => ({
      id: w.id, seller: w.seller, amount: w.amount, destination: w.destination, ts: w.ts,
      tier: (w.risk && w.risk.tier) || 'review',
      score: (w.risk && w.risk.score) || 0,
      reasons: (w.risk && w.risk.reasons) || [],
      kycVerified: !!w.kycVerified,
    })),
    /* What was actually PAID in the year, per seller, and who is past the
       reporting line. Sent whether or not anybody has crossed it, because an
       empty list is an answer and a missing field is a screen that quietly
       stops showing this the year nothing has been paid yet. */
    tax: {
      year,
      threshold: TAX_REPORT_THRESHOLD_USD,
      sellers: taxRows.length,
      paidTotal: +taxRows.reduce((n, r) => n + (+r.paid || 0), 0).toFixed(2),
      reportableCount: reportable.length,
      reportableTotal: +reportable.reduce((n, r) => n + (+r.paid || 0), 0).toFixed(2),
      reportable: reportable.slice(0, 500).map(r => ({
        seller: r.email, paid: r.paid, payouts: r.count, firstAt: r.firstAt, lastAt: r.lastAt,
      })),
      truncated: taxTruncated,
      note: taxTruncated
        ? 'More sellers were paid this year than this scan reads, so these totals are a floor. The payoutyear: records are complete - raise the scan limit or read them directly before filing.'
        : undefined,
    },
    autoMaxUSD: PAYOUT_AUTO_MAX_USD,
    kycThresholdUSD: PAYOUT_KYC_THRESHOLD_USD,
    reservePct: PAYOUT_RESERVE_PCT,
    reserveDays: PAYOUT_RESERVE_DAYS,
    paidTotal: +out.filter(w => w.status === 'paid').reduce((n, w) => n + (+w.amount || 0), 0).toFixed(2),
    /* Said out loud, in the answer, so a screen cannot present a partial total
       as a complete one. */
    scanned: out.length,
    truncated,
    scanLimit: ADMIN_PAYOUT_SCAN_MAX,
    note: truncated
      ? 'More withdrawal records exist than this scan reads, so these totals are a floor rather than the full picture. Settle the pending ones and they stop accumulating.'
      : undefined,
  });
}

/* POST /admin/payouts/mark { id, status, note } */
async function adminPayoutMark(request, env) {
  { const g = await _adminGate(request, env, 'read', 60, 2000); if (g) return g; }
  const body = await request.json().catch(() => ({}));
  const id = String(body.id || '');
  const status = String(body.status || '');
  if (!/^wd_[A-Za-z0-9-]{4,40}$/.test(id)) return json({ error: 'bad id' }, 400);
  if (!PAYOUT_STATES.has(status) || status === 'pending') return json({ error: 'status must be approved, paid or rejected' }, 400);

  /* SERIALIZED, because rejecting CREDITS a wallet.

     The already-settled check below is a read followed by a decision, which two
     concurrent requests both pass: each reads 'pending', each writes the new
     status, and each adds the amount back to the seller's balance. One rejected
     payout, paid back twice, out of nothing.

     It does not need a hostile caller. The founder dashboard left both buttons
     live for the whole round trip, so a double-click was the ordinary way to
     produce it. marketWithdraw, one function above, already takes this lock for
     exactly this reason - this was the settle side of the same money with
     nothing holding it. */
  if (!(await _claimOnce(env, 'polock', id, 30))) {
    return json({ error: 'This payout is already being settled. Give it a moment.', code: 'in_progress' }, 409);
  }
  try {
    // Re-read INSIDE the lock: whoever held it before us may have settled it.
    const raw = await env.AMV_KV.get(`withdraw:${id}`);
    if (!raw) return json({ error: 'not found' }, 404);
    let rec = null; try { rec = JSON.parse(raw); } catch (e) { return json({ error: 'not found' }, 404); }
    /* An APPROVED payout is still settleable - approved means AMV cleared it,
       not that the money moved, so marking it paid (or rejecting it after a
       second look) is exactly what an operator does next. Only a terminal
       state refuses. */
    /* AMV-011: A REJECTED PAYOUT WITH AN UNFINISHED REFUND IS NOT FINISHED.

       Settling twice would pay twice or refund twice, so a terminal state
       refuses - with one exception, which is the whole finding. The status is
       written before the money moves, deliberately: the note below explains
       that the alternative risks crediting and then leaving the record
       settleable again, and it is right about that.

       What it misses is what the chosen order costs. If the credit fails, the
       payout is terminally 'rejected' and the seller's balance was never
       returned - the money was debited when they asked, and it is now neither
       in flight nor back. They are simply out of pocket, silently, and the only
       recovery was somebody noticing.

       Both orders have a bad failure, so the answer is neither order. The
       refund is claimed once and marked outstanding on the record until it
       lands. A rejected payout that still owes money can be settled again, and
       doing so completes the refund rather than repeating it. */
    const outstanding = +rec.refundDue || 0;
    if (!['pending', 'approved'].includes(rec.status || 'pending') && !(outstanding > 0)) {
      // Settling twice would either pay twice or refund twice. It is money.
      return json({ error: 'This payout was already ' + rec.status + '.', code: 'already_settled' }, 409);
    }
    if (outstanding > 0) {
      /* Finish what was started rather than deciding it again. The operator's
         requested status is ignored here: the decision was already made and
         recorded, and only the money is missing. */
      const done = await _refundRejectedPayout(env, rec);
      await env.AMV_KV.put(`withdraw:${id}`, JSON.stringify(rec));
      return json({ ok: true, id, status: rec.status,
                    refundCompleted: done,
                    message: done
                      ? 'The refund that was outstanding on this payout has been returned to the seller.'
                      : 'The refund is still outstanding. Try again in a moment.' }, done ? 200 : 503);
    }

    rec.status = status;
    rec.settledAt = Date.now();
    rec.note = String(body.note || '').slice(0, 200);
    /* Recorded as owed BEFORE the status is written, so a crash anywhere after
       this point leaves a rejected payout that says, on its own record, that a
       seller is still owed money. */
    if (status === 'rejected') rec.refundDue = +(+rec.amount || 0).toFixed(2);
    await env.AMV_KV.put(`withdraw:${id}`, JSON.stringify(rec));
    /* And it stops being unsettled here. The other one. Removed after the
       status is stored, so a failure between the two leaves an entry pointing
       at a settled payout - which _payoutsInFlight re-checks and ignores -
       rather than a payout in flight that nothing names. */
    await _openPayoutRemove(env, rec.seller, id);

    if (status === 'rejected') {
      /* Give it back. The balance was debited when the request was made; a
         payout that will never be sent has to return it, or rejecting is just a
         second way to destroy the same money. */
      /* UNDER THE LOCK EVERY OTHER WALLET WRITE TAKES.

         This read the wallet, added the amount and wrote the whole record back
         raw - the one writer in the product that did not go through
         _withWallet. `polock` serialises settlements of THIS payout and says
         nothing about the wallet, so a sale credit or another withdrawal
         landing in the middle was simply lost: the object written back here is
         the one read before they happened, so it takes their holds, their
         pendingOut and their balance with it.

         Both directions cost somebody money. The refund losing to a sale drops
         the refund; the refund winning drops the sale, and it restores a stale
         balance on top - money the seller may already have withdrawn. */
      await _refundRejectedPayout(env, rec);
      await env.AMV_KV.put(`withdraw:${id}`, JSON.stringify(rec));
    } else {
      // Mark the pending debit settled so the seller's log is not left ambiguous.
      await _pushWalletTx(env, rec.seller, { type: 'withdrawal_paid', amount: 0, status: 'paid', id, ts: Date.now() });
      /* HERE, and not at request time. `paidOut` is incremented when a payout
         is REQUESTED, which is deliberately conservative for the identity
         signal and wrong for tax: what is reportable is what was actually
         sent. A payout that ends up rejected never reaches this line, so a
         requested-then-refused payout does not inflate somebody's year. */
      const tax = await _recordPaidForTax(env, rec.seller, +rec.amount || 0, rec.settledAt);
      if (tax && tax.reportable && !(tax.count > 1 && (tax.paid - (+rec.amount || 0)) >= TAX_REPORT_THRESHOLD_USD)) {
        /* Announced once, on the payout that crosses the line - not on every
           payout after it, which is how the notice stops being read. */
        audit(env, 'tax_threshold_crossed', { seller: rec.seller, year: tax.year, paid: tax.paid });
        try { await notify(env, `${rec.seller} has passed $${TAX_REPORT_THRESHOLD_USD} in payouts for ${tax.year}`
          + ` ($${tax.paid.toFixed(2)}). Their taxpayer details are needed for reporting.`); } catch (_) {}
      }
    }
    audit(env, 'payout_settled', { id, seller: rec.seller, amount: rec.amount, status });
    return json({ ok: true, id, status });
  } finally {
    await _releaseClaim(env, 'polock', id);
  }
}

/* AMV-011: THE REFUND, ONCE, AND RECOVERABLE IF IT DOES NOT LAND.

   Rejecting a payout has to return the money that was debited when it was
   asked for, or rejecting is a second way to destroy the same money. The record
   carries `refundDue` from the moment the decision is written, so a failure
   anywhere in here leaves a rejected payout that says on its own face that a
   seller is still owed - and adminPayoutMark will finish it rather than
   refusing as already settled.

   Claimed once per payout, so completing it twice is impossible however many
   times it is attempted. Returns whether the money is now back.

   Mutates `rec` in place; the caller writes it. */
async function _refundRejectedPayout(env, rec) {
  const amount = +(+rec.refundDue || +rec.amount || 0).toFixed(2);
  if (!(amount > 0)) { delete rec.refundDue; return true; }
  let landed = false;
  try {
    const once = await _onceOrRetry(env, 'porefund', rec.id, CLAIM_ONCE_TTL_S, async () => {
      /* UNDER THE LOCK EVERY OTHER WALLET WRITE TAKES.

         This read the wallet, added the amount and wrote the whole record back
         raw - the one writer in the product that did not go through
         _withWallet. `polock` serialises settlements of THIS payout and says
         nothing about the wallet, so a sale credit or another withdrawal
         landing in the middle was simply lost. */
      await _withWallet(env, rec.seller, (ww) => {
        ww.balance = +((+ww.balance || 0) + amount).toFixed(2);
        /* AMV-041: AND THE LIFETIME TOTAL, WHICH ONLY EVER WENT UP.

           `paidOut` is added to when a payout is REQUESTED. Nothing took it
           back when one was rejected, so every refused request left the seller
           permanently credited with money AMV never sent. It feeds the point
           past which identity must be verified, so the error accumulates into
           asking an honest seller for documents they do not owe. Floored at
           zero: a total of money sent cannot be negative. */
        ww.paidOut = +Math.max(0, ((+ww.paidOut) || 0) - amount).toFixed(2);
        /* The velocity signal counts payouts in a window. One that was refused
           is not evidence of anything, so it stops counting too. */
        if (Array.isArray(ww.payouts)) {
          const i = ww.payouts.findIndex((p) => p && Math.abs((+p.amount || 0) - amount) < 1e-9);
          if (i > -1) ww.payouts.splice(i, 1);
        }
      });
      await _pushWalletTx(env, rec.seller, { type: 'withdrawal_returned', amount,
                                             status: 'rejected', id: rec.id, ts: Date.now() });
      return true;
    });
    /* `claimed: false` means another attempt already did it - which is a
       success from here, not a failure. */
    landed = once.claimed ? !!once.value : true;
  } catch (e) {
    audit(env, 'payout_refund_failed', { id: rec.id, seller: rec.seller, amount,
                                         error: String((e && e.message) || e).slice(0, 160) });
    try {
      await alertOnce(env, 'payout_refund_stuck',
        'A rejected payout could not be returned to the seller, so they are still short the amount that was '
        + 'debited when they asked for it. The payout record carries refundDue and settling it again completes '
        + 'the refund without repeating it.', 15);
    } catch (_) {}
    return false;
  }
  if (landed) delete rec.refundDue;
  return landed;
}

/* Seller changes a listing's status: active | sold | deactivated. Owner only. */
async function marketSetStatus(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  const { id, status } = await request.json().catch(() => ({}));
  if (!['active', 'sold', 'deactivated'].includes(status)) return json({ error: 'bad status' }, 400);
  const it = await _getListing(env, id);
  if (!it) return json({ error: 'not found' }, 404);
  if (it.authorEmail !== user.email) return json({ error: 'not your listing' }, 403);
  // SECURITY: a seller can never flip their own listing out of review or off a
  // moderation hold. Only deactivating is allowed while under review/removed.
  if ((it.status === 'under_review' || it.status === 'removed') && status === 'active') {
    return json({ error: 'This listing is under review and can\u2019t be activated until review completes.', code: 'under_review' }, 403);
  }
  // Re-screen on any activation, in case the stored content is prohibited.
  if (status === 'active') {
    const screen = _marketScreen(it, ((await DB.get(env, 'seller', user.email)) || {}).verifiedFor);
    if (!screen.ok) {
      await _withKV(env, 'market', id, (rec) => { if (rec) rec.status = 'removed'; });
      /* Cleared straight away rather than left to expire. A minute of
         staleness is fine for a catalogue and is NOT fine for something
         moderation just pulled - that minute is the whole harm. */
      await _marketCacheBust(env);
      return json({ error: screen.reason, code: 'policy_violation' }, 422);
    }
    if (screen.action === 'held_for_review') {
      await _withKV(env, 'market', id, (rec) => { if (rec) rec.status = 'under_review'; });
      await _marketCacheBust(env);
      return json({ ok: true, status: 'under_review' });
    }
  }
  /* Re-checked inside the lock: the listing may have SOLD between the
     ownership check above and this write, and putting it back to active would
     re-list something somebody has already bought. */
  const set = await _withKV(env, 'market', id, (rec) => {
    if (!rec) return null;
    if (rec.status === 'sold' && status === 'active') return false;
    rec.status = status;
    return true;
  });
  if (set === false) return json({ error: 'This listing has sold, so it cannot be put back on sale.', code: 'already_sold' }, 409);
  /* Deactivating is somebody taking their own listing down, and they will look
     straight at the catalogue to check that it went. */
  await _marketCacheBust(env);
  audit(env, 'market_status', { id, status, by: user.email });
  return json({ ok: true, status });
}

/* Increment a listing's view counter (best-effort analytics, not authed). */
async function marketView(request, env) {
  /* AMV-204: A VIEW COUNTER IS NOT A REASON TO REWRITE A LISTING.

     This read the whole listing, added one to `views`, and wrote the whole
     record back - with no auth, on every page load. Three things wrong with
     that, and the first is the expensive one:

       - the most FREQUENT write in the marketplace was racing the two that
         carry money. A visitor loading the page while a sale or a status change
         was being written put the old record back, so an item that had just
         sold went back on sale because somebody looked at it;
       - anyone could drive unlimited writes to one key by reloading, which is
         billed and is an abuse vector with no account behind it;
       - KV allows roughly one write per second per key, so the listing that
         gets popular - the only one where the count matters - throttles and
         loses its own views.

     The count lives in the counter now, which is what a counter is for: it is
     atomic, it is cheap, and it touches nothing else on the record. */
  /* AND BOUNDED PER SOURCE, which the counter alone does not do.

     The note above says the abuse problem "goes away" once the count moved off
     the record. Half of it did: the lost update and the hot key are gone. What
     did not is that this is an unauthenticated route which still costs a
     listing read and a counter increment per request, both billed, and it was
     the only public route in this Worker with nothing bounding it - every
     other one carries a guard.

     Generous, because a person browsing a marketplace really does open a lot of
     listings, and because getting this wrong makes the shop look broken. */
  const vg = await guardAction(env, 'mktview:' + (request.headers.get('CF-Connecting-IP') || 'anon'),
                               120, 5000, 'listing views');
  if (vg) return vg;

  const { id } = await request.json().catch(() => ({}));
  const key = String(id || '').slice(0, 64);
  if (!key) return json({ ok: true });
  const it = await _getListing(env, key);
  if (!it) return json({ ok: true });
  let views = (it.views || 0) + 1;
  try {
    const r = await counter(env, `mktviews:${key}`, { op: 'incr', amount: 1, ttlMs: 86400000 * 400 });
    /* The counter starts at zero for listings that existed before this, so the
       number already on the record is carried alongside rather than thrown away. */
    const since = (r && r.value) || 1;
    views = (it.views || 0) + since;
    /* The browse screen reads `views` off the record and cannot afford a
       counter read per listing, so the record is refreshed from the counter -
       under the lock, and only every MKT_VIEW_FOLD views. That is one write per
       fifty instead of one per view: the count on screen stays right, the
       hot-key and lost-update problems go away, and a write that does lose a
       race now costs at most a few views rather than a sale. The abuse half is
       the guard at the top of this function, not this - a counter makes each
       request cheap, it does not make the number of requests finite. */
    if (since >= MKT_VIEW_FOLD && since % MKT_VIEW_FOLD === 0) {
      await _withKV(env, 'market', key, (rec) => {
        if (!rec) return null;
        rec.views = (rec.views || 0) + since;
      });
      await counter(env, `mktviews:${key}`, { op: 'incr', amount: -since, ttlMs: 86400000 * 400 });
    }
  } catch (e) { /* a view that could not be counted is not worth failing over */ }
  return json({ ok: true, views });
}

/* Buyer rates a listing (item rating, 1-5). Recomputes the listing average. */
async function marketRate(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  const { id, stars } = await request.json().catch(() => ({}));
  const s = Math.max(1, Math.min(5, Math.round(Number(stars) || 0)));
  if (!(await _ownsItem(env, user.email, id))) return json({ error: 'buy it before rating' }, 403);
  /* AMV-043: the snapshot taken at purchase stands in for a listing the seller
     has since taken down. Somebody who paid for a thing may say what they
     thought of it, and whether the seller still offers it is not their
     business - a rating that disappears when the seller withdraws the item is a
     rating the seller controls. */
  const it = (await _getListing(env, id))
          || (await DB.get(env, 'mktsnap', `${user.email}:${id}`).catch(() => null));
  if (!it) return json({ error: 'not found' }, 404);
  /* PSEUDONYMOUS, LIKE THE REVIEWS RIGHT BELOW THIS.

     This used to store map[user.email] = stars. The record is keyed by the
     LISTING - somebody else's listing - so it is not in PER_USER_KINDS and it
     could not be: erasing the rater's account cannot reach a record filed under
     a seller's item. A rater's address therefore outlived their own deletion,
     with nothing anywhere able to find it.

     marketReview, the function immediately after this one, already stores a
     one-way hash and says why in its own comment: never the raw email, so a
     list can be shown publicly without leaking addresses. The same record, the
     same reasoning, one function apart, and only one of them did it.

     Existing maps are migrated in place. The keys ARE the addresses, and the
     hash is a pure function of the address, so every old key can be converted
     here without needing to know whose it is - and the average, which is all
     anybody reads, does not move. */
  /* AMV-042: THIS RECORD IS KEYED BY THE LISTING, SO ITS WRITERS ARE EVERY BUYER.

     Read-modify-write on a record one person owns is a race between their own
     tabs. On a record keyed by somebody else's LISTING it is a race between
     strangers: two buyers rating the same item at the same moment both read the
     map, both add themselves, and the later write drops the earlier rating.
     Popular items - the ones with the most raters - are exactly where it
     happens most, and the only symptom is a rating count that is quietly lower
     than the number of people who rated.

     The hashing and the migration move inside the lock with everything else.
     They read the map and rewrite every key in it, which is the largest
     read-modify-write in this function and was the one furthest from any lock. */
  const IS_HASH = /^[0-9a-f]{16}$/;
  const mine = await _errHash(user.email.toLowerCase());
  /* The hashes are computed before the lock: the mutate below is synchronous,
     and awaiting inside it would hold the lock across storage calls for every
     existing rater. */
  const preHashed = new Map();
  {
    let seed = {};
    try { const raw = await env.AMV_KV.get(`mkrate:${id}`); if (raw) seed = JSON.parse(raw); } catch {}
    for (const who of Object.keys(seed)) {
      if (!IS_HASH.test(who)) preHashed.set(who, await _errHash(String(who).toLowerCase()));
    }
  }
  let vals = [];
  await _withKV(env, 'mkrate', id, (map) => {
    const migrated = {};
    for (const [who, val] of Object.entries(map)) {
      /* A key that arrived between the pre-hash pass and the lock is left as it
         is rather than dropped - it is somebody's rating, and the next writer
         migrates it. Losing it to be tidy would be the defect this fixes. */
      migrated[IS_HASH.test(who) ? who : (preHashed.get(who) || who)] = val;
    }
    for (const k of Object.keys(map)) delete map[k];
    Object.assign(map, migrated);
    map[mine] = s;
    vals = Object.values(map);
  }, {});
  const rating = +(vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(1);
  /* AMV-204: the average goes onto the listing under the lock. Written from a
     copy read before a sale or a status change landed, a rating put the old
     record back - so an item that had just sold went back on sale because
     somebody rated it. */
  await _withKV(env, 'market', id, (rec) => {
    if (!rec) return null;
    rec.rating = rating;
    rec.ratings = vals.length;
  });
  return json({ ok: true, rating, ratings: vals.length });
}

/* Buyer reviews a SELLER (person) with 1-5 stars + text. Gated: must have
   bought at least one of that seller's listings. Stored under the seller. */
/* ══════════════════════════════════════════════════════════════
   REPORTING A LISTING - THE THING THE POLICY SAID ALREADY HAPPENED.

   The marketplace policy screen tells buyers, in the product, that "buyers can
   report any listing; reports are reviewed by our team". None of that existed.
   There was a _mktReport dialog in the browser that nothing opened, and if
   anything had opened it, it wrote the report to localStorage - in the
   REPORTER'S OWN BROWSER, where the only person who could ever read it is the
   person complaining. There was no route here at all.

   That is the worst shape a safety promise can take: somebody sees an abusive
   listing, believes they have told the platform, and nobody has been told.
   For a marketplace that takes payments and pays sellers out, the policy is
   also the thing an operator would be held to.

   So it is real. A report is a durable record on the server, it is audited, it
   alerts the operator, three of them hide the listing pending a decision, and
   the operator has a screen that lists them.

   Keyed by listing, not by reporter, because the question anybody asks later
   is "what has been said about THIS listing" - and because a per-reporter key
   would put somebody else's complaint inside the reported seller's own erasure
   scope. */
const REPORT_REASONS = new Set(['scam', 'stolen', 'illegal', 'sexual', 'harassment', 'broken', 'other']);
/* Enough independent reports that leaving it up is the bigger risk. Low on
   purpose: a wrongly hidden listing is one operator click to restore, and a
   scam left up while a queue is read is somebody's money. */
const REPORT_AUTOHIDE = 3;

async function marketReport(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'Please sign in to report a listing.' }, 401);
  /* Bounded: a report route is also a way to bury a competitor under noise,
     and a way to make AMV write storage as fast as somebody can click. */
  const g = await guardAction(env, `mktreport:${user.email}`, 5, 30, 'reporting listings');
  if (g) return g;

  const body = await request.json().catch(() => ({}));
  const id = String(body.id || '').slice(0, 80);
  const reason = String(body.reason || 'other');
  const note = String(body.note || '').slice(0, 1000);
  if (!id) return json({ error: 'Which listing?' }, 400);
  if (!REPORT_REASONS.has(reason)) return json({ error: 'Pick one of the listed reasons.' }, 400);

  const it = await _getListing(env, id);
  if (!it) return json({ error: 'That listing no longer exists.' }, 404);
  if ((it.authorEmail || '').toLowerCase() === user.email.toLowerCase())
    return json({ error: 'That is your own listing.' }, 400);

  /* Under the record's lock, because several people reporting the same listing
     at the same moment is the NORMAL case for anything worth reporting - and
     losing all but one of them is losing exactly the signal that mattered. */
  const byId = await _errHash(user.email.toLowerCase());
  let rec;
  try {
    rec = await _withKind(env, 'mktreport', id, (r) => {
      r.itemId = id;
      r.title = String(it.title || '').slice(0, 140);
      r.seller = it.authorEmail || '';
      r.reports = Array.isArray(r.reports) ? r.reports : [];
      /* One per person per listing. A second report from the same account
         updates what they said rather than counting twice, so the count means
         "how many different people" - which is the only version of the number
         worth acting on.

         Identified by a one-way hash, never the address. This record is keyed
         by the LISTING, so it sits outside the reporter's own erasure scope -
         and a complaint about somebody else's listing must not be the thing
         that keeps a reporter's email on the server after they have asked for
         it to be gone. The hash still dedupes, which is all it was for. */
      const prior = r.reports.find(x => x.by === byId);
      if (prior) { prior.reason = reason; prior.note = note; prior.ts = Date.now(); }
      else r.reports.push({ by: byId, reason, note, ts: Date.now() });
      /* Deduped per reporter, so this grows with distinct PEOPLE rather than
         with complaints - but distinct people is still unbounded, and the
         count that drives the auto-hide only needs the recent ones. */
      if (r.reports.length > 500) r.reports = r.reports.slice(-500);
      r.count = r.reports.length;
      r.lastAt = Date.now();
      if (!r.status) r.status = 'open';
      /* _withRecord hands back whatever the mutate returns, and writes back the
         object it loaded. Both matter here: the record is mutated IN PLACE so
         the write is the updated one, and it is returned so the count below is
         the count that was actually stored rather than one read again after
         the lock was let go. */
      return r;
    }, { itemId: id, reports: [], status: 'open' });
  } catch (e) {
    if (_isBusy(e)) return _busyJson('report');
    throw e;
  }

  audit(env, 'market_reported', { by: user.email, itemId: id, reason, count: rec.count });

  /* Enough people have said something that leaving it visible while a queue is
     read is the bigger risk. Hidden, not deleted - the seller keeps the work
     and the operator decides. */
  let hidden = false;
  if (rec.count >= REPORT_AUTOHIDE && !it.hidden) {
    try {
      await _withKind(env, 'market', id, (m) => {
        if (!m || !m.id) return;
        m.hidden = true;
        m.hiddenReason = 'reported';
        m.hiddenAt = Date.now();
      }, null);
      hidden = true;
      /* Out of the catalogue now. Auto-hiding is the response to enough people
         saying something is wrong, and leaving it on the front page for
         another minute is the exact risk the auto-hide exists to cut. */
      await _marketCacheBust(env);
      audit(env, 'market_autohidden', { itemId: id, count: rec.count });
    } catch (e) { if (!_isBusy(e)) throw e; }
  }

  try {
    await notify(env, `Listing reported (${rec.count}x): "${rec.title}" by ${rec.seller || 'unknown'} - reason: ${reason}.`
      + (hidden ? ' Hidden automatically pending review.' : ''));
  } catch (e) {}

  return json({ ok: true, count: rec.count, hidden,
    message: hidden
      ? 'Thank you. Enough people have reported this that it is now hidden while it is reviewed.'
      : 'Thank you. This has been sent for review.' });
}

/* What came in, for the person who has to act on it. */
async function adminReports(request, env) {
  { const g = await _adminGate(request, env, 'read', 60, 2000); if (g) return g; }
  /* DB.list hands back {id, value} rows, not the records themselves. Reading
     r.count off the wrapper gave every listing a count of zero and no seller -
     an operator screen that answers confidently with nothing in it, which is
     worse than one that fails. */
  const { rows, truncated } = await scan(env, 'mktreport', 2000, 'marketplace reports screen');
  const open = rows.map(r => r.value || {}).filter(r => (r.status || 'open') === 'open');
  open.sort((a, b) => (b.count || 0) - (a.count || 0) || (b.lastAt || 0) - (a.lastAt || 0));
  return json({
    ok: true,
    reports: open.slice(0, 200).map(r => ({
      itemId: r.itemId, title: r.title, seller: r.seller, count: r.count || 0,
      lastAt: r.lastAt || 0,
      reasons: [...new Set((r.reports || []).map(x => x.reason))],
      notes: (r.reports || []).map(x => x.note).filter(Boolean).slice(0, 5),
    })),
    openCount: open.length,
    total: rows.length,
    truncated,
    autoHideAt: REPORT_AUTOHIDE,
  });
}

async function marketReview(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  const { seller, stars, text } = await request.json().catch(() => ({}));
  const sellerEmail = String(seller || '').toLowerCase();
  if (!sellerEmail || sellerEmail === user.email) return json({ error: 'invalid seller' }, 400);
  /* AMV-043: from the purchase itself where it is recorded, and only then from
     the listing - which may not exist any more, and whose existence is the
     seller's own decision. The snapshot taken at purchase is the third place to
     look, because it is the copy a seller cannot touch. */
  const purchases = await _purchasesList(env, user.email);
  let bought = false;
  for (const p of purchases) {
    if (!p) continue;
    if (String(p.seller || '').toLowerCase() === sellerEmail) { bought = true; break; }
    /* Older purchases, recorded before the seller was written down. */
    if (!p.seller) {
      const snap = await DB.get(env, 'mktsnap', `${user.email}:${p.id}`).catch(() => null);
      if (snap && String(snap.authorEmail || '').toLowerCase() === sellerEmail) { bought = true; break; }
      const it = await _getListing(env, p.id);
      if (it && (it.authorEmail || '').toLowerCase() === sellerEmail) { bought = true; break; }
    }
  }
  if (!bought) return json({ error: 'You can only review sellers you\u2019ve bought from.' }, 403);
  const s = Math.max(1, Math.min(5, Math.round(Number(stars) || 0)));
  const key = `mkreview:${sellerEmail}`;
  // Screen review text - user-generated content that displays publicly.
  const reviewText = String(text || '').slice(0, 1000);
  const rScreen = _marketScreen({ text: reviewText, title: '' });
  if (!rScreen.ok && rScreen.action === 'blocked') {
    audit(env, 'market_review_blocked', { by: user.email, category: rScreen.category });
    return json({ error: 'Your review contains content that isn\u2019t allowed.', code: 'policy_violation' }, 422);
  }
  // AMV-059: store a PSEUDONYMOUS reviewer id (a non-reversible hash of the
  // email) for one-review-per-buyer dedup, plus a display name - never the raw
  // email, so a review list can be shown publicly without leaking addresses.
  const byId = await _errHash(user.email.toLowerCase());
  const entry = { byId, byName: (user.name || user.email.split('@')[0]).slice(0, 40), stars: s, text: reviewText, ts: Date.now() };
  /* AMV-042: keyed by the SELLER, so every buyer of theirs writes it. Two
     reviews landing together both read the list, both add themselves, and one
     disappears - and the buyer who lost is told their review was posted. */
  await _withKV(env, 'mkreview', sellerEmail, (list) => {
    const existing = list.findIndex(r => (r.byId || '') === byId || (r.by || '').toLowerCase() === user.email.toLowerCase());
    if (existing >= 0) list[existing] = entry; else list.unshift(entry);
    if (list.length > 500) list.length = 500;
  }, []);
  audit(env, 'market_review', { seller: sellerEmail, by: user.email, stars: s });
  return json({ ok: true, review: entry });
}

/* Deterministic thread id for a pair (order-independent) so both share one. */
function _threadId(a, b) { return 'mkthread:' + [String(a || '').toLowerCase(), String(b || '').toLowerCase()].sort().join('__'); }

/* A THREAD ID FROM A CALLER IS NOT A STORAGE KEY UNTIL IT LOOKS LIKE ONE.

   Two routes took `body.thread` and handed it straight to the namespace - one
   of them for a WRITE. Nothing bad happens today, because the membership check
   underneath needs the record to have `a` or `b` equal to the caller and only
   thread records have those. That is the whole guard, and it is a guard made
   of somebody else's schema: the day any other record gains an `a` or a `b`
   holding an address, this becomes a way to read and overwrite it by name.

   Every other route in this file validates before keying - a listing id, a
   payout id, a slug, a rating id. This is the one that did not, and the shape
   is fixed and cheap to insist on. */
const _threadKeyOK = (tid) =>
  /^mkthread:[^\s:]{1,120}__[^\s:]{1,120}$/.test(String(tid || ''));

/* Send a message to another user (buyer<->seller). Appends to the shared thread. */
/* WHO A MESSAGE IS ALLOWED TO REACH.

   AMV-185: the recipient used to be whatever address the caller typed. That
   makes this endpoint a way to put text into any inbox on the internet with
   AMV's name on the envelope, and no amount of screening the words fixes what
   the thing IS.

   So the recipient is derived, never supplied: from the listing being asked
   about, or from a conversation this account is already part of. Both are
   things the sender can only name because they already have a legitimate
   reason to. A raw address is accepted ONLY when it belongs to an existing AMV
   account AND a conversation with them already exists - which is a reply, not
   a first contact.

   Asking a seller a question before buying stays open on purpose. It is the
   question that starts most sales, and gating it behind a purchase would be
   protecting the marketplace from working. */
async function _messageRecipient(env, user, body) {
  const me = String(user.email).toLowerCase();

  /* About a listing: the seller is whoever published it. */
  if (body.item) {
    const it = await _getListing(env, String(body.item));
    if (!it) return { error: 'That listing no longer exists.', status: 404 };
    const seller = String(it.authorEmail || '').toLowerCase();
    if (!seller) return { error: 'That listing has no seller to message.', status: 404 };
    if (seller === me) return { error: 'That is your own listing.', status: 400 };
    return { email: seller, about: { id: it.id, title: it.title } };
  }

  /* A conversation that already exists, and that this account is part of. */
  const tid = body.thread ? String(body.thread) : '';
  if (tid) {
    /* Same guard as marketThreadRead: shaped like a thread key before it is
       used as one, so the membership test below is a second line rather than
       the only one. */
    if (!_threadKeyOK(tid)) return { error: 'That conversation does not exist.', status: 404 };
    let t = null;
    try { const raw = await env.AMV_KV.get(tid); if (raw) t = JSON.parse(raw); } catch (e) {}
    if (!t) return { error: 'That conversation does not exist.', status: 404 };
    const a = String(t.a || '').toLowerCase(), b = String(t.b || '').toLowerCase();
    if (a !== me && b !== me) return { error: 'That is not your conversation.', status: 403 };
    return { email: a === me ? b : a, thread: t };
  }

  /* A bare address: only as a reply into a conversation that already exists.
     A first message to a typed address is exactly the case being closed. */
  const typed = String(body.to || '').toLowerCase();
  if (!typed) return { error: 'Say who this is for - a listing, or a conversation.', status: 400 };
  if (typed === me) return { error: 'You cannot message yourself.', status: 400 };
  const key = _threadId(me, typed);
  let existing = null;
  try { const raw = await env.AMV_KV.get(key); if (raw) existing = JSON.parse(raw); } catch (e) {}
  if (!existing) {
    /* Deliberately the same answer whether or not that address has an account.
       "No such person" would turn this into a way to test which addresses are
       registered here. */
    return { error: 'You can only message people through one of their listings, or a conversation you already have.',
             status: 403, code: 'no_thread' };
  }
  return { email: typed, thread: existing };
}

async function marketMessage(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  // Messaging reaches another user - guard against spam/harassment.
  const blocked = await guardAction(env, `mktmsg:${user.email}`, 15, 300, 'messages');
  if (blocked) return blocked;
  const reqBody = await request.json().catch(() => ({}));
  const { text } = reqBody;
  const body = String(text || '').trim().slice(0, 2000);
  if (!body) return json({ error: 'empty message' }, 400);

  const who = await _messageRecipient(env, user, reqBody);
  if (who.error) return json({ error: who.error, code: who.code }, who.status || 400);
  const other = who.email;
  if (other === String(user.email).toLowerCase()) return json({ error: 'invalid recipient' }, 400);
  // Screen private messages - block prohibited content (illegal offers, CSAM, etc.)
  const mScreen = _marketScreen({ text: body, title: '' });
  if (!mScreen.ok && mScreen.action === 'blocked') {
    audit(env, 'market_message_blocked', { by: user.email, category: mScreen.category });
    return json({ error: 'That message contains content that isn\u2019t allowed on the marketplace.', code: 'policy_violation' }, 422);
  }
  const key = _threadId(user.email, other);
  /* AMV-196: READ, APPEND, WRITE - AND THE OTHER PERSON'S REPLY IS GONE.

     A thread has two writers by definition. Both replying in the same moment
     read the same thread and both write it back, so one message vanishes: no
     error anywhere, and the sender keeps seeing it in their own copy of the
     conversation. They find out it never arrived when the other person answers
     something else, or never answers at all.

     `who.thread` is the copy _messageRecipient read BEFORE any of this, so it
     is used only when there is nothing stored at all - otherwise appending to
     it would be the same lost write with an extra step. */
  let t = null;
  try {
    t = await _withRecord(env, 'mktthread', key,
      async (e, k) => { try { const raw = await e.AMV_KV.get(k); return raw ? JSON.parse(raw) : null; } catch (err) { return null; } },
      async () => {},                    // written explicitly below, inside the lock
      async (stored) => {
        let th = stored || who.thread || null;
        if (!th) th = { id: key, a: user.email, b: other, aName: user.name || user.email.split('@')[0], bName: other.split('@')[0], msgs: [], read: {} };
        if (th.a === user.email) th.aName = user.name || th.aName; else th.bName = user.name || th.bName;
        /* What it is about, kept on the thread so the other side sees "about
           Vintage jacket" rather than a message from a stranger with no context. */
        if (who.about && !th.about) th.about = who.about;
        th.msgs = th.msgs || [];
        th.msgs.push({ from: user.email, text: body, ts: Date.now() });
        if (th.msgs.length > 500) th.msgs = th.msgs.slice(-500);
        /* READ MARKERS ARE COUNTS, not timestamps.

           They were timestamps, and nothing ever compared them to anything, so
           "unread" could not be computed on the server at all - which is part of
           why the inbox was reading localStorage. A count of messages a person
           has seen is comparable to the length of the thread, which is the whole
           question. */
        th.read = th.read || {};
        if (typeof th.read[user.email] !== 'number' || th.read[user.email] > th.msgs.length) th.read[user.email] = 0;
        th.read[user.email] = th.msgs.length;    // the sender has seen their own message
        await env.AMV_KV.put(key, JSON.stringify(th));
        return th;
      });
  } catch (e) {
    /* Not written. Say so, because a message that silently did not send is the
       one failure this whole route exists to prevent. A fault inside the append
       is NOT the same thing and must not be dressed up as "try again". */
    if (!_isBusy(e)) throw e;
    audit(env, 'market_message_busy', { from: user.email, to: other });
    return json({ error: 'That conversation was busy for a moment and your message was not sent. Please send it again.', code: 'thread_busy' }, 503);
  }
  /* Both sides now know this conversation exists without anybody having to
     find it by listing every thread in the product. Written after the message
     is safely stored, and best-effort: an index that missed one entry costs a
     rebuild, and failing the send because a convenience index did not write
     would lose the thing that actually mattered. */
  await _inboxIndexAdd(env, user.email, key);
  await _inboxIndexAdd(env, other, key);
  audit(env, 'market_message', { from: user.email, to: other });

  /* TELL THEM TO COME AND READ IT - and send them nothing else.

     The message body does NOT travel. If it did, this endpoint would still be
     a way to deliver an attacker's words and links into somebody's inbox, and
     deriving the recipient above would have bought nothing. They get who, and
     a way back to AMV. Best-effort: a notification that fails must not fail
     the send, because the message IS delivered - it is in their inbox. */
  const noteCtx = { from: (user.name || String(user.email).split('@')[0]), to: other,
                    about: (who.about && who.about.title) || (t.about && t.about.title) || '' };
  try { await _notifyNewMessage(env, noteCtx); } catch (e) {}
  return json({ ok: true, thread: t });
}

/* "Somebody messaged you on AMV." Who, and a link. Never the message. */
async function _notifyNewMessage(env, { from, to, about }) {
  if (!env.EMAIL_API_KEY) return false;
  const appUrl = String(env.APP_URL || '').replace(/\/$/, '');
  const link = appUrl ? appUrl + '?tab=market&inbox=1' : '';
  const who = _escHtml(String(from || 'Someone').slice(0, 60));
  const item = about ? _escHtml(String(about).slice(0, 80)) : '';
  return _sendEmail_message(env, to, `${String(from || 'Someone').slice(0, 60)} sent you a message on AMV`,
    _emailShell('You have a new message',
      `<p style="margin:0 0 18px;font-size:14px;line-height:1.65;color:#555"><b>${who}</b> sent you a message on AMV`
      + (item ? ` about <b>${item}</b>` : '') + '.</p>'
      + '<p style="margin:0 0 22px;font-size:14px;line-height:1.65;color:#555">Open AMV to read it and reply.</p>',
      link ? { label: 'Open your messages', url: link } : null,
      '<p style="margin:0;font-size:12px;line-height:1.6;color:#999">For your safety the message itself is not included in this email. '
      + 'Read it in AMV, where you can see who sent it and report anything that should not be there.</p>',
      'You received this because somebody messaged you on the AMV marketplace.'),
    `${String(from || 'Someone').slice(0, 60)} sent you a message on AMV`
    + (about ? ` about "${String(about).slice(0, 80)}"` : '') + '.\n\n'
    + 'Open AMV to read it and reply: ' + link + '\n\n'
    + 'For your safety the message itself is not included in this email.\n\n- The AMV team');
}

/* Opening a conversation clears its badge. Only for a thread you are in. */
async function marketThreadRead(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  const { thread } = await request.json().catch(() => ({}));
  const tid = String(thread || '');
  if (!tid) return json({ error: 'which conversation?' }, 400);
  /* Shaped like a thread key before it is used as one - the membership check
     below must not be the only thing standing between a caller-supplied
     string and a write to that name. */
  if (!_threadKeyOK(tid)) return json({ error: 'not found' }, 404);
  let t = null;
  try { const raw = await env.AMV_KV.get(tid); if (raw) t = JSON.parse(raw); } catch (e) {}
  if (!t) return json({ error: 'not found' }, 404);
  const me = String(user.email).toLowerCase();
  if (String(t.a || '').toLowerCase() !== me && String(t.b || '').toLowerCase() !== me)
    return json({ error: 'not your conversation' }, 403);
  t.read = t.read || {};
  t.read[me] = (t.msgs || []).length;
  await env.AMV_KV.put(tid, JSON.stringify(t));
  return json({ ok: true, unread: 0 });
}

/* List the current user's message threads (newest first). */
/* ONE PERSON'S CONVERSATIONS, WITHOUT LISTING EVERYBODY'S.

   A thread key encodes both participants - `mkthread:a@x.com__b@x.com` - so
   the inbox filtered on the key and avoided reading other people's threads.
   That is the cheap half. The expensive half is that it still LISTED every
   thread key in the product, on every inbox load, with no cap: the work grew
   with total conversations rather than with the caller's.

   The key shape also cannot be narrowed by prefix, because the pair is sorted
   - somebody whose address sorts second appears in the middle of the key and
   no prefix reaches them. So it is an index, built on first use like the
   seller one, for the same reason: the alternative is a migration, and the
   old scan is already the correct answer, just once instead of every time. */
async function _inboxIndexAdd(env, email, threadKey) {
  const em = String(email || '').toLowerCase();
  if (!em || !threadKey) return;
  try {
    await _withKV(env, 'mktinbox', em, (r) => {
      r.ids = Array.isArray(r.ids) ? r.ids : [];
      /* Moved to the end rather than skipped, so the most recent conversation
         is the last to be dropped when the cap bites. */
      r.ids = r.ids.filter(x => x !== threadKey).concat(threadKey);
      if (r.ids.length > MKT_INDEX_MAX) r.ids = r.ids.slice(-MKT_INDEX_MAX);
      r.built = r.built || Date.now();
      return r;
    }, { ids: [], built: 0 });
  } catch (e) { audit(env, 'inbox_index_failed', { email: em, error: String((e && e.message) || e) }); }
}

async function _inboxThreadKeys(env, email) {
  const me = String(email || '').toLowerCase();
  try {
    const raw = await env.AMV_KV.get(`mktinbox:${me}`);
    if (raw) {
      const r = JSON.parse(raw);
      if (r && r.built) return { ids: Array.isArray(r.ids) ? r.ids : [], truncated: false };
    }
  } catch (e) { /* unreadable index: rebuild below rather than fail the inbox */ }

  const ids = [];
  let cursor, scanned = 0, truncated = false;
  do {
    const page = await env.AMV_KV.list({ prefix: 'mkthread:', cursor, limit: 1000 });
    for (const k of (page.keys || [])) {
      scanned++;
      if (k.name.includes(me)) ids.push(k.name);
    }
    cursor = page.list_complete ? undefined : page.cursor;
    if (cursor && scanned >= MKT_SCAN_MAX) { truncated = true; break; }
  } while (cursor);

  /* A partial backfill is not written as complete - somebody would lose the
     conversations past the cap for good, which is worse than a slow page. */
  if (!truncated) {
    try { await env.AMV_KV.put(`mktinbox:${me}`, JSON.stringify({ ids: ids.slice(-MKT_INDEX_MAX), built: Date.now() })); } catch (e) {}
  } else {
    audit(env, 'inbox_index_partial', { email: me, scanned });
  }
  return { ids, truncated };
}

async function marketThreads(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  const me = user.email.toLowerCase();
  const out = [];
  const idx = await _inboxThreadKeys(env, me);
  for (const name of idx.ids) {
    const raw = await env.AMV_KV.get(name);
    if (!raw) continue;
    /* Membership is re-checked against the RECORD, not taken from the index.
       An index is a convenience; it is not an authorization, and a wrong entry
       must not become a way to read somebody else's conversation. */
    try { const t = JSON.parse(raw); if (t.a === me || t.b === me) out.push(t); } catch (e) {}
  }
  out.sort((x, y) => (y.msgs[y.msgs.length - 1]?.ts || 0) - (x.msgs[x.msgs.length - 1]?.ts || 0));
  /* Unread computed HERE, from the record, so both devices and both people
     agree. The client used to work it out from its own localStorage, which is
     how one side could see a conversation the other had never received. */
  const withUnread = out.map(t => {
    const seen = (t.read && typeof t.read[me] === 'number') ? t.read[me] : 0;
    const total = (t.msgs || []).length;
    const last = (t.msgs || [])[total - 1];
    /* Only messages from the OTHER person count as unread - your own reply is
       not something waiting for you. */
    const unread = (last && String(last.from || '').toLowerCase() !== me) ? Math.max(0, total - seen) : 0;
    return Object.assign({}, t, { unread });
  });
  return json({ ok: true, threads: withUnread,
                unreadTotal: withUnread.reduce((n, t) => n + (t.unread ? 1 : 0), 0) });
}

/* =====================================================================
   FOUNDER ADMIN - token-gated platform monitoring (auditor #10)
   Lets the operator see real platform-wide spend, users, and abuse signals,
   plus flip the kill switch and inspect/adjust a single user. Protected by
   ADMIN_TOKEN (a secret only you hold) - NOT by user auth, so a normal user
   token can never reach it.
   ===================================================================== */
// increment a short-lived failed-login counter (15-min window) for brute-force defense
async function _noteAuthFail(env, key){
  try{
    const n = parseInt(await env.AMV_KV.get(key) || '0', 10) + 1;
    await env.AMV_KV.put(key, String(n), { expirationTtl: 900 });
  }catch(e){}
}


/* Mark a user active today, counted at most ONCE per day (unique DAU). We set a
   per-user marker with a 2-day TTL; the first mark of the day bumps the counter. */
async function _markActive(env, email){
  try{
    const day = todayKey();
    const marker = `active:${email}:${day}`;
    if(await env.AMV_KV.get(marker)) return;              // already counted today
    await env.AMV_KV.put(marker, '1', { expirationTtl: 2 * 86400 });
    const key = `grow:active:${day}`;
    const cur = parseInt(await env.AMV_KV.get(key) || '0', 10) || 0;
    await env.AMV_KV.put(key, String(cur + 1), { expirationTtl: 60 * 86400 });
    /* Coming back is a SECOND distinct day, not a second session - somebody who
       opens AMV twice in one afternoon has not come back yet. The first active
       day is remembered for as long as the funnel counts, so this stays true
       for somebody who returns after a month. */
    const firstKey = `factive:${email}`;
    const first = await env.AMV_KV.get(firstKey);
    if(!first) await env.AMV_KV.put(firstKey, day, { expirationTtl: FUNNEL_TTL_S });
    else if(first !== day) await _funnelMark(env, email, 'returned');
  }catch(e){ /* best-effort */ }
}

/* ── Growth tracking: a tiny per-day counter so the owner can see TRENDS, not
   just a snapshot. One KV key per day (grow:signup:YYYY-MM-DD). 60-day TTL keeps
   it bounded. This is what turns "you have 40 users" into "signups are up 3x
   week over week" - the number that actually tells you if it's working. ── */
async function _recordGrowth(env, kind){
  const day = todayKey();
  const key = `grow:${kind}:${day}`;
  try{
    const cur = parseInt(await env.AMV_KV.get(key) || '0', 10) || 0;
    await env.AMV_KV.put(key, String(cur + 1), { expirationTtl: 60 * 86400 });
  }catch(e){ /* growth stats are best-effort, never block signup */ }
}

/* ── THE FUNNEL ────────────────────────────────────────────────────────────
   Plan population answers "who is paying now". It cannot answer the question
   that decides whether any of the product work is landing: of the people who
   signed up, how many ever got value, how many came back, and how many paid.

   Without it, first-run screens, activation nudges and onboarding copy are all
   judged on feel. With it they are judged on a number.

   Each step is marked ONCE PER USER, ever, and increments a cumulative counter -
   the same approach as the plan population, and for the same reason: the ratios
   stay exact at forty accounts and at four hundred thousand, with no scan.

   No step is inferred. `activated` is a real answer AMV produced for them,
   `returned` is a second distinct day, `paid` is a verified payment. A funnel
   made of proxies tells you a story rather than the truth. */
const FUNNEL_STEPS = ['signup', 'activated', 'returned', 'paid'];
const FUNNEL_TTL_S = 400 * 86400;

async function _funnelMark(env, email, step){
  try{
    /* Trimmed as well as lowercased, so one caller passing a raw typed address
       cannot file the same person under two identities. Normalising at the
       choke point rather than trusting five call sites to agree. */
    const em = String(email || '').toLowerCase().trim();
    if(!em || FUNNEL_STEPS.indexOf(step) < 0) return false;
    const k = `fstep:${em}:${step}`;
    if(await env.AMV_KV.get(k)) return false;            // already counted, ever
    await env.AMV_KV.put(k, String(Date.now()), { expirationTtl: FUNNEL_TTL_S });
    await counter(env, `funnel:${step}`, { op: 'incr', amount: 1 });
    if(step !== 'signup') await _recordGrowth(env, step);
    /* How long it took them to pay, accumulated rather than stored per user, so
       the average is available without reading every account. */
    if(step === 'paid'){
      const acct = await DB.get(env, 'acct', em);
      const age = acct && acct.createdAt ? Date.now() - acct.createdAt : 0;
      if(age > 0){
        await counter(env, 'funnelttpsum', { op: 'incr', amount: age / 86400000 });
        await counter(env, 'funnelttpn', { op: 'incr', amount: 1 });
      }
    }
    return true;
  }catch(e){ return false; }   // a funnel stat must never fail a real action
}

async function _funnelReport(env){
  const out = {};
  for(const step of FUNNEL_STEPS){
    try{ out[step] = Math.max(0, (await counter(env, `funnel:${step}`, { op: 'get' })).value || 0); }
    catch(e){ out[step] = 0; }
  }
  const n = out.signup || 0;
  const pct = v => (n > 0 ? +((v / n) * 100).toFixed(1) : null);
  let days = null;
  try{
    const sum = (await counter(env, 'funnelttpsum', { op: 'get' })).value || 0;
    const cnt = (await counter(env, 'funnelttpn', { op: 'get' })).value || 0;
    if(cnt > 0) days = +(sum / cnt).toFixed(1);
  }catch(e){}
  return {
    ...out,
    activatedPct: pct(out.activated),
    returnedPct: pct(out.returned),
    paidPct: pct(out.paid),
    avgDaysToPay: days,
    /* Counting started when this shipped, so accounts that existed before it
       are not in the denominator. Said out loud rather than left for somebody
       to discover when the numbers do not match the user count. */
    note: 'Counted from when funnel tracking was switched on, so accounts older than that are not included.',
  };
}

/* Read the last N days of a growth series as [{date, count}], oldest first. */
async function _growthSeries(env, kind, days){
  const out = [];
  const now = new Date();
  for(let i = days - 1; i >= 0; i--){
    const d = new Date(now.getTime() - i * 86400000);
    const key = `grow:${kind}:${d.toISOString().slice(0,10)}`;
    const v = parseInt(await env.AMV_KV.get(key) || '0', 10) || 0;
    out.push({ date: d.toISOString().slice(0,10), count: v });
  }
  return out;
}

async function adminStats(request, env) {
  /* AMV-052: through the SAME gate as every other admin route. This was a bare
     token comparison with no rate limit, so three of the sixteen admin routes
     were an unbounded channel for guessing the token while the other thirteen
     were not - and an attacker only has to find the unbounded one. */
  { const g = await _adminGate(request, env, 'read', 60, 2000); if (g) return g; }

  const today = todayKey(), month = monthKey();
  // global spend today (atomic counter) + cap
  const gSpend = (await counter(env, `spend:${today}`, { op: 'get' })).value || 0;
  const gCap = parseFloat(env.GLOBAL_DAILY_USD_CAP || '500');
  const killed = (await env.AMV_KV.get('GLOBAL_KILL')) === '1';

  // list entitlements (paying users) via the durable layer (D1 query or KV scan)
  let users = [], plans = { free: 0, pro: 0, elite: 0, ultra: 0, custom: 0, team: 0 };
  let mrr = 0, pastDue = 0, atRisk = 0;

  /* Bounded on purpose, and reported. Past this many accounts the per-account
     lists below are a sample - the headline money comes from the maintained
     counters instead, which are exact at any size. */
  const SCAN_LIMIT = 2000;
  const { rows: entRows, truncated } = await scan(env, 'ent', SCAN_LIMIT, 'owner stats screen');
  for (const row of entRows) {
    const e = row.value || {};
    const email = row.id;
    /* The EFFECTIVE plan, not the one that was sold. Counting a subscription
       whose payment failed as revenue overstates MRR and hides the problem -
       the owner needs to see money at risk, not money assumed. */
    const plan = _planOf(e);
    /* _planPriceUSD, not a local table: a per-seat plan's revenue is its seat
       count times the seat price, and a table keyed by plan name reports every
       Teams customer - however large - as zero. */
    if (e.pastDueSince) {
      pastDue++;
      atRisk += _planPriceUSD(e.plan, e.custom);
    }
    plans[plan] = (plans[plan] || 0) + 1;
    const revenue = _planPriceUSD(plan, e.custom);
    mrr += revenue;
    const cost = (await counter(env, `cost:${email}:${month}`, { op: 'get' })).value || 0;
    if (plan !== 'free' || cost > 0) users.push({ email, plan, monthCostUSD: +cost.toFixed(3), revenue });
  }

  /* AMV-071: UNIT ECONOMICS.
     A single blended cost number cannot answer the questions that decide
     whether this business works: is each tier profitable, which accounts cost
     more than they pay, and where is the money actually going. Those are the
     numbers you steer on, and none of them were here. */
  const cohorts = {};
  for (const u of users) {
    const c = cohorts[u.plan] || (cohorts[u.plan] = { plan: u.plan, users: 0, revenue: 0, cost: 0 });
    c.users++; c.revenue += u.revenue; c.cost += u.monthCostUSD;
  }
  const byPlanEconomics = Object.values(cohorts).map(c => ({
    plan: c.plan, users: c.users,
    revenue: +c.revenue.toFixed(2), cost: +c.cost.toFixed(2),
    grossMargin: +(c.revenue - c.cost).toFixed(2),
    // A free cohort has no revenue, so a margin PERCENTAGE is meaningless there
    // - null says "not applicable" instead of printing a fake -100%.
    grossMarginPct: c.revenue > 0 ? +(((c.revenue - c.cost) / c.revenue) * 100).toFixed(1) : null,
    costPerUser: +(c.cost / Math.max(1, c.users)).toFixed(3),
  })).sort((a, b) => b.revenue - a.revenue);

  /* The accounts that quietly destroy an AI business: paying, but costing more
     than they pay. Worth seeing individually, because the answer is usually a
     conversation rather than a limit. */
  const unprofitable = users
    .filter(u => u.revenue > 0 && u.monthCostUSD > u.revenue)
    .map(u => ({ email: u.email, plan: u.plan, revenue: u.revenue, cost: u.monthCostUSD,
                 lossUSD: +(u.monthCostUSD - u.revenue).toFixed(2) }))
    .sort((a, b) => b.lossUSD - a.lossUSD).slice(0, 20);
  // Free users cost real money too - that is the price of the funnel, and it
  // belongs on screen next to what the funnel returns.
  const freeCost = +(cohorts.free ? cohorts.free.cost : 0).toFixed(2);

  // Where the money went this month, and what caching saved.
  const features = ['chat', 'automation', 'sms', 'widget'];
  const featureCost = {};
  for (const feat of features) {
    const v = (await counter(env, `featcost:${feat}:${month}`, { op: 'get' })).value || 0;
    if (v > 0) featureCost[feat] = +v.toFixed(2);
  }
  const cacheSaved = +((await counter(env, `cachesave:${month}`, { op: 'get' })).value || 0).toFixed(2);

  // top spenders (who costs us most this month) - abuse / margin watch
  const topSpenders = [...users].sort((a, b) => b.monthCostUSD - a.monthCostUSD).slice(0, 20);
  /* AMV-088: when the scan saw everything, the scan IS the truth and the
     counters are checked against it. When it did not, the counters are the only
     thing that can be right - and the response says which happened, so nobody
     reads a sample as a total. */
  /* AMV-095: whether the answers are any good - the one number that decides
     whether anyone stays, and the only one that was never measured. */
  const quality = await _qualityReport(env);
  /* AMV-098: how long people waited. The average is the headline; the buckets
     are what tell you whether it is one bad engine or all of them. */
  const speed = await (async () => {
    const sum = (await counter(env, `ttfbsum:${month}`, { op: 'get' })).value || 0;
    const n = (await counter(env, `ttfbn:${month}`, { op: 'get' })).value || 0;
    const buckets = {};
    for (const b of ['p500', 'p1000', 'p2500', 'p5000', 'slow']) {
      let total = 0;
      for (const k of Object.keys(ENGINES)) {
        total += (await counter(env, `ttfb:${k}:${b}:${month}`, { op: 'get' })).value || 0;
      }
      buckets[b] = total;
    }
    const fast = buckets.p500 + buckets.p1000;
    return { samples: n, avgFirstTokenMs: n ? Math.round(sum / n) : null, buckets,
             underOneSecondPct: n ? +((fast / n) * 100).toFixed(1) : null };
  })();
  const pop = await _planPopulation(env);
  const popTotal = Object.values(pop).reduce((a, b) => a + b, 0);
  /* Revenue on the per-seat plan is seats, not accounts, so it comes from the
     seat counter rather than from multiplying a head count by a price that does
     not exist for that plan. A custom plan's price is per account and unknown
     here, so the scan above is what carries it - reported, not guessed. */
  const seatsSold = await _teamSeatsSold(env);
  let popMrr = seatsSold * TEAM_SEAT_PRICE_USD;
  for (const [plan, n] of Object.entries(pop)) {
    if (plan === 'team' || plan === 'custom') continue;
    popMrr += _planPriceUSD(plan) * n;
  }
  const totalCost0 = (await counter(env, `costtotal:${month}`, { op: 'get' })).value || 0;

  if (truncated) {
    // The scan is a sample; take population and revenue from the counters.
    plans = pop;
    mrr = popMrr;
  }
  const paying = truncated
    ? Object.entries(pop).filter(([p]) => p !== 'free').reduce((n, [, v]) => n + v, 0)
    : users.filter(u => u.plan !== 'free').length;

  // Growth over time - the numbers that show whether it's WORKING, not just a
  // snapshot. 30-day signup + active series, plus today's figures.
  const signups30 = await _growthSeries(env, 'signup', 30);
  const active30 = await _growthSeries(env, 'active', 30);
  /* AMV-075: referral conversions, so the invite loop is a measured channel
     rather than a feature nobody can tell is working. A conversion is counted
     when an invited account has genuinely started using AMV - the same bar the
     reward is paid at - so this series is real activation, not raw signups. */
  const referrals30 = await _growthSeries(env, 'referral', 30);
  /* The top of the funnel. Everything else here starts at signup, so the
     largest group - people who looked and left - was invisible, and
     visitors-to-accounts is the number most marketing work is trying to move. */
  const visits30 = await _growthSeries(env, 'visit', 30);
  const visits7 = visits30.slice(-7).reduce((n, d) => n + d.count, 0);
  const signupsToday = signups30.length ? signups30[signups30.length - 1].count : 0;
  const activeToday = active30.length ? active30[active30.length - 1].count : 0;
  const referrals7 = referrals30.slice(-7).reduce((n, d) => n + d.count, 0);
  const signups7 = signups30.slice(-7).reduce((n, d) => n + d.count, 0);
  const signupsPrev7 = signups30.slice(-14, -7).reduce((n, d) => n + d.count, 0);
  const wowGrowthPct = signupsPrev7 > 0 ? +(((signups7 - signupsPrev7) / signupsPrev7) * 100).toFixed(0) : null;

  /* EVERY account, not every entitlement row.

     This read `entRows.length`, and a free signup creates no entitlement row -
     so the denominator was essentially the set of people who had already paid,
     and conversion reported ~100% no matter what the funnel was really doing.
     On a fixture of twenty free accounts and one payer it said 100% where the
     truth was 4.8%: the single most decision-corrupting number the dashboard
     could produce, because it says the funnel is perfect and there is nothing
     to fix.

     The maintained counter is exact at any size. It falls back to the scan on
     a deployment that predates it, where the old wrong answer is still better
     than none - and `basis` says which one this is, because a number whose
     meaning changes silently is how the first version of this got believed. */
  const popAccounts = (await counter(env, 'popaccounts', { op: 'get' })).value || 0;
  const countedAccounts = popAccounts > 0 ? popAccounts : entRows.length;
  const conversionBasis = popAccounts > 0 ? 'accounts' : 'entitlements';
  const conversionPct = countedAccounts > 0 ? +((paying / countedAccounts) * 100).toFixed(1) : 0;
  const arpu = paying > 0 ? +(mrr / paying).toFixed(2) : 0;

  return json({
    ok: true,
    generatedAt: Date.now(),
    spend: { today: +gSpend.toFixed(2), cap: gCap, pctOfCap: +(gSpend / gCap * 100).toFixed(1), killed },
    users: { total: truncated ? popTotal : users.length, paying, byPlan: plans,
             conversionPct, conversionBasis, accounts: countedAccounts, activeToday },
    /* Say plainly whether the per-account lists below are everything or a
       sample. The alternative is a number that is quietly wrong. */
    scan: { rows: entRows.length, limit: SCAN_LIMIT, truncated,
            note: truncated
              ? 'More accounts than one page can read. Revenue and population come from maintained counters and are exact; the per-account lists are the first ' + entRows.length + '.'
              : 'Every account was read.' },
    growth: { signupsToday, signups7, signupsPrev7, wowGrowthPct, signups30, active30,
              referrals7, referrals30, visits7, visits30,
              /* Of the people who arrived, how many became accounts. Null
                 rather than 0 when nothing has been counted yet, because "no
                 visitors recorded" and "nobody converted" are different facts
                 and showing 0% for the first is a lie about the product. */
              visitToSignupPct: visits7 > 0 ? +((signups7 / visits7) * 100).toFixed(1) : null,
              // What share of the last week's signups came through an invite.
              referralSharePct: signups7 > 0 ? +((referrals7 / signups7) * 100).toFixed(1) : null },
    /* Signup -> activated -> returned -> paid. The question every piece of
       onboarding work is trying to move, and the only one that says whether it
       did (AMV-101). */
    funnel: await _funnelReport(env),
    revenue: { estMRR: mrr, estARR: mrr * 12, arpu, pastDueAccounts: pastDue, mrrAtRisk: atRisk,
               teamSeatsSold: seatsSold, teamSeatMRR: seatsSold * TEAM_SEAT_PRICE_USD },
    margin: (() => {
      const scanCost = +users.reduce((s, u) => s + u.monthCostUSD, 0).toFixed(2);
      /* The maintained total is exact; the scanned sum is only exact when the
         scan saw everything. Prefer the counter, and fall back to the sum if it
         has not been populated yet (an existing deployment before this shipped). */
      const totalCost = +(totalCost0 > 0 ? totalCost0 : scanCost).toFixed(2);
      return {
        estMonthlyCost: totalCost,
        grossMargin: +(mrr - totalCost).toFixed(2),
        grossMarginPct: mrr > 0 ? +(((mrr - totalCost) / mrr) * 100).toFixed(1) : null,
        costPerPayingUser: paying > 0 ? +(totalCost / paying).toFixed(3) : 0,
        freeUserCost: freeCost,
        byPlan: byPlanEconomics,
        featureCost,
        cacheSavedUSD: cacheSaved,
        unprofitableAccounts: unprofitable,
      };
    })(),
    quality,
    speed,
    topSpenders,
  });
}

/* =====================================================================
   AMV-097  THE API - selling AMV to programs, not only to people

   Everything an API needs already existed: metering, per-plan quotas, the
   monthly cost backstop, atomic reservation, abuse controls, engine routing.
   What was missing was a way for a customer to reach any of it without a
   browser session, which is the difference between a $20 seat and a line item
   in someone's infrastructure budget.

   The design is deliberately boring, because the interesting parts are already
   solved:
     - A key is a credential for an ACCOUNT. It spends that account's quota and
       counts against that account's cost ceiling. There is no second budget to
       reason about, and no way for a leaked key to cost more than the plan.
     - Only the HASH is stored. A key is shown once, at creation, and can never
       be read back - because a store that can show you your key can show it to
       whoever reads the store.
     - A key can be scoped and revoked, and its last use is recorded, so a
       customer can tell a live key from a forgotten one.
   ===================================================================== */

const API_KEY_MAX_PER_USER = 10;
const API_KEY_PREFIX = 'amv_sk_';

function _newApiKey() {
  return API_KEY_PREFIX + crypto.randomUUID().replace(/-/g, '') + crypto.randomUUID().replace(/-/g, '').slice(0, 16);
}
/* SHA-256 of the key. Not a password - it is 48 random hex characters, so there
   is nothing to brute force and no salt to add; the hash exists so the store
   never holds the credential itself. */
async function _apiKeyHash(key) {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(String(key)));
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
}
/* What a customer can see about their own key: enough to recognise it, never
   enough to use it. */
function _apiKeyPublic(k) {
  return { id: k.id, name: k.name, last4: k.last4, created: k.created,
           lastUsed: k.lastUsed || null, revoked: !!k.revoked, calls: k.calls || 0 };
}

/* POST /v1/keys/create { name } -> the key, ONCE */
async function apiKeyCreate(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  /* An API key is how an account is spent without anyone watching, so a lapsed
     or free account does not get one - the same rule the rest of the paid
     surface uses, applied where it can be explained. */
  const budget = await _budgetFor(env, user);
  if (budget.free) {
    return json({ error: 'API keys are part of a paid plan. Upgrade and you can create one straight away.',
                  code: 'plan_required' }, 402);
  }
  const blocked = await guardAction(env, `keycreate:${user.email}`, 5, 20, 'API keys');
  if (blocked) return blocked;

  const body = await request.json().catch(() => ({}));
  const name = String(body.name || 'API key').slice(0, 60).trim() || 'API key';

  const key = _newApiKey();
  const hash = await _apiKeyHash(key);
  /* The hash is kept on the record too, and it has to be: revoking marks this
     item AND deletes the lookup the request path reads. Without the hash here
     there would be nothing to delete, so a "revoked" key would keep working -
     which is the worst possible way for a revoke button to fail. It is a hash,
     not the key, and _apiKeyPublic never returns it. */
  const item = { id: 'k_' + crypto.randomUUID().slice(0, 12), name, hash,
                 last4: key.slice(-4), created: Date.now(), calls: 0 };
  /* AMV-053: THE CAP AND THE APPEND ARE ONE DECISION.

     This read the key list, counted the live ones, compared them to the cap and
     wrote the list back - four steps with three gaps. Two creates arriving
     together both read the same list, both decide they are under the cap, and
     both write: the cap is exceeded, and worse, the second write is made from a
     list that does not contain the first key. That key is LOST from the record
     while its lookup row still exists, so it goes on authenticating and cannot
     be revoked through the product, because nothing lists it.

     The lock roster excused this handler on the grounds that two creates at
     once is one person double-clicking and "the cap below refuses the second
     anyway". A double-click is exactly how it happens, and the cap is read
     inside the same window it is supposed to close - so it refuses nothing.
     Same shape as the signup exemption, and wrong for the same reason.

     The lookup row is written after the lock, deliberately: it is a different
     key, and a failure between them leaves a key that is listed and does not
     work - visible and revocable - rather than one that works and is invisible. */
  let capped = false;
  await _withKind(env, 'apikeys', user.email, (rec) => {
    const live = (rec.items || []).filter(k => !k.revoked);
    if (live.length >= API_KEY_MAX_PER_USER) { capped = true; return; }
    rec.items = (rec.items || []).concat(item);
  }, { items: [] });
  if (capped) {
    return json({ error: 'You can have up to ' + API_KEY_MAX_PER_USER + ' active keys. Revoke one to create another.' }, 429);
  }
  // The lookup the request path uses: hash -> which account, which key.
  await env.AMV_KV.put(`apikey:${hash}`, JSON.stringify({ email: user.email, id: item.id }));
  audit(env, 'apikey_created', { email: user.email, id: item.id });
  await _userEvent(env, request, user.email, 'api_key_created');
  /* The only time this value exists anywhere outside the caller's memory. */
  return json({ ok: true, key, item: _apiKeyPublic(item),
                note: 'Copy this now. It is not stored and cannot be shown again.' });
}

/* POST /v1/keys/list */
async function apiKeyList(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  const rec = (await DB.get(env, 'apikeys', user.email)) || { items: [] };
  return json({ ok: true, keys: (rec.items || []).map(_apiKeyPublic), max: API_KEY_MAX_PER_USER });
}

/* POST /v1/keys/revoke { id } */
async function apiKeyRevoke(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  const { id } = await request.json().catch(() => ({}));
  /* AMV-210: the hot path stamps lastUsed on this same record once a minute
     per key, so a revoke could be written back over. The KEY still stopped
     working either way - the lookup row below is what the request path reads,
     and deleting it is what revocation really is - but the record would show a
     revoked key as active, which is a screen telling somebody the opposite of
     the truth about a credential. */
  let hash = '';
  const found = await _withKind(env, 'apikeys', user.email, (rec) => {
    const item = (rec.items || []).find(k => k.id === id);
    if (!item) return false;
    hash = item.hash || '';
    if (!item.revoked) item.revoked = Date.now();
    return true;
  }, { items: [] });
  if (!found) return json({ error: 'not found' }, 404);
  /* Delete the lookup too - this is what the request path reads, and deleting
     it is what revocation really is. Marking the record without removing this
     would leave the key working. */
  if (hash) { try { await env.AMV_KV.delete(`apikey:${hash}`); } catch (e) {} }
  audit(env, 'apikey_revoked', { email: user.email, id });
  await _userEvent(env, request, user.email, 'api_key_revoked');
  return json({ ok: true, id, revoked: true });
}

/* Resolve `Authorization: Bearer amv_sk_...` to the account it belongs to, in
   the same shape requireUser returns - so every quota, cost cap and plan check
   downstream applies to an API call exactly as it does to a browser one. */
async function _userFromApiKey(request, env) {
  const raw = (request.headers.get('Authorization') || '').replace(/^Bearer\s+/i, '')
           || request.headers.get('X-AMV-Key') || '';
  if (!raw.startsWith(API_KEY_PREFIX)) return null;
  let ref = null;
  try { ref = JSON.parse(await env.AMV_KV.get(`apikey:${await _apiKeyHash(raw)}`) || 'null'); } catch (e) {}
  if (!ref || !ref.email) return null;

  const rec = (await DB.get(env, 'apikeys', ref.email)) || { items: [] };
  const item = (rec.items || []).find(k => k.id === ref.id);
  if (!item || item.revoked) return null;

  /* The account still has to exist. Erasure now clears these, but a key that
     authenticates on the strength of a lookup row alone is one orphaned record
     away from being a credential belonging to nobody - and this is the check
     that makes that impossible rather than merely tidy. */
  const acct = await DB.get(env, 'acct', ref.email);
  if (!acct) return null;

  // Last use, so a customer can tell a live key from a forgotten one. Written
  // at most once a minute: this is on the hot path of every API request.
  const now = Date.now();
  if (!item.lastUsed || now - item.lastUsed > 60000) {
    /* Under the lock, and re-found inside it: this runs on every authenticated
       API request, so it is the write most likely to be racing a revoke. */
    try {
      await _withKind(env, 'apikeys', ref.email, (rec2) => {
        const cur = (rec2.items || []).find(k => k.id === ref.id);
        if (!cur) return null;
        cur.lastUsed = now;
        cur.calls = (cur.calls || 0) + 1;
      }, { items: [] });
    } catch (e) {}
    item.lastUsed = now;
  }

  /* The SAME principal a browser session gets. This used to return five fields
     of its own and nothing else, so an API key carried no billing subject, no
     block, and no family limit - see _principalOf. */
  return await _principalOf(env, ref.email, null, { via: 'apikey', keyId: ref.id });
}

/* =====================================================================
   AMV-095  IS IT ANY GOOD?

   Cost, latency, margin, abuse and growth are all instrumented. Answer
   QUALITY is not measured anywhere at all - which means a routing change, a
   prompt edit or a model swap could make AMV materially worse and every
   dashboard would stay green. The one number that decides whether people stay
   is the one nobody can see.

   So a rating on an answer is counted, per engine, per month. What is NOT
   stored is the important part: no message text, no prompt, no answer, not a
   snippet. Storing conversations to measure quality would trade the thing
   being measured for the measurement. Engine, feature, a coarse reason and a
   timestamp is enough to answer "did that change make it worse", and is not
   worth stealing.
   ===================================================================== */

const FEEDBACK_REASONS = new Set(['wrong', 'incomplete', 'ignored_instructions', 'too_slow', 'other']);

/* ══════════════════════════════════════════════════════════════════════
   PUBLIC CONFIG - the handful of values a VISITOR's browser needs.

   The Worker holds GOOGLE_CLIENT_ID, and the browser did not - so "Continue
   with Google", the first button on the sign-up sheet, was dead for everybody
   except the owner, who had pasted the id into their own Settings. Same shape
   as the backend URL: configuration that lived in one person's localStorage
   while every visitor needed it.

   ONLY values that are public by design go in here. A Google client id, a
   Turnstile SITE key and a support address all appear in plain sight in
   ordinary use - in the OAuth URL, in the captcha widget's own markup, on the
   contact page. And only values a browser actually USES: the PayPal client id
   was served here until the browser-side PayPal SDK was removed, and an
   unused public value is still surface for nothing. Nothing
   that could sign, spend or authenticate is served: not STRIPE_SECRET_KEY, not
   TURNSTILE_SECRET, not GOOGLE_CLIENT_SECRET, not JWT_SECRET. A missing value
   is simply absent, so this also cannot be used to enumerate which secrets a
   deployment has - that is the admin readiness endpoint's job, behind a token.
   ══════════════════════════════════════════════════════════════════════ */
const PUBLIC_CONFIG_KEYS = [
  ['googleClientId',  'GOOGLE_CLIENT_ID'],
  ['supportEmail',    'SUPPORT_EMAIL'],
  /* A Turnstile SITE key is public by design - it sits in the HTML of every
     site that uses one. The SECRET is the other half and never leaves here.
     Without this the widget cannot render, no token is produced, and
     _verifyCaptcha refuses every sign-up and sign-in the moment
     TURNSTILE_SECRET is set. */
  ['turnstileSiteKey','TURNSTILE_SITE_KEY'],
];
/* ══════════════════════════════════════════════════════════════════════
   THE TOP OF THE FUNNEL - people who arrive and never sign up.

   _funnelMark already answers everything from signup onwards: signed up,
   got value, came back, paid. It cannot see the largest group there is, the
   people who looked at the page and left, so the one number that decides
   whether any of the marketing works - visitors who become accounts - was not
   computable from anything AMV held.

   The obvious fix was to serve an analytics endpoint to the browser and let
   `track()` beacon to it. That means a third party receiving a record of every
   visitor, a CSP widened to let it, and somebody else's cookie policy becoming
   AMV's problem. For ONE number.

   So this is first-party and deliberately impoverished. It increments a daily
   COUNTER. There is no identifier of any kind in it - no id, no address, no
   user agent, no referrer, nothing that could later be joined to a person -
   which is why it needs no consent banner to be honest and no processor
   agreement to be lawful. It cannot answer "who", only "how many", and how
   many is the entire question.

   Rate limited per IP because it is unauthenticated, and one visit per session
   is enforced by the browser rather than trusted from it - a caller who lies
   inflates a number that only they read. */
async function recordVisit(request, env) {
  const ip = request.headers.get('CF-Connecting-IP') || '';
  if (ip) {
    /* Generous: a person opening AMV in several tabs is normal. Bounded:
       an unauthenticated counter is otherwise free to inflate. */
    const r = await limitAction(env, `visit:${ip}`, 10, 200);
    if (!r.ok) return json({ ok: true, counted: false });
  }
  try { await _recordGrowth(env, 'visit'); } catch (e) {}
  return json({ ok: true, counted: true });
}

async function publicConfig(request, env) {
  /* Unauthenticated by necessity - it is read before anybody has an account -
     so it is bounded per IP like the other open endpoints. */
  const ip = request.headers.get('CF-Connecting-IP') || 'anon';
  const blocked = await guardAction(env, `pubcfg:${ip}`, 30, 2000, 'config reads');
  if (blocked) return blocked;

  const out = { ok: true };
  for (const [field, secret] of PUBLIC_CONFIG_KEYS) {
    const v = String((env && env[secret]) || '').trim();
    if (v) out[field] = v;
  }
  /* Built directly rather than through json(), which takes only a body and a
     status - a third argument would have been silently ignored and the cache
     header would never have been sent. Five minutes is long enough to spare
     the Worker a request per page load and short enough that rotating a client
     id takes effect while you are still watching. */
  return new Response(JSON.stringify(out), { status: 200, headers: {
    'Content-Type': 'application/json', 'Cache-Control': 'public, max-age=300',
    ...CORS, ...SECURITY_HEADERS } });
}

async function feedbackRecord(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  // Cheap to send and easy to spam, so it is bounded like anything else.
  const blocked = await guardAction(env, `fb:${user.email}`, 30, 300, 'ratings');
  if (blocked) return blocked;

  const body = await request.json().catch(() => ({}));
  const rating = body.rating === 'up' ? 'up' : (body.rating === 'down' ? 'down' : null);
  if (!rating) return json({ error: 'rating must be up or down' }, 400);
  const engine = ENGINES[body.engine] ? body.engine : (RAW_TO_KEY[body.engine] || 'unknown');
  const feature = String(body.feature || 'chat').replace(/[^a-z_]/gi, '').slice(0, 24) || 'chat';
  const reason = FEEDBACK_REASONS.has(body.reason) ? body.reason : '';

  const mk = monthKey();
  await counter(env, `qual:${engine}:${rating}:${mk}`, { op: 'incr', amount: 1, ttlMs: 86400000 * 400 });
  await counter(env, `qualfeat:${feature}:${rating}:${mk}`, { op: 'incr', amount: 1, ttlMs: 86400000 * 400 });
  if (rating === 'down' && reason) {
    await counter(env, `qualwhy:${reason}:${mk}`, { op: 'incr', amount: 1, ttlMs: 86400000 * 400 });
  }
  /* Deliberately not audited with any content. The event itself is the record. */
  return json({ ok: true });
}

/* ══════════════════════════════════════════════════════════════════════
   SUPPORT - a bug report that reaches a person.

   There was nowhere for one to go. The in-app report wrote to localStorage and
   only transmitted if `amv_feedback_endpoint` was set, a key no screen in the
   product could write, and /v1/feedback is the thumbs up/down counter above,
   which deliberately stores no content and would have refused a sentence. So
   somebody reporting a broken payment was thanked and their report sat in
   their own browser for ever.

   The screen at least stopped claiming otherwise. It still left a product that
   takes money with no way to be told it is broken, which is a refund and a
   chargeback for every problem that could have been a reply.

   Stored under the reporter's own email, which is not incidental: it is what
   puts support tickets on PER_USER_KINDS, so they are erased with the account
   and included in a data export like everything else the server holds. A
   support inbox is one of the easiest places to accumulate personal data that
   outlives the person who wrote it. */
const SUPPORT_MAX_LEN = 4000;
const SUPPORT_KEEP = 20;              // per account, newest first
const SUPPORT_KINDS = new Set(['bug', 'idea', 'billing', 'account', 'other']);

async function supportSubmit(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'sign in first, or email support directly' }, 401);
  /* Reaching a human is worth spending real money on, so it is worth abusing.
     Generous for a person with a bad day, useless as an amplifier. */
  const blocked = await guardAction(env, `support:${user.email}`, 5, 20, 'support messages');
  if (blocked) return blocked;

  const body = await request.json().catch(() => ({}));
  const text = String(body.text || '').trim().slice(0, SUPPORT_MAX_LEN);
  if (text.length < 5) return json({ error: 'please describe what happened' }, 400);
  const kind = SUPPORT_KINDS.has(body.kind) ? body.kind : 'other';
  /* Context the reporter did not have to think to include, and nothing more.
     No conversation content: somebody reporting that chat is broken has not
     agreed to send us what they were chatting about. */
  const ticket = {
    id: 'sup_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
    kind, text, at: Date.now(),
    plan: String(body.plan || '').slice(0, 16),
    tab: String(body.tab || '').replace(/[^a-z_-]/gi, '').slice(0, 24),
    app: String(body.app || '').slice(0, 24),
    status: 'open',
  };

  /* AMV-033: two tickets submitted from two tabs both read the list, both
     prepend, and the later write loses the earlier ticket - somebody who asked
     for help and was told it was sent. */
  await _withKind(env, 'support', user.email, (rec) => {
    rec.tickets = [ticket].concat(Array.isArray(rec.tickets) ? rec.tickets : []).slice(0, SUPPORT_KEEP);
    rec.updatedAt = Date.now();
  }, { tickets: [] });

  /* Told to the operator NOW. A ticket that only exists until somebody thinks
     to open an admin page is barely better than one in a browser. Not
     alertOnce: every report is a different person, and collapsing them is how
     the second one is never seen. */
  let notified = false;
  try {
    await notify(env, `📮 ${kind} report from ${user.email}` + (ticket.plan ? ` (${ticket.plan})` : '')
      + `:\n${text.slice(0, 500)}`);
    notified = !!env.ALERT_WEBHOOK;
  } catch (e) {}
  audit(env, 'support_submitted', { email: user.email, kind, id: ticket.id });

  /* What actually happened, so the screen cannot thank somebody for a delivery
     that did not occur. Stored is true either way; reaching a person is not. */
  return json({ ok: true, id: ticket.id, stored: true, notified,
                support: env.SUPPORT_EMAIL || '' });
}

/* The operator's inbox. Behind the admin token like every other operator
   surface - it contains other people's words about their own accounts. */
async function supportInbox(request, env) {
  /* AMV-052: through the SAME gate as every other admin route. This was a bare
     token comparison with no rate limit, so three of the sixteen admin routes
     were an unbounded channel for guessing the token while the other thirteen
     were not - and an attacker only has to find the unbounded one. */
  { const g = await _adminGate(request, env, 'read', 60, 2000); if (g) return g; }
  const { rows, truncated } = await scan(env, 'support', SUPPORT_SCAN_LIMIT, 'support inbox');
  const out = [];
  for (const row of rows) {
    for (const t of ((row.value || {}).tickets || [])) out.push(Object.assign({ email: row.id }, t));
  }
  out.sort((a, b) => (b.at || 0) - (a.at || 0));
  /* Two separate ways this list is not everything, and an unanswered customer
     is the cost of either: more accounts than the scan read, and more tickets
     than the page shows. Both are stated rather than implied by a short list. */
  const shown = out.slice(0, 200);
  return json({ ok: true, tickets: shown, accounts: rows.length,
                truncated: truncated || out.length > shown.length,
                totalTickets: out.length,
                note: truncated
                  ? 'More accounts have tickets than this scan read - there is unseen mail beyond this list.'
                  : (out.length > shown.length
                      ? 'Showing the ' + shown.length + ' newest of ' + out.length + ' tickets.' : null) });
}

/* Approval rate per engine, for the dashboard and the weekly digest. A rate
   with almost no votes behind it is noise, so the count travels with it and
   the rate is null until there is enough to mean anything. */
async function _qualityReport(env) {
  const mk = monthKey();
  const MIN_VOTES = 10;
  const out = { engines: [], features: [], reasons: [], month: mk };
  for (const key of Object.keys(ENGINES)) {
    const up = (await counter(env, `qual:${key}:up:${mk}`, { op: 'get' })).value || 0;
    const down = (await counter(env, `qual:${key}:down:${mk}`, { op: 'get' })).value || 0;
    const total = up + down;
    out.engines.push({ engine: key, up, down, votes: total,
      approvalPct: total >= MIN_VOTES ? +((up / total) * 100).toFixed(1) : null });
  }
  for (const feat of ['chat', 'research', 'code', 'agent', 'automation']) {
    const up = (await counter(env, `qualfeat:${feat}:up:${mk}`, { op: 'get' })).value || 0;
    const down = (await counter(env, `qualfeat:${feat}:down:${mk}`, { op: 'get' })).value || 0;
    const total = up + down;
    if (total) out.features.push({ feature: feat, up, down, votes: total,
      approvalPct: total >= MIN_VOTES ? +((up / total) * 100).toFixed(1) : null });
  }
  for (const why of FEEDBACK_REASONS) {
    const n = (await counter(env, `qualwhy:${why}:${mk}`, { op: 'get' })).value || 0;
    if (n) out.reasons.push({ reason: why, count: n });
  }
  out.reasons.sort((a, b) => b.count - a.count);
  const allUp = out.engines.reduce((n, e) => n + e.up, 0);
  const allDown = out.engines.reduce((n, e) => n + e.down, 0);
  out.votes = allUp + allDown;
  out.approvalPct = out.votes >= MIN_VOTES ? +((allUp / out.votes) * 100).toFixed(1) : null;
  out.minVotes = MIN_VOTES;
  return out;
}

/* =====================================================================
   AMV-084  GO-LIVE READINESS - what is actually switched on

   The Go-Live screen was a list of guesses made in the browser. Three of its
   rows were hardcoded to "not set up" whatever the truth was, and the row for
   the AI engine reported whether THIS BROWSER had a session - which says
   nothing at all about whether the Worker holds an API key. So the one screen
   whose entire job is to tell the owner whether the product is real could not
   see a single server secret, and confidently said so.

   This reports the truth from the only place that knows it. It returns
   whether each secret EXISTS - never a value, never a prefix, never a length,
   because a screen that leaks the shape of a key is worse than one that
   guesses. Each entry also carries what it turns on and the exact command to
   set it, so "not set up" is a next action rather than a verdict.
   ===================================================================== */

/* Present and non-empty. A secret set to the empty string is not configured,
   and treating it as configured is how a deploy silently half-works. */
function _has(env, name) { return !!String((env && env[name]) || '').trim(); }

function _readinessReport(env) {
  const put = n => 'wrangler secret put ' + n;
  /* `blocking` means the product does not do its core job without it.
     Everything else is a real feature that degrades honestly. */
  const items = [
    { id: 'ai', name: 'AI engine', blocking: true, on: !!_modelKey(env),
      turnsOn: 'Every answer, agent, build, document and scheduled task.',
      how: put('AMV_MODEL_KEY') },
    { id: 'auth', name: 'Accounts and sessions', blocking: true, on: _has(env, 'JWT_SECRET'),
      turnsOn: 'Sign-in, sync and every authenticated route. Without it no token can be issued or verified.',
      how: put('JWT_SECRET') },
    { id: 'admin', name: 'Operator access', blocking: false, on: _has(env, 'ADMIN_TOKEN'),
      turnsOn: 'The founder dashboard, platform stats, the kill switch and the weekly digest.',
      how: put('ADMIN_TOKEN') },
    { id: 'ownerEmail', name: 'Owner address', blocking: false, on: _has(env, 'OWNER_EMAIL'),
      turnsOn: 'The weekly digest, and operator privileges for that account.',
      how: put('OWNER_EMAIL') },
    { id: 'email', name: 'Email delivery', blocking: false, on: _has(env, 'EMAIL_API_KEY'),
      turnsOn: 'Password resets, the weekly digest, and automation results reaching an inbox instead of only the app.',
      how: put('EMAIL_API_KEY') },
    /* AMV-193: CONFIGURED IS NOT THE SAME AS DELIVERABLE.
       The line above goes green the moment a Resend key exists. But the default
       sender is onboarding@resend.dev, which Resend only delivers to the
       address that owns the Resend account - so with a key and no verified
       domain, password resets reach the operator and NOBODY ELSE. Every other
       person who forgets their password is locked out for good, and the screen
       that exists to say what works reported email as on.
       Preflight warns about this; a running deployment could not see it. */
    { id: 'emailSender', name: 'Email actually reaches people', blocking: false,
      on: _has(env, 'EMAIL_API_KEY') && _has(env, 'RESET_EMAIL_FROM'),
      turnsOn: 'Mail to anyone other than you. Without a sender on a domain you have verified, the default '
             + 'address only delivers to the owner of the email account - so password resets reach you and nobody else.',
      how: put('RESET_EMAIL_FROM') },
    { id: 'appUrl', name: 'App address', blocking: false, on: _has(env, 'APP_URL'),
      turnsOn: 'Correct links in every email, invite links, and shared conversation URLs.',
      how: put('APP_URL') },
    { id: 'payments', name: 'Payments', blocking: false, on: _has(env, 'STRIPE_SECRET_KEY'),
      turnsOn: 'Checkout, subscriptions and the billing portal. Nobody can pay you without it.',
      how: put('STRIPE_SECRET_KEY') },
    /* BLOCKING once payments are switched on, and only then. A deployment not
       selling anything yet does not need a webhook; one that IS selling and
       has no webhook is the worse half of a broken pair. Nothing else grants a
       plan on payment, and nothing else revokes one on cancellation, refund or
       chargeback - so money arrives and nobody gets what they bought, while
       anybody who ever did get a plan keeps it for ever. Taking payments with
       no way to end what they bought is the one configuration that can put a
       deployment in front of a customer's bank. */
    { id: 'paymentsHook', name: 'Payment webhooks', blocking: _has(env, 'STRIPE_SECRET_KEY'),
      on: _has(env, 'STRIPE_WEBHOOK_SECRET'),
      turnsOn: _has(env, 'STRIPE_SECRET_KEY') && !_has(env, 'STRIPE_WEBHOOK_SECRET')
        ? 'REQUIRED NOW - you are taking payments without it. Nothing grants a plan when somebody pays, and nothing revokes one when they cancel, are refunded, or charge back. The daily renewal sweep is a backstop, not a substitute.'
        : 'Plans granted on payment, and revoked on cancellation, refund or chargeback. Without it a payment never reaches the account that made it.',
      how: put('STRIPE_WEBHOOK_SECRET') },
    { id: 'modelFallback', name: 'Model failover', blocking: false, on: _has(env, 'MODEL_API_FALLBACK_URL'),
      turnsOn: 'A second endpoint AMV falls back to when the primary cannot answer. Non-streaming requests are retried there; a stream that already sent words is never retried, because repeating them is worse than an honest error.',
      how: put('MODEL_API_FALLBACK_URL') },
    /* THE SECRET THAT DECIDES WHETHER TOKENS ARE STORED IN THE CLEAR.

       Not blocking, because AMV is fully usable without connected accounts and
       refusing to boot over an optional feature would be the wrong trade. It is
       listed loudly instead: without it, connecting is refused outright rather
       than falling back to plaintext storage, which is the only degradation
       that would actually be dishonest here. */
    { id: 'connectKey', name: 'Connected accounts (encryption)', blocking: false,
      on: _has(env, 'CONNECT_KEY'),
      turnsOn: 'Holding account tokens so Crew jobs run with the tab closed. The key seals every stored token with AES-GCM, so a stolen copy of the database is ciphertext rather than mailboxes. Without it AMV refuses to connect an account at all - it will not store a token unencrypted.',
      how: put('CONNECT_KEY') },
    /* A ROTATION IN PROGRESS IS A STATE, AND STATES BELONG ON THIS SCREEN.

       CONNECT_KEY_PREV being set is not a missing capability - it is a rotation
       that has started and has not finished. Left off this list, the only way
       to know AMV is still able to read records sealed under an old secret
       would be to remember setting it, and the whole point of the screen is
       that nothing about the deployment is only in somebody's head. It reports
       "on" when it is ABSENT, because absent is the settled state. */
    { id: 'connectKeyPrev', name: 'Connected accounts (key rotation)', blocking: false,
      on: !_has(env, 'CONNECT_KEY_PREV'),
      turnsOn: _has(env, 'CONNECT_KEY_PREV')
        ? 'A ROTATION IS IN PROGRESS. CONNECT_KEY_PREV is set, so records sealed under the previous key can still be read; each one re-seals under the current key the next time it is used. Remove CONNECT_KEY_PREV once every connection has been used, and check the audit log for conn_resealed before you do.'
        : 'Nothing to do - no rotation is in progress. To rotate: put the new value in CONNECT_KEY and the old one in CONNECT_KEY_PREV, leave it a while, then remove CONNECT_KEY_PREV. Rotating without it makes every stored connection unreadable and every customer reconnect every account.',
      how: 'Only during a rotation: ' + put('CONNECT_KEY_PREV') },
    /* Each provider is its own line, because "connected accounts is on" is not
       a thing - Google can be live while Microsoft is dark, and the operator
       needs to see which. */
    { id: 'connectGoogle', name: 'Connect Google', blocking: false,
      on: _has(env, 'GOOGLE_CLIENT_ID') && _has(env, 'GOOGLE_CLIENT_SECRET'),
      turnsOn: 'Gmail, Calendar and Drive as connected accounts. Needs an app registered with Google and both halves pasted here; until then Google shows as not set up rather than opening a flow that fails.',
      how: put('GOOGLE_CLIENT_ID') + ' and ' + put('GOOGLE_CLIENT_SECRET') },
    { id: 'connectMicrosoft', name: 'Connect Microsoft', blocking: false,
      on: _has(env, 'MS_CLIENT_ID') && _has(env, 'MS_CLIENT_SECRET'),
      turnsOn: 'Outlook mail and calendar as connected accounts.',
      how: put('MS_CLIENT_ID') + ' and ' + put('MS_CLIENT_SECRET') },
    { id: 'teamSeats', name: 'Teams (per-seat billing)', blocking: false, on: _has(env, 'STRIPE_PRICE_TEAM_SEAT'),
      turnsOn: 'Selling Teams by the seat at $' + TEAM_SEAT_PRICE_USD + '/seat/month. Without it Teams is still usable on Elite and Ultra, and the per-seat plan says it is not switched on rather than failing at checkout.',
      how: put('STRIPE_PRICE_TEAM_SEAT') },
    /* BOTH halves, deliberately. This line used to read TURNSTILE_SECRET alone
       and report "on", which is the one answer that is never true: the secret
       verifies a token, the SITE KEY is what renders the widget that produces
       one. With only the secret set, no browser can produce a token, so the
       captcha is skipped rather than refusing every sign-up - and this line is
       how an operator finds out it is skipped. */
    { id: 'captcha', name: 'Signup verification (Turnstile)', blocking: false,
      on: _has(env, 'TURNSTILE_SECRET') && _has(env, 'TURNSTILE_SITE_KEY'),
      turnsOn: _has(env, 'TURNSTILE_SECRET') && !_has(env, 'TURNSTILE_SITE_KEY')
        ? 'HALF SET UP - the secret is set but the site key is not, so no browser can produce a token. The captcha is being SKIPPED rather than blocking every sign-up; only the honeypot and rate limits apply. Set TURNSTILE_SITE_KEY to switch it on.'
        : 'Bot protection on signup and sign-in. Needs BOTH halves: the secret verifies here, the site key renders the widget in the browser. Until they are set, only the honeypot and rate limits apply.',
      how: put('TURNSTILE_SITE_KEY') + ' and ' + put('TURNSTILE_SECRET') },
    { id: 'googleAuth', name: 'Google sign-in', blocking: false, on: _has(env, 'GOOGLE_CLIENT_ID'),
      turnsOn: 'Sign in with Google. It fails closed until set, rather than trusting an unverified token.',
      how: put('GOOGLE_CLIENT_ID') },
    { id: 'alerts', name: 'Operator alerts', blocking: false, on: _has(env, 'ALERT_WEBHOOK'),
      turnsOn: 'Being paged when spend caps are hit, checkout breaks, or the model rejects a request.',
      how: put('ALERT_WEBHOOK') },
  ];

  /* Storage is bound, not pasted, so it is reported separately - and what each
     binding buys is a correctness property, not a feature. */
  const storage = [
    { id: 'kv', name: 'KV namespace', on: !!(env && env.AMV_KV),
      turnsOn: 'All persistence. Nothing works without it.', how: 'Bind AMV_KV in wrangler.toml', blocking: true },
    { id: 'd1', name: 'D1 database', on: !!(env && env.DB && typeof env.DB.prepare === 'function'),
      turnsOn: 'Guaranteed sync writes: without it two devices saving at the same instant cannot be arbitrated, only merged.',
      how: 'Bind DB in wrangler.toml', blocking: false },
    /* BLOCKING once money is being taken, and only then - the same shape as
       the payment webhook above and for the same reason.

       Without the Durable Object every `reserve` degrades to a read followed by
       a write. That is the exact race the reservation exists to close: twenty
       requests arriving together all read the same total, all decide they fit,
       and all proceed, so the overshoot is bounded only by how many arrive at
       once. The daily spend ceiling, every plan's token allowance and every
       exactly-once claim are all built on it.

       On a machine with no customers that is a documented degradation and
       refusing to run there would mean AMV does not work without a paid
       Cloudflare plan. On a deployment taking payments it is the difference
       between a bill with a ceiling and a bill without one, and the operator
       has to be told that before the first customer rather than by the
       invoice. */
    { id: 'counter', name: 'Atomic counter', on: !!(env && env.AMV_COUNTER),
      blocking: _has(env, 'STRIPE_SECRET_KEY'),
      turnsOn: (_has(env, 'STRIPE_SECRET_KEY') && !(env && env.AMV_COUNTER))
        ? 'REQUIRED NOW - you are taking payments without it. Every spend ceiling and token allowance falls back to read-then-write, so requests arriving together all pass the same check and the day\u2019s ceiling can be overshot by however many arrive at once. It is the one control standing between AMV and an unbounded bill.'
        : 'Race-free usage limits, spend caps and one-time claims. Without it they are a read followed by a write, which is the race they exist to close.',
      how: 'Bind AMV_COUNTER (the AMVCounter Durable Object) in wrangler.toml' },
  ];

  const all = items.concat(storage);
  const missingBlocking = all.filter(i => i.blocking && !i.on);
  const missingOptional = all.filter(i => !i.blocking && !i.on);
  return {
    items, storage,
    summary: {
      on: all.filter(i => i.on).length,
      total: all.length,
      blockingMissing: missingBlocking.length,
      // The single sentence that answers "can I launch".
      verdict: missingBlocking.length
        ? 'Not ready: ' + missingBlocking.map(i => i.name).join(', ') + ' still missing.'
        : (missingOptional.length
            ? 'Core product is live. ' + missingOptional.length + ' optional capabilit' + (missingOptional.length === 1 ? 'y is' : 'ies are') + ' still off.'
            : 'Everything is configured.'),
    },
  };
}

/* GET /admin/readiness - admin-gated, and it never returns a secret value. */
async function adminReadiness(request, env) {
  { const g = await _adminGate(request, env, 'read', 60, 2000); if (g) return g; }
  return json(Object.assign({ ok: true, checkedAt: Date.now() }, _readinessReport(env)));
}

/* =====================================================================
   AMV-081  THE WEEKLY OWNER DIGEST

   Every number below already existed. Signups, activation, referral
   conversions, per-plan margin, cost per paying user, money at risk - all of
   it computed, all of it correct, and all of it sitting on a dashboard that
   only reports what is true at the instant somebody remembers to open it.

   A dashboard tells you the state. A digest tells you the CHANGE, on a
   schedule, without being asked - which is the difference between having
   metrics and being run by them. So this stores a snapshot each week and
   reports the delta against the last one, in the order the questions actually
   get asked: is it growing, does it make money, and what is on fire.

   Rules it keeps:
     - It never invents a comparison. The first week says "no previous week",
       because that is what is true.
     - It sends at most once per week, claimed atomically, so a cron that fires
       twice does not mail twice.
     - With nothing configured it does nothing and says why in the log, rather
       than failing the cron tick that also runs everyone's automations.
   ===================================================================== */

/* Monday-anchored week key, so a digest belongs to a week rather than to
   whenever the cron happened to fire. */
function _weekKey(ts) {
  const d = new Date(ts || Date.now());
  const day = (d.getUTCDay() + 6) % 7;                 // Monday = 0
  const monday = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate() - day);
  return new Date(monday).toISOString().slice(0, 10);
}

/* The owner's numbers, read through the same admin endpoint the dashboard uses
   so the digest and the screen can never drift apart. Returns null when there
   is no admin token configured - with no admin surface there is nothing to
   report, and inventing a second path into these numbers would be a second
   thing to secure. */
async function _ownerMetrics(env) {
  if (!env.ADMIN_TOKEN) return null;
  const r = await adminStats(new Request('https://internal/v1/admin/stats', {
    headers: { Authorization: 'Bearer ' + env.ADMIN_TOKEN },
  }), env);
  if (!r || r.status !== 200) return null;
  const m = await r.json().catch(() => null);
  if (!m) return null;

  /* AMV-194: WHAT IS WAITING ON A PERSON.

     The support inbox and the abuse review are real routes behind the admin
     token, and no screen calls either - the moderation card in the dashboard
     still says "pending". That is a defensible way to build them and a terrible
     way to run them: a customer files a complaint, it is stored correctly, and
     the only way anybody reads it is remembering to curl an endpoint. An
     unanswered support ticket is churn that never explains itself.

     So the digest - the one thing that already arrives without being asked for
     - carries the count. Cheap to gather, and it turns "I must remember to
     check" into "something told me". */
  try {
    const { rows: sup } = await scan(env, 'support', SUPPORT_SCAN_LIMIT, 'digest: support waiting');
    let open = 0, oldest = 0;
    for (const row of sup) {
      for (const t of ((row.value || {}).tickets || [])) {
        if (t && t.status === 'closed') continue;
        open++;
        if (t && t.at && (!oldest || t.at < oldest)) oldest = t.at;
      }
    }
    const { rows: ab } = await scan(env, 'abuse', 5000, 'digest: abuse flags');
    const flagged = ab.filter(x => (x.value || {}).blocked).length;
    m.waiting = { support: open, supportOldestDays: oldest ? Math.floor((Date.now() - oldest) / 86400000) : 0,
                  flagged };
  } catch (e) { /* the digest is worth sending without this */ }
  return m;
}

/* The handful of figures worth carrying week to week. Deliberately small: a
   snapshot that stores everything becomes a second source of truth to keep
   correct, and nobody compares forty numbers. */
function _digestSnapshot(m) {
  const g = m.growth || {}, rev = m.revenue || {}, mar = m.margin || {}, u = m.users || {};
  return {
    at: Date.now(),
    signups7: +g.signups7 || 0,
    referrals7: +g.referrals7 || 0,
    activeToday: +u.activeToday || 0,
    paying: +u.paying || 0,
    totalUsers: +u.total || 0,
    mrr: +rev.estMRR || 0,
    mrrAtRisk: +rev.mrrAtRisk || 0,
    grossMargin: +mar.grossMargin || 0,
    grossMarginPct: mar.grossMarginPct === null ? null : +mar.grossMarginPct,
    costPerPayingUser: +mar.costPerPayingUser || 0,
    freeUserCost: +mar.freeUserCost || 0,
    monthlyCost: +mar.estMonthlyCost || 0,
    unprofitable: (mar.unprofitableAccounts || []).length,
    approvalPct: (m.quality && m.quality.approvalPct != null) ? m.quality.approvalPct : null,
    qualityVotes: (m.quality && m.quality.votes) || 0,
    avgFirstTokenMs: (m.speed && m.speed.avgFirstTokenMs != null) ? m.speed.avgFirstTokenMs : null,
    activatedPct: (m.funnel && m.funnel.activatedPct != null) ? m.funnel.activatedPct : null,
    returnedPct: (m.funnel && m.funnel.returnedPct != null) ? m.funnel.returnedPct : null,
    paidPct: (m.funnel && m.funnel.paidPct != null) ? m.funnel.paidPct : null,
    avgDaysToPay: (m.funnel && m.funnel.avgDaysToPay != null) ? m.funnel.avgDaysToPay : null,
    teamSeatsSold: (m.revenue && m.revenue.teamSeatsSold) || 0,
  };
}

/* "12 (+3)" - and nothing at all when there is no previous week, because an
   invented baseline is worse than no baseline. */
function _delta(now, before, opts) {
  const o = opts || {};
  const fmt = v => (o.money ? '$' + (+v).toFixed(o.dp == null ? 2 : o.dp)
                            : (o.pct ? (+v).toFixed(1) + '%' : String(Math.round(v))));
  if (before == null || !Number.isFinite(before)) return fmt(now);
  const d = now - before;
  if (Math.abs(d) < 1e-9) return fmt(now) + ' (no change)';
  return fmt(now) + ' (' + (d > 0 ? '+' : '-') + fmt(Math.abs(d)) + ')';
}

/* Build the digest. Returns { subject, html, text, snapshot, previous } so it
   can be previewed without being sent - the same content either way, which is
   the only way a preview is worth anything. */
function _buildDigest(m, prev) {
  const snap = _digestSnapshot(m);
  const g = m.growth || {}, mar = m.margin || {};
  const p = prev || null;
  const pv = k => (p ? p[k] : null);

  const rows = [
    ['Signups this week',      _delta(snap.signups7, pv('signups7'))],
    ['Of those, from invites', (snap.referrals7 || 0) + (g.referralSharePct != null ? ' (' + g.referralSharePct + '% of signups)' : '')],
    ['Active today',           _delta(snap.activeToday, pv('activeToday'))],
    /* The funnel, in the order somebody moves through it. These four lines are
       the only ones on this page that say whether the product WORK is landing -
       everything else says how the business is doing today (AMV-101). */
    ['Got a real answer',      snap.activatedPct == null ? 'not enough signups yet'
                                 : _delta(snap.activatedPct, pv('activatedPct'), { pct: true }) + ' of signups'],
    ['Came back another day',  snap.returnedPct == null ? 'not enough signups yet'
                                 : _delta(snap.returnedPct, pv('returnedPct'), { pct: true }) + ' of signups'],
    ['Went on to pay',         snap.paidPct == null ? 'not enough signups yet'
                                 : _delta(snap.paidPct, pv('paidPct'), { pct: true }) + ' of signups'],
    ['Time from signup to pay', snap.avgDaysToPay == null ? 'nobody has paid yet'
                                 : _delta(snap.avgDaysToPay, pv('avgDaysToPay')) + ' days on average'],
    ['Paying accounts',        _delta(snap.paying, pv('paying'))],
    ['Team seats sold',        _delta(snap.teamSeatsSold, pv('teamSeatsSold'))],
    ['MRR',                    _delta(snap.mrr, pv('mrr'), { money: true })],
    ['MRR at risk',            _delta(snap.mrrAtRisk, pv('mrrAtRisk'), { money: true })],
    ['Gross margin',           _delta(snap.grossMargin, pv('grossMargin'), { money: true })
                               + (snap.grossMarginPct != null ? ' (' + snap.grossMarginPct + '%)' : '')],
    ['Cost per paying user',   _delta(snap.costPerPayingUser, pv('costPerPayingUser'), { money: true, dp: 3 })],
    ['Cost of the free tier',  _delta(snap.freeUserCost, pv('freeUserCost'), { money: true })],
    ['Wait for the first word', snap.avgFirstTokenMs == null
                                 ? 'not measured yet'
                                 : _delta(snap.avgFirstTokenMs, pv('avgFirstTokenMs')) + ' ms'],
    ['Answers rated good',     snap.approvalPct == null
                                 ? 'not enough ratings yet'
                                 : _delta(snap.approvalPct, pv('approvalPct'), { pct: true })
                                   + ' (' + snap.qualityVotes + ' rating' + (snap.qualityVotes === 1 ? '' : 's') + ')'],
  ];

  /* What to actually DO. Only stated when the numbers say it - a digest that
     ends with advice every week is a digest nobody finishes reading. */
  const flags = [];
  /* Somebody is waiting on a person, and there is no screen that shows it. */
  const waiting = (m && m.waiting) || {};
  if (waiting.support > 0) {
    flags.push(waiting.support + ' support message' + (waiting.support > 1 ? 's are' : ' is') + ' waiting for a reply'
      + (waiting.supportOldestDays > 0 ? ', the oldest for ' + waiting.supportOldestDays + ' day' + (waiting.supportOldestDays > 1 ? 's' : '') : '')
      + '. Nobody is emailed when one arrives, so this line is the only thing that will tell you.');
  }
  if (waiting.flagged > 0) {
    flags.push(waiting.flagged + ' account' + (waiting.flagged > 1 ? 's are' : ' is') + ' blocked for chargeback or refund abuse. '
      + 'Worth a look in case any of them is a real customer caught by a pattern.');
  }
  if (snap.mrrAtRisk > 0)
    flags.push('$' + snap.mrrAtRisk.toFixed(2) + ' of MRR is on cards that failed. Those accounts drop to Free when their grace period ends.');
  if (snap.unprofitable > 0)
    flags.push(snap.unprofitable + ' account' + (snap.unprofitable > 1 ? 's cost' : ' costs') + ' more than it pays. They are named on the dashboard.');
  if (snap.grossMarginPct != null && snap.grossMarginPct < 50)
    flags.push('Gross margin is ' + snap.grossMarginPct + '%. Below 50% the plan pricing or the model routing needs a look.');
  if (p && snap.signups7 < pv('signups7'))
    flags.push('Signups fell from ' + pv('signups7') + ' to ' + snap.signups7 + ' week on week.');
  if (snap.paying === 0 && snap.totalUsers > 0)
    flags.push('No paying accounts yet against ' + snap.totalUsers + ' signups. Every cost below is being carried by nothing.');
  if (m.spend && m.spend.killed)
    flags.push('The global kill switch is ON. Nobody can use AMV right now.');
  /* A quality drop is the one thing that will not show up anywhere else until
     it shows up as churn, by which point it is months old. */
  if (snap.avgFirstTokenMs != null && snap.avgFirstTokenMs > 3000)
    flags.push('The average wait for the first word is ' + snap.avgFirstTokenMs + 'ms. Past about three seconds people assume it is broken.');
  if (p && pv('avgFirstTokenMs') != null && snap.avgFirstTokenMs != null
      && snap.avgFirstTokenMs > pv('avgFirstTokenMs') * 1.5)
    flags.push('AMV got noticeably slower to start: ' + pv('avgFirstTokenMs') + 'ms to ' + snap.avgFirstTokenMs + 'ms.');
  if (snap.approvalPct != null && snap.approvalPct < 70)
    flags.push('Only ' + snap.approvalPct + '% of rated answers were rated good. Something in routing or prompting is worth looking at.');
  /* Each of these points at a different problem, which is the whole reason for
     measuring the steps separately rather than only counting conversions. */
  if (snap.activatedPct != null && snap.activatedPct < 50)
    flags.push('Only ' + snap.activatedPct + '% of signups ever got a real answer out of AMV. That is a first-screen problem, not a pricing one.');
  else if (snap.returnedPct != null && snap.returnedPct < 25)
    flags.push('Only ' + snap.returnedPct + '% of signups came back on a second day. People are getting an answer and not finding a reason to return.');
  else if (snap.paidPct != null && snap.paidPct < 2 && snap.activatedPct != null && snap.activatedPct > 50)
    flags.push('People are using AMV (' + snap.activatedPct + '% activated) but only ' + snap.paidPct + '% pay. The limits or the upgrade moment are worth a look, not the onboarding.');
  if (p && pv('approvalPct') != null && snap.approvalPct != null && snap.approvalPct < pv('approvalPct') - 5)
    flags.push('Answer quality fell from ' + pv('approvalPct') + '% to ' + snap.approvalPct + '% week on week.');
  const worstReason = (m.quality && (m.quality.reasons || [])[0]);
  if (worstReason && worstReason.count >= 5)
    flags.push('The most common complaint was "' + worstReason.reason.replace(/_/g, ' ') + '" (' + worstReason.count + ' times).');

  const esc = t => String(t).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
  const appUrl = String(_digestAppUrl(m) || '').replace(/\/$/, '');
  const week = _weekKey();
  const subject = 'AMV weekly: ' + snap.signups7 + ' signups, $' + snap.mrr.toFixed(0) + ' MRR';

  const rowsHtml = rows.map(([k, v]) =>
    '<tr><td style="padding:7px 0;font-size:13px;color:#666">' + esc(k) + '</td>' +
    '<td style="padding:7px 0;font-size:13px;color:#111;text-align:right;font-weight:600">' + esc(v) + '</td></tr>').join('');
  const flagsHtml = flags.length
    ? '<div style="margin-top:22px;padding:14px;border-radius:10px;background:#fff8e6;border:1px solid #f0dca8">' +
      '<div style="font-size:12px;font-weight:700;color:#8a6d1f;text-transform:uppercase;letter-spacing:.04em;margin-bottom:8px">Needs a decision</div>' +
      flags.map(f => '<div style="font-size:13px;line-height:1.6;color:#5c4a14;margin-bottom:6px">' + esc(f) + '</div>').join('') +
      '</div>'
    : '<p style="margin:22px 0 0;font-size:13px;color:#777">Nothing needs a decision this week.</p>';

  const html = _emailShell(
    'Week of ' + week,
    (p ? '<p style="margin:0 0 16px;font-size:13px;color:#777">Compared with the week before.</p>'
       : '<p style="margin:0 0 16px;font-size:13px;color:#777">First digest, so there is nothing to compare against yet.</p>') +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0">' + rowsHtml + '</table>' + flagsHtml,
    appUrl ? { label: 'Open the dashboard', url: appUrl } : null,
    '<hr style="border:none;border-top:1px solid #eee;margin:18px 0"><p style="margin:0;font-size:11px;color:#999">Sent once a week to the AMV owner. These are the same figures as the founder dashboard.</p>',
    'AMV weekly digest.'
  );

  const text = 'AMV weekly - week of ' + week + '\n\n'
    + rows.map(([k, v]) => k + ': ' + v).join('\n')
    + (flags.length ? '\n\nNeeds a decision:\n' + flags.map(f => '- ' + f).join('\n') : '\n\nNothing needs a decision this week.')
    + (appUrl ? '\n\n' + appUrl : '');

  return { subject, html, text, snapshot: snap, previous: p, flags, week };
}
/* The dashboard payload does not carry the app URL, and threading env through
   the builder purely for one link would make it harder to test. This keeps the
   builder pure and lets the caller attach it to the metrics it passes in. */
function _digestAppUrl(m) { return (m && m._appUrl) || ''; }

/* Run it. Claimed once per week so a doubled cron cannot mail twice. */
async function runWeeklyDigest(env) {
  const week = _weekKey();
  const to = String(env.OWNER_EMAIL || '').toLowerCase().trim();
  if (!to || !env.EMAIL_API_KEY || !env.ADMIN_TOKEN) {
    return { sent: false, reason: !to ? 'no OWNER_EMAIL' : (!env.EMAIL_API_KEY ? 'no email provider' : 'no ADMIN_TOKEN') };
  }
  // Atomic, so two overlapping cron invocations cannot both send.
  if (!(await _claimOnce(env, 'digest', week, 40 * 86400))) return { sent: false, reason: 'already sent this week' };

  const m = await _ownerMetrics(env);
  if (!m) { return { sent: false, reason: 'metrics unavailable' }; }
  m._appUrl = env.APP_URL || env.APP_ORIGIN || '';

  let prev = null;
  try { prev = JSON.parse(await env.AMV_KV.get('digestsnap') || 'null'); } catch (e) { prev = null; }

  const d = _buildDigest(m, prev);
  const ok = await _sendEmail(env, to, d.subject, d.html, d.text, 'owner');
  if (!ok) {
    /* Nothing was delivered, so two things must not happen: this snapshot must
       not become the baseline for a week the owner never saw - that would
       quietly under-report the next change - and the week must not stay
       claimed, or one provider hiccup silently costs a whole digest. Give the
       week back and the next tick tries again. */
    await _releaseClaim(env, 'digest', week);
    audit(env, 'digest_failed', { week });
    await alertOnce(env, 'digest_fail', 'Weekly owner digest could not be delivered - the email provider rejected it.', 720);
    return { sent: false, reason: 'delivery failed', week };
  }
  // Stored only after a delivery that actually happened.
  await env.AMV_KV.put('digestsnap', JSON.stringify(d.snapshot), { expirationTtl: 120 * 86400 });
  audit(env, 'digest_sent', { week, signups7: d.snapshot.signups7, mrr: d.snapshot.mrr });
  return { sent: true, week, flags: d.flags.length };
}

/* GET/POST /admin/digest - preview it now, or send it now.

   Preview is the default and changes nothing. Sending is an outward-facing
   action, so it takes an explicit flag rather than happening because someone
   opened a URL. */
async function adminDigest(request, env) {
  { const g = await _adminGate(request, env, 'read', 60, 2000); if (g) return g; }
  const url = new URL(request.url);
  const send = url.searchParams.get('send') === '1';
  if (send) {
    /* Release this week's claim so an explicit request is honoured rather than
       silently swallowed by the once-a-week guard. Through the helper, because
       the claim lives in the Durable Object, D1 or KV depending on what is
       configured - deleting one KV key would miss it in two of three cases. */
    await _releaseClaim(env, 'digest', _weekKey());
    const r = await runWeeklyDigest(env);
    return json({ ok: !!r.sent, ...r });
  }
  const m = await _ownerMetrics(env);
  if (!m) return json({ error: 'metrics unavailable' }, 503);
  m._appUrl = env.APP_URL || env.APP_ORIGIN || '';
  let prev = null;
  try { prev = JSON.parse(await env.AMV_KV.get('digestsnap') || 'null'); } catch (e) {}
  const d = _buildDigest(m, prev);
  return json({ ok: true, preview: true, week: d.week, subject: d.subject,
                snapshot: d.snapshot, previous: d.previous, flags: d.flags, text: d.text });
}

// flip the global kill switch on/off
async function adminKill(request, env) {
  { const g = await _adminGate(request, env, 'read', 60, 2000); if (g) return g; }
  const { on } = await request.json().catch(() => ({}));
  if (on) await env.AMV_KV.put('GLOBAL_KILL', '1');
  else await env.AMV_KV.delete('GLOBAL_KILL');
  audit(env, 'admin_kill', { on: !!on });
  return json({ ok: true, killed: !!on });
}

// inspect one user, or override their plan (e.g. comp an account, stop abuse)
async function adminUser(request, env) {
  { const g = await _adminGate(request, env, 'read', 60, 2000); if (g) return g; }
  const body = await request.json().catch(() => ({}));
  const email = String(body.email || '').toLowerCase().trim();
  if (!email) return json({ error: 'email required' }, 400);
  const month = monthKey(), today = todayKey();

  if (body.action === 'setPlan' && body.plan) {
    await setEntitlement(env, email, body.plan, { source: 'admin' });
    audit(env, 'admin_set_plan', { email, plan: body.plan });
    return json({ ok: true, email, plan: body.plan });
  }
  if (body.action === 'revoke') {
    await revokeUserTokens(env, email);   // force re-login everywhere
    audit(env, 'admin_revoke', { email });
    return json({ ok: true, revoked: email });
  }
  // default: inspect
  const ent = await DB.get(env, 'ent', email);
  /* Read the counters this account actually spends against. A team member's own
     key is empty by design, and showing an operator three zeros for somebody who
     is using the product every day would be worse than showing nothing. */
  const sub = await _billingSubjectOf(env, email, ent);
  const monthCost = (await counter(env, `cost:${sub.subject}:${month}`, { op: 'get' })).value || 0;
  const monthTok = (await counter(env, `usg:${sub.subject}:${month}`, { op: 'get' })).value || 0;
  const dayTok = (await counter(env, `usg:${sub.subject}:${today}`, { op: 'get' })).value || 0;
  return json({
    ok: true, email,
    entitlement: ent || { plan: 'free' },
    team: sub.teamId ? { id: sub.teamId, role: sub.teamRole, plan: sub.plan, shared: sub.subject !== email } : null,
    usage: { dayTokens: dayTok, monthTokens: monthTok, monthCostUSD: +monthCost.toFixed(3),
             subject: sub.subject, shared: sub.subject !== email },
  });
}


/* Verify a Stripe webhook signature (the t=…,v1=… scheme: HMAC-SHA256 of
   "timestamp.payload" with the webhook secret). Constant-time compared. */
async function verifyStripeSignature(secret, payload, sigHeader) {
  try {
    if (!secret || !sigHeader) return false;
    /* Stripe sends EVERY valid signature, and during a webhook-secret rotation
       that is more than one v1. Object.fromEntries keeps only the last, so if
       the configured secret produced the first one, verification failed and
       real events were rejected as forged - sales uncredited, at exactly the
       moment somebody is rotating a secret. All of them are considered. */
    let t = '';
    const v1s = [];
    for (const kv of sigHeader.split(',')) {
      const eq = kv.indexOf('=');
      if (eq < 0) continue;
      const k = kv.slice(0, eq).trim(), v = kv.slice(eq + 1).trim();
      if (k === 't') t = v;
      else if (k === 'v1') v1s.push(v);
    }
    if (!t || !v1s.length) return false;
    // reject very old timestamps (replay protection, 5 min tolerance)
    if (Math.abs(Date.now() / 1000 - parseInt(t, 10)) > 300) return false;
    const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const mac = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(`${t}.${payload}`));
    const expected = Array.from(new Uint8Array(mac)).map(b => b.toString(16).padStart(2, '0')).join('');
    // constant-time compare against each offered signature
    let matched = false;
    for (const v1 of v1s) {
      if (expected.length !== v1.length) continue;
      let diff = 0;
      for (let i = 0; i < expected.length; i++) diff |= expected.charCodeAt(i) ^ v1.charCodeAt(i);
      if (diff === 0) matched = true;
    }
    return matched;
  } catch { return false; }
}

/* ---- PayPal: create a recurring SUBSCRIPTION (needs billing plan IDs) ----

   The only PayPal purchase route there is. A one-time ORDER pair used to sit
   here too (create + capture) and had to go: an order has no renewal, so the
   entitlement it granted had nothing that would ever expire or revoke it. One
   $15 payment bought Pro permanently, callable directly by any signed-in
   account. A subscription is the thing that keeps paying, and the webhook is
   what grants and revokes against it. */
async function paypalSubscribe(request, env) {
  const user = await requireUser(request, env);
  if (!user) return json({ error: 'unauthorized' }, 401);
  if (!env.PAYPAL_CLIENT_ID || !env.PAYPAL_SECRET)
    return json({ error: 'PayPal is not connected on this deployment yet, so it cannot be used to pay. Nothing has been charged.',
                  code: 'needs_service' }, 503);
  /* The same bound the card path has had all along, for the same reason: one
     account hammering this burns AMV's rate limit at PayPal, and the people
     who then cannot check out are everybody else. It was missing here because
     the rule that finds these knew Stripe's hostname and not PayPal's. */
  const pg = await guardAction(env, `paypalsub:${user.email}`, 10, 100, 'starting a subscription');
  if (pg) return pg;
  const { plan } = await request.json().catch(() => ({}));
  // PayPal subscriptions require a pre-created billing plan per tier. Map tier →
  // the plan id you set as a secret. If it's not set, say so honestly rather
  // than pretending to subscribe.
  const PLAN_IDS = { pro: env.PAYPAL_PLAN_PRO, elite: env.PAYPAL_PLAN_ELITE, ultra: env.PAYPAL_PLAN_ULTRA };
  const planId = PLAN_IDS[plan];
  if (!plan || !(plan in PLAN_IDS)) return json({ error: 'unknown plan' }, 400);
  if (!planId) return json({ error: 'PayPal subscriptions are not set up for this plan yet. Use card checkout.', code: 'paypal_sub_unconfigured' }, 503);

  const token = await _paypalToken(env);
  if (!token) return json({ error: 'paypal auth failed' }, 502);
  const appUrl = (env.APP_URL || '').replace(/\/$/, '');
  const r = await fetchDeadline(`${_paypalBase(env)}/v1/billing/subscriptions`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      plan_id: planId,
      custom_id: `${user.email}|${plan}`,
      application_context: {
        brand_name: 'AMV',
        user_action: 'SUBSCRIBE_NOW',
        return_url: appUrl ? `${appUrl}/?paypal_sub=success` : undefined,
        cancel_url: appUrl ? `${appUrl}/?paypal_sub=cancel` : undefined,
      },
    }),
  });
  const d = await r.json().catch(() => ({}));
  if (!r.ok) return json({ error: 'paypal subscribe failed' }, 502);
  // return the approval URL for the client to open
  const approve = (d.links || []).find(l => l.rel === 'approve');
  if (!approve) return json({ error: 'no approval url from paypal' }, 502);
  /* Same for PayPal: the subscription exists now, activation arrives later by
     webhook, and a lost activation is a customer paying for nothing. */
  await _pendStart(env, d.id, { provider:'paypal', email:user.email, plan });
  return json({ url: approve.href, id: d.id });
}

// ---- PayPal: capture an approved order, then grant entitlement ----
// ---- PayPal: webhook (for renewals/disputes/refunds) ----
async function paypalWebhook(request, env, ctx) {
  const raw = await request.text();
  // PayPal webhook verification requires an API call to /v1/notifications/verify-webhook-signature.
  const verified = await verifyPaypalWebhook(env, request.headers, raw);
  if (!verified) { audit(env, 'forged_webhook', { kind: 'paypal' }); return new Response('bad signature', { status: 400 }); }
  let evt; try { evt = JSON.parse(raw); } catch { return new Response('bad json', { status: 400 }); }
  /* AMV-201: the same exactly-once guarantee Stripe has had. PayPal redelivers
     an event until it gets a 200, and every redelivery was being processed
     again here. Most handlers happen to be idempotent, but "happens to be" is
     not a guarantee, and the two money paths should not have different ones.
     Released below if handling genuinely fails, so a real failure is still
     allowed to be retried. */
  if (evt.id && !(await _claimOnce(env, 'paypalevt', evt.id, CLAIM_ONCE_TTL_S))) {
    return new Response('ok', { status: 200 });
  }
  /* AMV-200: when it happened. PayPal gives no ordering guarantee either, so a
     retried older event can arrive after a newer one - a cancellation followed
     by a stale "still active" would put a cancelled customer back on a paid
     plan, free. */
  const evtAt = Date.parse(evt.create_time || evt.resource?.create_time || '') || Date.now();
  try {
    const custom = evt.resource?.custom_id || '';
    const [email, claimedPlan] = custom.split('|');
    /* AMV-007: which PayPal subscription this event is about. A subscription
       event IS the subscription; a sale names the agreement it was taken under.
       A refund of a one-off capture names neither, and correctly makes no
       ownership claim. */
    const ppSub = evt.resource?.billing_agreement_id
               || (/^BILLING\.SUBSCRIPTION\./.test(evt.event_type || '') ? (evt.resource?.id || '') : '')
               || '';
    if (evt.event_type === 'PAYMENT.CAPTURE.REFUNDED' || evt.event_type === 'BILLING.SUBSCRIPTION.CANCELLED'
        || evt.event_type === 'BILLING.SUBSCRIPTION.EXPIRED') {
      if (email) await setEntitlement(env, email.toLowerCase(), 'free', { source: 'paypal', canceled: true, eventAt: evtAt, sub: ppSub });
    } else if (evt.event_type === 'BILLING.SUBSCRIPTION.PAYMENT.FAILED'
            || evt.event_type === 'BILLING.SUBSCRIPTION.SUSPENDED') {
      // Same rule as Stripe: a failed payment does not buy another month.
      if (email) await _markPastDue(env, email.toLowerCase(), { provider: 'paypal', event: evt.event_type });
    } else if (evt.event_type === 'BILLING.SUBSCRIPTION.ACTIVATED'
            || evt.event_type === 'BILLING.SUBSCRIPTION.RE-ACTIVATED'
            || evt.event_type === 'PAYMENT.SALE.COMPLETED') {
      /* THE PLAN THEY PAID FOR, WHICH NOTHING HERE USED TO GRANT.

         This branch called _clearPastDue and stopped. _clearPastDue returns
         immediately when there is no pastDueSince - which is the state every
         NEW subscriber is in - so activation did nothing at all. The only
         setEntitlement on this whole path set the plan to 'free', on
         cancellation. custom_id has carried the tier since the day it was
         written and the line above discarded it.

         So PayPal took a recurring payment, every month, and the customer
         stayed on the free plan. Nothing errored, nothing was logged, and the
         one thing that would have caught it - somebody paying by PayPal - is
         not something the tests did. It is the worst shape a defect can have
         in this product: money in, nothing out, silently.

         The tier is taken from the plan PayPal is ACTUALLY billing wherever
         that is knowable, and only falls back to the echoed custom_id. Both
         arrive inside a signature-verified webhook, but one of them is what
         the customer is being charged for and the other is what a client
         claimed at checkout time - and if they ever disagree, the charge is
         the truth. */
      const em = String(email || '').toLowerCase();
      if (em) {
        const tier = _paypalTierOf(env, evt.resource?.plan_id, claimedPlan);
        if (tier) {
          const cur = await DB.get(env, 'ent', em);
          /* renewedAt moves on every successful payment, so the renewal sweep
             sees a live subscription rather than revoking one that is being
             paid for. */
          if (!cur || cur.plan !== tier || cur.pastDueSince) {
            await setEntitlement(env, em, tier, { source: 'paypal', eventAt: evtAt, sub: ppSub });
          } else {
            /* AMV-202: a renewal touch-up is still an entitlement write, and a
               webhook is exactly when another one is likely to be in flight. */
            await _withEnt(env, em, (rec) => {
              if (!rec) return null;
              rec.renewedAt = Date.now();
              delete rec.pastDueSince;
            });
          }
          audit(env, 'paypal_grant', { email: em, plan: tier, event: evt.event_type });
        } else {
          /* Paid, and AMV cannot tell what for. Never guess a tier - guessing
             high gives away product and guessing low shortchanges somebody who
             paid. It is a real failure and it needs a human. */
          audit(env, 'paypal_unmapped_plan', { email: em, planId: evt.resource?.plan_id || '', claimed: claimedPlan || '' });
          try { await alertOnce(env, 'paypal_unmapped',
            'A PayPal payment arrived for a plan AMV cannot map to a tier (plan_id: '
            + (evt.resource?.plan_id || 'none') + '). The customer has PAID and has NOT been granted anything. '
            + 'Check PAYPAL_PLAN_PRO / _ELITE / _ULTRA match the billing plans in PayPal.', 5); } catch (_) {}
        }
        await _clearPastDue(env, em);
        /* Finished the normal way, so the sweep has nothing to chase. The id is
           the subscription's, which is what _pendStart recorded. */
        await _pendDone(env, evt.resource?.id || '');
      }
    }
  } catch (e) {
    audit(env, 'webhook_error', { kind: 'paypal', msg: String(e.message).slice(0, 120) });
    /* AMV-008: RELEASING THE CLAIM IS HALF OF A RETRY. THE STATUS IS THE OTHER.

       This released the claim and then fell through to the 200 below, so PayPal
       recorded the delivery as handled and never sent it again. The comment
       here said "let PayPal's retry reprocess it" while the code was the reason
       no retry would come. A customer paid, processing threw, and they were
       charged with no plan - and nothing anywhere reported a failure.

       A webhook is acknowledged when the work is durable, never before. The
       claim goes back so the redelivery is not mistaken for a duplicate, and
       the status tells PayPal to send it. */
    if (evt.id) { try { await _releaseClaim(env, 'paypalevt', evt.id); } catch (_) {} }
    try { await alertOnce(env, 'paypal_webhook_failed',
      'A PayPal webhook failed to process and was returned for retry. Event '
      + (evt && evt.id ? evt.id : 'unknown') + ' type ' + (evt && evt.event_type ? evt.event_type : 'unknown')
      + '. If this repeats, a payment may be taken with no plan granted.', 15); } catch (_) {}
    return new Response('retry', { status: 503, headers: { ...CORS } });
  }
  return json({ received: true });
}

/* Which AMV tier a PayPal billing plan corresponds to.

   Prefers the plan id PayPal is really charging against, because that is what
   the customer's money is buying. The tier echoed back in custom_id is a
   fallback for events that do not carry a plan id, and is validated against the
   known tiers rather than trusted as a string - it round-trips through the
   client, and a tier is an entitlement. */
function _paypalTierOf(env, planId, claimed) {
  const byId = {
    [env.PAYPAL_PLAN_PRO || '\u0000none-pro']: 'pro',
    [env.PAYPAL_PLAN_ELITE || '\u0000none-elite']: 'elite',
    [env.PAYPAL_PLAN_ULTRA || '\u0000none-ultra']: 'ultra',
  };
  const fromId = planId ? byId[String(planId)] : null;
  if (fromId) return fromId;
  const c = String(claimed || '').toLowerCase();
  return (c === 'pro' || c === 'elite' || c === 'ultra') ? c : null;
}

function _paypalBase(env) { return env.PAYPAL_MODE === 'live' ? 'https://api-m.paypal.com' : 'https://api-m.sandbox.paypal.com'; }
async function _paypalToken(env) {
  try {
    const auth = btoa(`${env.PAYPAL_CLIENT_ID}:${env.PAYPAL_SECRET}`);
    const r = await fetchDeadline(`${_paypalBase(env)}/v1/oauth2/token`, {
      method: 'POST',
      headers: { 'Authorization': `Basic ${auth}`, 'Content-Type': 'application/x-www-form-urlencoded' },
      body: 'grant_type=client_credentials',
    });
    const d = await r.json();
    return d.access_token || null;
  } catch { return null; }
}
async function verifyPaypalWebhook(env, headers, body) {
  try {
    if (!env.PAYPAL_WEBHOOK_ID) return false;
    const token = await _paypalToken(env);
    if (!token) return false;
    const r = await fetchDeadline(`${_paypalBase(env)}/v1/notifications/verify-webhook-signature`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        auth_algo: headers.get('paypal-auth-algo'),
        cert_url: headers.get('paypal-cert-url'),
        transmission_id: headers.get('paypal-transmission-id'),
        transmission_sig: headers.get('paypal-transmission-sig'),
        transmission_time: headers.get('paypal-transmission-time'),
        webhook_id: env.PAYPAL_WEBHOOK_ID,
        webhook_event: _safeJson(body),
      }),
    });
    const d = await r.json();
    return d.verification_status === 'SUCCESS';
  } catch { return false; }
}


/* Password reset - emails a secure, time-limited link.
   Needs an email service (e.g. Resend, SendGrid, or AWS SES). Set the
   RESET_EMAIL_FROM secret and EMAIL_API_KEY; wire sendResetEmail() to your
   provider. Until then it stores a token so the flow is ready. */
async function authReset(request, env) {
  const body = await request.json().catch(() => ({}));
  const email = String(body.email || '').toLowerCase().trim();
  if (!email || !email.includes('@')) return json({ error: 'invalid email' }, 400);

  /* Bounded, and it was not. This route needs no credential of any kind and it
     causes an email to whatever address is typed into it - which is a mail
     bomber with AMV's return address on it, aimed at somebody who never signed
     up here, spending AMV's sending reputation and per-message cost on every
     shot. It also mints a KV record per call.

     Two limits, because they stop different things. Per ADDRESS stops one
     person being buried; per IP stops one caller working through a list. The
     per-address one is deliberately the tighter of the two: a real human who
     has lost their password asks once, maybe twice, and the second request is
     usually because the first email was slow.

     Both are counted BEFORE the token is minted and before anything is sent,
     and a refusal is the same shape as everywhere else - which also means it
     cannot be used to tell a real address from an unknown one, since the limit
     applies either way. */
  const perAddress = await guardAction(env, `reset:${email}`, 2, 6, 'password reset emails');
  if (perAddress) return perAddress;
  const ip = request.headers.get('CF-Connecting-IP') || '';
  if (ip) {
    const perIp = await guardAction(env, `resetip:${ip}`, 5, 30, 'password reset requests');
    if (perIp) return perIp;
  }

  // generate a one-time, 1-hour token
  const token = crypto.randomUUID().replace(/-/g, '') + crypto.randomUUID().replace(/-/g, '');
  await env.AMV_KV.put(`reset:${token}`, JSON.stringify({ email, at: Date.now() }), { expirationTtl: 3600 });
  const link = `${new URL(request.url).origin.replace(/\/$/, '')}/reset?token=${token}`;
  // send the email if a provider is configured; otherwise the flow is ready but no email goes out
  let sent = false;
  try { sent = await sendResetEmail(env, email, link); } catch (e) { /* provider not set up */ }
  // Always return ok:true to avoid leaking which emails exist (security best practice)
  return json({ ok: true, sent });
}

/* Complete a password reset: consume the one-time token and set a new password.
   The token is single-use and expires in 1 hour. The new password is hashed with
   PBKDF2-SHA256 and a fresh salt, so it's stored securely and no one can read it. */
async function authResetConfirm(request, env) {
  const body = await request.json().catch(() => ({}));
  const token = String(body.token || '').trim();
  const password = String(body.password || '');
  if (!token) return json({ error: 'missing token' }, 400);
  /* AMV-191: bounded, though the token is long and random rather than a
     guessable code - the six-digit path is separate and counts its own attempts.
     This is not about somebody brute-forcing their way in; it is that an
     unbounded route doing a storage read per call is a free way to hammer the
     store, and that every other door has a ceiling. Keyed per address so one
     source cannot spend everybody's. */
  const rcIp = (await _ipHash(env, request))
            || request.headers.get('CF-Connecting-IP')
            || request.headers.get('X-Forwarded-For') || 'unknown';
  const rcBlock = await guardAction(env, `resetconfirm:${rcIp}`, 10, 60, 'password resets');
  if (rcBlock) return rcBlock;
  { const bad = _passwordLengthProblem(password); if(bad) return json(bad, 400); }
  const stored = await env.AMV_KV.get(`reset:${token}`);
  if (!stored) return json({ error: 'This reset link is invalid or has expired. Please request a new one.' }, 400);
  /* Stored as {email, at}. The timestamp exists because erasure cannot reach
     this record - it is keyed by the token, and nothing maps an address back to
     the tokens issued for it. So a link outlives the account it was issued for,
     and if that address is registered again inside the hour, the link would
     name a DIFFERENT person's account. Refusing anything issued before the
     account existed closes that without needing to find the token. */
  let email = '', issuedAt = 0;
  try { const p = JSON.parse(stored); email = String(p.email || ''); issuedAt = +p.at || 0; }
  catch { email = String(stored || ''); }
  if (!email) return json({ error: 'This reset link is invalid or has expired. Please request a new one.' }, 400);
  const acct = await DB.get(env, 'acct', email);
  if (!acct) return json({ error: 'account not found' }, 404);
  if (issuedAt && acct.createdAt && acct.createdAt > issuedAt) {
    await env.AMV_KV.delete(`reset:${token}`);
    audit(env, 'reset_token_predates_account', { email });
    return json({ error: 'This reset link is invalid or has expired. Please request a new one.' }, 400);
  }
  /* Hash the new password with a fresh salt. This is deliberately slow, which
     is the point of it - and it is why the write that follows takes the record
     lock instead of writing back the copy read before the hashing started.
     AMV-196: anything else that touched this account in the meantime would be
     reverted, and in the other direction a login's iteration upgrade could put
     the OLD credential back after this said the reset worked. */
  const salt = crypto.randomUUID().replace(/-/g, '');
  const newHash = await _hashPassword(password, salt, PBKDF2_ITERATIONS);
  try {
    await _withAcct(env, email, (a) => {
      if (!a) return;
      a.pwHash = newHash; a.salt = salt; a.pwIter = PBKDF2_ITERATIONS;
      a.pwResetAt = Date.now();
    });
  } catch (e) {
    /* Not written, so do NOT consume the token - the link still works and they
       can try again. Saying it worked here is the failure that matters: they
       would walk away believing the old password no longer opens the account. */
    audit(env, 'password_reset_blocked', { email });
    return json({ error: 'Something else was changing this account just now, so the password was not changed. Please try again in a moment.', code: 'acct_busy' }, 503);
  }
  // consume the token (single-use) and revoke existing sessions for safety
  await env.AMV_KV.delete(`reset:${token}`);
  const _revoked = await _revokeOrSay(env, email, 'password_reset');
  audit(env, 'password_reset', { email, sessionsRevoked: _revoked });
  await _userEvent(env, request, email, 'password_changed');
  return json({ ok: true, sessionsRevoked: _revoked,
    note: _revoked ? undefined : 'Your password was changed, but AMV could not sign out sessions that were already open. Use "sign out everywhere" once things settle.' });
}

// Wire this to your email provider (Resend shown as an example).
async function sendResetEmail(env, to, link) {
  return _sendEmail_security(env, to, 'Reset your AMV password',
    _emailShell('Reset your password',
      `<p style="margin:0 0 22px;font-size:14px;line-height:1.65;color:#555">We received a request to reset your AMV password. Tap the button below to choose a new one. This link expires in <b>1 hour</b>.</p>`,
      { label: 'Reset my password', url: link },
      `<p style="margin:0 0 6px;font-size:12px;line-height:1.6;color:#999">Or paste this link into your browser:</p>`+
      `<p style="margin:0 0 22px;font-size:12px;line-height:1.6;color:#7c6cff;word-break:break-all">${link}</p>`+
      `<hr style="border:none;border-top:1px solid #eee;margin:0 0 18px"><p style="margin:0;font-size:12px;line-height:1.6;color:#999">If you didn't request this, you can safely ignore this email - your password won't change.</p>`,
      'This is an automated security email.'),
    `Reset your AMV password\n\nWe received a request to reset your password. Open this link to set a new one (it expires in 1 hour):\n${link}\n\nIf you didn't request this, you can safely ignore this email - your password won't change.\n\n- The AMV team`);
}

/* Notify a teammate that work was assigned to them. */
async function sendTaskAssignedEmail(env, to, { assignerName, taskTitle, priority, teamName, appUrl }) {
  const safeTitle = _escHtml(taskTitle || 'a task');
  const who = _escHtml(assignerName || 'A teammate');
  const team = _escHtml(teamName || 'your team');
  const prio = priority && priority !== 'normal' ? ` <span style="font-size:11px;color:${priority==='high'?'#d23':'#888'};font-weight:600">(${_escHtml(priority)} priority)</span>` : '';
  const link = appUrl || '';
  return _sendEmail_task(env, to, `${assignerName||'A teammate'} assigned you: ${taskTitle||'a task'}`,
    _emailShell('You\u2019ve been assigned work',
      `<p style="margin:0 0 18px;font-size:14px;line-height:1.65;color:#555">${who} assigned you a task in <b>${team}</b> on AMV:</p>`+
      `<div style="background:#f6f6f9;border:1px solid #ececf3;border-radius:10px;padding:16px;margin:0 0 22px"><div style="font-size:15px;font-weight:600;color:#15131f">${safeTitle}${prio}</div></div>`,
      link ? { label: 'Open in AMV', url: link } : null,
      `<p style="margin:0;font-size:12px;line-height:1.6;color:#999">You can view, update, and complete this task from the Team page in AMV.</p>`,
      'You received this because you\u2019re a member of this team on AMV.'),
    `${assignerName||'A teammate'} assigned you a task in ${teamName||'your team'} on AMV:\n\n"${taskTitle||'a task'}"${priority&&priority!=='normal'?' ('+priority+' priority)':''}\n\nOpen AMV to view and update it: ${link}\n\n- The AMV team`);
}

/* Generic Resend sender - one place that talks to the email provider. */
/* Resend gives every account a sender that needs NO domain verification:
   onboarding@resend.dev. It only delivers to the address that owns the Resend
   account - which is exactly what you need to recover YOUR OWN login on day one.
   For real users, set RESET_EMAIL_FROM to an address on a domain you've verified
   in Resend, or their mail will not arrive. */
const RESET_FROM_DEFAULT = 'AMV <onboarding@resend.dev>';

/* NOTHING CAPPED WHAT ONE PERSON COULD BE SENT.

   Every rate limit in this file is per ACTOR - how often you may do a thing.
   That is the right shape for cost, and for abuse of AMV. It is the wrong shape
   for abuse of a PERSON, and email is the one thing here that leaves the
   building and lands somewhere we do not control, on our domain, with our
   reputation on it.

   Three things were true at once:

     marketMessage is guarded at 300 messages a day and every one of them mails
     the recipient. The limit works exactly as written and the outcome is still
     three hundred emails into one stranger's inbox in a day.

     Team task assignment had no limit at all. Create, assign, delete, repeat.

     An Ultra account may run 100 automations at a ten-minute interval, each
     able to mail its result. That is fourteen thousand emails a day, all of
     them asked for, none of them counted.

   So the cap goes where every send already passes, in the dimension nothing
   else covers: how much mail one ADDRESS can be sent in a day. Classed, and
   each class holds its own budget, so a flood of task notifications can never
   spend the one a password reset needs.

   The numbers are backstops, not policy. `auto` sits well above a ten-minute
   watch running all day (144) so the feature somebody paid for still works,
   and well below the fan-out above.

   When the counter cannot be reached, security and owner mail still goes and
   notification mail is held. That is a deliberate split rather than one rule:
   an unenforceable cap is not a cap, which argues for refusing - but a reset
   code that cannot be sent is somebody locked out of their account by our
   outage, and every actor-side limit is still in force underneath. The operator
   is alerted either way. */
const EMAIL_DAY_CAP = {
  security: 10,   // reset codes and account security mail
  owner:    14,   // the operator's own digests
  message:  25,   // somebody messaged you on the marketplace
  task:     25,   // work landed on you in a team
  auto:    250,   // your own scheduled jobs, addressed to you, at your request
  other:    25,
};
const EMAIL_SENDS_WITHOUT_A_COUNTER = { security: true, owner: true };

async function _emailBudgetOk(env, cls, to) {
  const cap = EMAIL_DAY_CAP[cls] || EMAIL_DAY_CAP.other;
  const who = String(to || '').toLowerCase().trim();
  if (!who) return false;
  const r = await counter(env, `mailto:${cls}:${who}:${todayKey()}`,
                          { op: 'reserve', amount: 1, cap, ttlMs: 86400000 * 2 });
  if (r && r.unavailable) {
    audit(env, 'email_budget_unavailable', { cls, to: who });
    try {
      await alertOnce(env, 'email_budget',
        'The per-recipient email budget cannot be evaluated - the atomic counter is unavailable. ' +
        'Security and owner mail is still going out; notification mail is being held.', 15);
    } catch (e) { /* alerting must never break a send decision */ }
    return !!EMAIL_SENDS_WITHOUT_A_COUNTER[cls];
  }
  if (!r || !r.allowed) {
    audit(env, 'email_budget_block', { cls, cap, to: who });
    return false;
  }
  return true;
}

/* Thin, named entry points for the sends whose argument lists span many lines.
   The class is the first thing you read rather than a string trailing a
   template-literal body twenty lines down, which is where a class gets pasted
   wrong. */
const _sendEmail_security = (env, ...a) => _sendEmailAs(env, 'security', a);
const _sendEmail_message  = (env, ...a) => _sendEmailAs(env, 'message',  a);
const _sendEmail_task     = (env, ...a) => _sendEmailAs(env, 'task',     a);
function _sendEmailAs(env, cls, [to, subject, html, text]) {
  return _sendEmail(env, to, subject, html, text, cls);
}

async function _sendEmail(env, to, subject, html, text, cls) {
  if (!env.EMAIL_API_KEY) return false;
  if (!(await _emailBudgetOk(env, cls || 'other', to))) return false;
  const from = env.RESET_EMAIL_FROM || RESET_FROM_DEFAULT;
  try {
    const resp = await fetchDeadline('https://api.resend.com/emails', {
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + env.EMAIL_API_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({ from, to: [to], subject, html, text }),
    });
    return resp.ok;
  } catch (e) { return false; }
}

// minimal HTML escape for values interpolated into email markup
function _escHtml(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }

/* Shared branded email shell. body is trusted HTML; cta is {label,url} or null;
   extra is trusted HTML after the CTA; footnote is plain text.
   Inline styles only (clients strip <style>); table layout for compatibility. */
function _emailShell(heading, body, cta, extra, footnote) {
  const ctaHtml = cta ? `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 auto 24px"><tr><td style="border-radius:10px;background:#7c6cff">
    <a href="${cta.url}" style="display:inline-block;padding:13px 28px;font-size:14px;font-weight:600;color:#fff;text-decoration:none;border-radius:10px">${_escHtml(cta.label)}</a>
  </td></tr></table>` : '';
  return `<!doctype html><html><body style="margin:0;padding:0;background:#f4f4f7;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f7;padding:32px 0">
    <tr><td align="center">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:480px;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 1px 3px rgba(0,0,0,.08)">
        <tr><td style="background:#15131f;padding:28px 32px;text-align:center">
          <span style="display:inline-block;width:34px;height:34px;background:#7c6cff;border-radius:9px;color:#fff;font-weight:800;font-size:16px;line-height:34px;text-align:center">A</span>
          <div style="color:#fff;font-size:17px;font-weight:700;margin-top:10px;letter-spacing:-.3px">AMV</div>
        </td></tr>
        <tr><td style="padding:32px">
          <h1 style="margin:0 0 12px;font-size:20px;color:#15131f;letter-spacing:-.4px">${_escHtml(heading)}</h1>
          ${body}
          ${ctaHtml}
          ${extra || ''}
        </td></tr>
        <tr><td style="padding:18px 32px;background:#fafafa;text-align:center">
          <p style="margin:0;font-size:11px;color:#aaa">&copy; AMV &middot; ${_escHtml(footnote || '')}</p>
        </td></tr>
      </table>
    </td></tr>
  </table></body></html>`;
}

/* ═══════════════════════════════════════════════════════════════════════
   GLOBAL MAIL - every integration AMV shipped was American.

   Google, Microsoft 365, Slack, Discord, GitHub, Notion, Canvas. Somebody in
   Chengdu, Seoul, Warsaw or Sao Paulo opens the integrations page and finds
   nothing they use. That is not a marketing gap, it is the product being
   unusable for most of the world.

   Mail is the one that can be fixed properly, because it is the one built on
   an open protocol. QQ Mail, NetEase 163, Naver, Yandex, GMX, Libero, Seznam,
   WP.pl, Rediffmail, UOL and the rest all speak IMAP and SMTP, and all of them
   issue an app password for exactly this. So AMV does not need a partnership
   or an API key from any of them - it needs to speak the protocol, once, and
   then it works everywhere.

   What is deliberately NOT here: WeChat has no API for personal accounts and
   automating one gets it banned; Wallapop has no public API at all. Both were
   asked for. Shipping a fake version of either would break the rule that
   nothing in AMV pretends to work, so they are absent and said out loud rather
   than half-built.
   ═══════════════════════════════════════════════════════════════════════ */

/* WHERE EACH PROVIDER LIVES, AND HOW A PERSON GETS IN.

   `setup` is not documentation padding - it is the field that decides whether
   this feature works for a real person. Every one of these providers uses a
   different word for the same thing and hides it in a different place: QQ
   calls it an authorisation code and puts it behind an SMS check, 163 calls it
   a client authorisation password, Naver makes you switch IMAP on first. A
   person who pastes their ordinary login password gets a failure that looks
   like a bug in AMV, so the instruction has to be right there at the moment
   they are asked for it. */
